/* Logo + hamburger no cabeçalho da sidebar. */
.prazzu-sidebar-brand-wrap {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
}

.prazzu-sidebar-brand {
    min-width: 0;
    display: inline-flex;
    align-items: center;
    overflow: hidden;
}

.fi-logo img,
.prazzu-sidebar-brand-img {
    object-fit: contain;
    max-height: 42px;
    max-width: 150px;
    transition: opacity .2s ease, width .2s ease, max-width .2s ease;
}

.prazzu-sidebar-toggle {
    width: 38px;
    height: 38px;
    min-width: 38px;
    border: 1px solid rgba(253, 134, 5, .22);
    border-radius: 12px;
    background: rgba(253, 134, 5, .08);
    color: var(--prazzu-secondary);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: background .18s ease, color .18s ease, border-color .18s ease, transform .18s ease;
}

.prazzu-sidebar-toggle:hover {
    background: var(--prazzu-primary);
    border-color: var(--prazzu-primary);
    color: #ffffff;
    transform: translateY(-1px);
}

.prazzu-sidebar-toggle-bars {
    width: 18px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.prazzu-sidebar-toggle-bars span {
    display: block;
    height: 2px;
    width: 100%;
    border-radius: 999px;
    background: currentColor;
}

.fi-sidebar-item-active a,
.fi-sidebar-item a:hover {
    background: rgba(253, 134, 5, 0.1);
    color: var(--prazzu-secondary);
}

.fi-ta-record {
    transition: background-color 0.18s ease, box-shadow 0.18s ease;
}

.fi-ta-record:hover {
    background: rgba(253, 134, 5, 0.035);
}

.fi-ta-actions {
    gap: 0.35rem;
}

.fi-dropdown-panel {
    border-radius: 0.95rem;
    border-color: rgba(6, 55, 109, 0.12);
    box-shadow: 0 16px 38px rgba(6, 55, 109, 0.14);
}

/* Conteúdo: expande/recolhe com a sidebar, mas mantém respiro nas bordas e limite em telas gigantes. */
.fi-main,
.fi-main-ctn,
.fi-page {
    width: 100% !important;
}

.fi-main-ctn {
    padding: clamp(10px, 1vw, 18px) !important;
}

.fi-page {
    width: 100% !important;
    max-width: var(--prazzu-content-max) !important;
    margin-inline: auto !important;
}

@media (min-width: 1900px) {
    .fi-page {
        max-width: 1760px !important;
    }
}

/* Scroll da sidebar funcional, mas sem barra visível. */
.fi-sidebar,
.fi-sidebar-nav {
    overflow-y: auto !important;
    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
}

.fi-sidebar::-webkit-scrollbar,
.fi-sidebar-nav::-webkit-scrollbar {
    width: 0 !important;
    height: 0 !important;
    display: none !important;
}

@media (max-width: 1024px) {
    .prazzu-sidebar-toggle {
        display: inline-flex !important;
    }
}


@media (max-width: 768px) {
    .fi-topbar-ctn {
        top: 10px !important;
        right: 12px !important;
    }

    .fi-topbar-end {
        padding: 5px !important;
    }
}

/* =========================================================
   V9 - Correção do menu de usuário cortado + hamburger mobile
   ========================================================= */

/* A topbar continua sem aparecer como barra branca, mas agora ocupa a largura
   lógica da tela para o Floating UI calcular corretamente a posição dos dropdowns. */
.fi-topbar-ctn {
    left: 0 !important;
    right: 0 !important;
    top: 0 !important;
    width: 100vw !important;
    height: 0 !important;
    min-height: 0 !important;
    overflow: visible !important;
    background: transparent !important;
    border: 0 !important;
    box-shadow: none !important;
    z-index: 99980 !important;
    pointer-events: none !important;
}

.fi-topbar {
    position: relative !important;
    display: flex !important;
    align-items: flex-start !important;
    justify-content: flex-end !important;
    width: 100vw !important;
    height: 0 !important;
    min-height: 0 !important;
    overflow: visible !important;
    padding: 0 !important;
    margin: 0 !important;
    border: 0 !important;
    box-shadow: none !important;
    pointer-events: none !important;
}

.fi-topbar > :not(.fi-topbar-end) {
    display: none !important;
}

.fi-topbar-end {
    position: fixed !important;
    top: 14px !important;
    right: 18px !important;
    z-index: 99990 !important;
    pointer-events: auto !important;
}

/* Evita que dropdowns/flutuantes do Filament sejam cortados por wrappers do layout. */
html,
body,
.fi-body,
.fi-layout,
.fi-layout > *,
.fi-main,
.fi-main-ctn,
.fi-page,
.fi-topbar-ctn,
.fi-topbar,
.fi-topbar-end {
    overflow: visible !important;
}

body {
    overflow-x: hidden !important;
    overflow-y: auto !important;
}

/* O painel do usuário/logout deve sempre ficar por cima e dentro da tela.
   Este seletor corrige especificamente o caso em que o Floating UI calcula left negativo. */
.fi-dropdown-panel {
    z-index: 1000000 !important;
    max-width: calc(100vw - 24px) !important;
}

.fi-dropdown-panel[style*="left: -"] {
    left: auto !important;
    right: 12px !important;
}

/* Mantém a sidebar com scroll invisível e funcional mesmo depois de liberar overflow geral. */
.fi-sidebar,
.fi-sidebar-nav {
    overflow-x: hidden !important;
    overflow-y: auto !important;
    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
}

.fi-sidebar::-webkit-scrollbar,
.fi-sidebar-nav::-webkit-scrollbar {
    width: 0 !important;
    height: 0 !important;
    display: none !important;
}

/* Mobile: reaparece somente a área do hamburger da topbar para abrir a sidebar.
   A barra branca continua removida. */
@media (max-width: 1024px) {
    .fi-topbar-ctn {
        height: 0 !important;
        min-height: 0 !important;
        pointer-events: none !important;
    }

    .fi-topbar {
        justify-content: space-between !important;
        pointer-events: none !important;
    }

    .fi-topbar > :not(.fi-topbar-end) {
        position: fixed !important;
        top: 10px !important;
        left: 12px !important;
        z-index: 99990 !important;
        display: inline-flex !important;
        align-items: center !important;
        justify-content: center !important;
        width: auto !important;
        min-width: 44px !important;
        height: 44px !important;
        padding: 0 !important;
        border: 1px solid rgba(6, 55, 109, .10) !important;
        border-radius: 999px !important;
        background: rgba(255, 255, 255, .94) !important;
        box-shadow: 0 12px 30px rgba(6, 55, 109, .14) !important;
        backdrop-filter: blur(12px) !important;
        pointer-events: auto !important;
    }

    .dark .fi-topbar > :not(.fi-topbar-end) {
        border-color: rgba(255, 255, 255, .10) !important;
        background: rgba(15, 23, 42, .90) !important;
        box-shadow: 0 12px 30px rgba(0, 0, 0, .30) !important;
    }

    .fi-topbar-end {
        top: 10px !important;
        right: 12px !important;
    }

    .fi-dropdown-panel[style*="left: -"] {
        left: 12px !important;
        right: 12px !important;
        width: auto !important;
        max-width: calc(100vw - 24px) !important;
    }

    .fi-main-ctn {
        padding-top: 68px !important;
    }
}

/* =========================================================
   V10 - Responsivo mobile sem quebrar o desktop aprovado
   ========================================================= */

@media (max-width: 1023.98px) {
    /* No mobile a sidebar NÃO pode herdar o modo compactado do desktop. */
    .fi-sidebar {
        width: min(20rem, calc(100vw - 32px)) !important;
        min-width: min(20rem, calc(100vw - 32px)) !important;
        max-width: min(20rem, calc(100vw - 32px)) !important;
        flex-basis: auto !important;
        height: 100dvh !important;
        max-height: 100dvh !important;
        top: 0 !important;
        z-index: 99995 !important;
    }

    /* Mobile precisa de uma barra real para o hamburger nativo do Filament funcionar.
       Ela aparece só no mobile e não interfere na sidebar 100% do desktop. */
    .fi-topbar-ctn {
        position: sticky !important;
        top: 0 !important;
        left: 0 !important;
        right: 0 !important;
        width: 100% !important;
        height: 64px !important;
        min-height: 64px !important;
        overflow: visible !important;
        z-index: 99980 !important;
        pointer-events: auto !important;
        background: transparent !important;
    }

    .fi-topbar {
        position: relative !important;
        display: flex !important;
        align-items: center !important;
        justify-content: space-between !important;
        width: 100% !important;
        height: 64px !important;
        min-height: 64px !important;
        padding: 10px 12px !important;
        margin: 0 !important;
        overflow: visible !important;
        border: 0 !important;
        box-shadow: none !important;
        pointer-events: auto !important;
    }

    .fi-topbar::before {
        content: '';
        position: fixed;
        top: 8px;
        left: 10px;
        right: 10px;
        height: 48px;
        border: 1px solid rgba(6, 55, 109, .10);
        border-radius: 18px;
        background: rgba(255, 255, 255, .94);
        box-shadow: 0 10px 26px rgba(6, 55, 109, .12);
        backdrop-filter: blur(12px);
        pointer-events: none;
        z-index: -1;
    }

    .dark .fi-topbar::before {
        border-color: rgba(255, 255, 255, .10);
        background: rgba(15, 23, 42, .92);
        box-shadow: 0 10px 26px rgba(0, 0, 0, .32);
    }

    .fi-topbar > :not(.fi-topbar-end) {
        position: static !important;
        display: flex !important;
        align-items: center !important;
        justify-content: flex-start !important;
        width: auto !important;
        min-width: 44px !important;
        height: 44px !important;
        padding: 0 !important;
        border: 0 !important;
        background: transparent !important;
        box-shadow: none !important;
        pointer-events: auto !important;
        z-index: 1 !important;
    }

    .fi-topbar button,
    .fi-topbar a {
        pointer-events: auto !important;
    }

    .fi-topbar-end {
        position: static !important;
        display: inline-flex !important;
        align-items: center !important;
        justify-content: flex-end !important;
        gap: 6px !important;
        width: auto !important;
        min-width: 0 !important;
        padding: 0 !important;
        border: 0 !important;
        background: transparent !important;
        box-shadow: none !important;
        backdrop-filter: none !important;
        pointer-events: auto !important;
        z-index: 1 !important;
    }

    .fi-main,
    .fi-main-ctn,
    .fi-page {
        width: 100% !important;
        max-width: 100% !important;
        overflow-x: hidden !important;
    }

    .fi-main-ctn {
        padding: 10px !important;
        padding-top: 10px !important;
    }

    .fi-page {
        padding-inline: 0 !important;
        margin-inline: 0 !important;
    }

    /* Dropdown do usuário sempre dentro da tela no mobile. */
    .fi-dropdown-panel {
        max-width: calc(100vw - 20px) !important;
        z-index: 1000000 !important;
    }

    .fi-dropdown-panel[style*="left: -"],
    .fi-dropdown-panel[style*="right:"] {
        left: 10px !important;
        right: 10px !important;
        width: auto !important;
    }
}

/* =========================================================
   V11 - Mobile: remove o X externo e usa o hamburger interno
   ========================================================= */

@media (max-width: 1023.98px) {
    /* Remove apenas o botão X que aparece fora/na topbar quando o menu mobile está aberto. */
    .fi-topbar-close-sidebar-btn,
    .fi-topbar-close-collapse-sidebar-btn {
        display: none !important;
        opacity: 0 !important;
        visibility: hidden !important;
        pointer-events: none !important;
    }

    /* Garante que o hamburger interno da sidebar fique clicável acima do overlay. */
    .fi-sidebar .prazzu-sidebar-toggle {
        position: relative !important;
        z-index: 1000001 !important;
        display: inline-flex !important;
        pointer-events: auto !important;
        touch-action: manipulation !important;
    }

    .fi-sidebar .prazzu-sidebar-brand-wrap {
        position: relative !important;
        z-index: 1000001 !important;
        pointer-events: auto !important;
    }
}

