/* =========================
   ANIMAÇÃO SUAVE SIDEBAR
   ========================= */

/* Transição da largura da sidebar */
.fi-sidebar {
    transition: width 0.25s ease, min-width 0.25s ease, max-width 0.25s ease;
}

/* Transição do conteúdo acompanhando */
.fi-main,
.fi-main-ctn,
.fi-page {
    transition: all 0.2s ease;
}

/* Transição dos itens internos */
.fi-sidebar-item-label,
.fi-sidebar-group-label,
.fi-sidebar a,
.fi-sidebar button {
