/* ==========================================================
   White Label - Overrides globais para componentes nativos
   Filament / FilePond / botões de ação
   Mantém os componentes internos obedecendo as cores configuradas
   no White Label, inclusive quando o Filament usa classes como
   fi-color-warning, fi-bg-color-400 e filepond--label-action.
   ========================================================== */
:root {
    --pzu-button: var(--wl-button, var(--pzu-primary));
    --pzu-button-dark: var(--wl-button-dark, var(--pzu-primary-dark));
    --pzu-button-soft: var(--wl-button-soft, var(--pzu-primary-soft));
    --pzu-button-text: var(--wl-button-text, #ffffff);
    --pzu-button-rgb: var(--wl-button-rgb, 109, 45, 246);
    --pzu-accent: var(--wl-accent, var(--pzu-success));
    --pzu-accent-dark: var(--wl-accent-dark, var(--pzu-success));
    --pzu-accent-soft: var(--wl-accent-soft, var(--pzu-success-soft));
}

/* Botões do Filament: primary, warning, success, info, gray e action buttons */
.fi-btn.fi-color-primary,
.fi-btn.fi-color-warning,
.fi-btn.fi-color-success,
.fi-btn.fi-color-info,
.fi-btn.fi-color-gray,
.fi-btn.fi-color-custom,
.fi-ac-btn-action.fi-color-primary,
.fi-ac-btn-action.fi-color-warning,
.fi-ac-btn-action.fi-color-success,
.fi-ac-btn-action.fi-color-info,
.fi-ac-btn-action.fi-color-gray,
.fi-ac-btn-action.fi-color-custom,
button.fi-btn.fi-color-primary,
button.fi-btn.fi-color-warning,
button.fi-btn.fi-color-success,
button.fi-btn.fi-color-info,
button.fi-btn.fi-color-gray,
button.fi-btn.fi-color-custom,
button.fi-btn.fi-ac-btn-action,
button[type="submit"].fi-btn,
.fi-btn-color-primary,
.fi-btn-color-warning,
.fi-btn-color-success,
.fi-btn-color-info,
.fi-btn-color-gray {
    background: linear-gradient(135deg, var(--pzu-button), var(--pzu-button-dark)) !important;
    border-color: var(--pzu-button) !important;
    color: var(--pzu-button-text) !important;
    box-shadow: 0 14px 30px rgba(var(--pzu-button-rgb), .24) !important;
}

.fi-btn.fi-color-primary:hover,
.fi-btn.fi-color-warning:hover,
.fi-btn.fi-color-success:hover,
.fi-btn.fi-color-info:hover,
.fi-btn.fi-color-gray:hover,
.fi-btn.fi-color-custom:hover,
.fi-ac-btn-action.fi-color-primary:hover,
.fi-ac-btn-action.fi-color-warning:hover,
.fi-ac-btn-action.fi-color-success:hover,
.fi-ac-btn-action.fi-color-info:hover,
.fi-ac-btn-action.fi-color-gray:hover,
.fi-ac-btn-action.fi-color-custom:hover,
button.fi-btn.fi-ac-btn-action:hover,
button[type="submit"].fi-btn:hover {
    background: linear-gradient(135deg, var(--pzu-button-dark), var(--pzu-button)) !important;
    border-color: var(--pzu-button-dark) !important;
    color: var(--pzu-button-text) !important;
    filter: brightness(.98);
}

.fi-btn.fi-color-primary svg,
.fi-btn.fi-color-warning svg,
.fi-btn.fi-color-success svg,
.fi-btn.fi-color-info svg,
.fi-btn.fi-color-gray svg,
.fi-btn.fi-color-custom svg,
.fi-ac-btn-action svg,
button.fi-btn.fi-ac-btn-action svg,
button[type="submit"].fi-btn svg {
    color: currentColor !important;
    stroke: currentColor !important;
}

/* Variantes outline/ghost continuam leves, mas usando a cor dos botões */
.fi-btn.fi-outlined,
.fi-btn.fi-color-primary.fi-outlined,
.fi-btn.fi-color-warning.fi-outlined,
.fi-btn.fi-color-success.fi-outlined,
.fi-btn.fi-color-info.fi-outlined,
.fi-btn.fi-color-gray.fi-outlined {
    background: color-mix(in srgb, var(--pzu-button) 8%, transparent) !important;
    border-color: color-mix(in srgb, var(--pzu-button) 28%, transparent) !important;
    color: var(--pzu-button-dark) !important;
    box-shadow: none !important;
}

/* Links de ação e botões pequenos dentro de formulários/tabelas */
.fi-link,
.fi-link:hover,
.fi-ta-actions .fi-btn,
.fi-form-actions .fi-btn,
.fi-modal-footer-actions .fi-btn,
.fi-page-header-actions .fi-btn,
.fi-header-actions .fi-btn {
    border-color: color-mix(in srgb, var(--pzu-button) 24%, transparent) !important;
}

.fi-link,
.fi-link:hover,
.fi-tabs-item-active,
.fi-tabs-item:hover,
.fi-section-header-icon,
.fi-ta-text-item-label {
    color: var(--wl-primary, var(--pzu-primary)) !important;
}

/* FilePond / upload de arquivos */
.filepond--label-action,
.filepond--file-action-button,
.filepond--file-status,
.filepond--credits,
.filepond--root .filepond--drop-label label strong,
.filepond--root .filepond--drop-label label span {
    color: var(--wl-primary, var(--pzu-primary)) !important;
}

.filepond--label-action {
    border-bottom-color: var(--wl-primary, var(--pzu-primary)) !important;
    text-decoration-color: var(--wl-primary, var(--pzu-primary)) !important;
    font-weight: 800 !important;
}

.filepond--label-action:hover {
    color: var(--pzu-button, var(--wl-primary, var(--pzu-primary))) !important;
    border-bottom-color: var(--pzu-button, var(--wl-primary, var(--pzu-primary))) !important;
}

.filepond--panel-root {
    border-color: color-mix(in srgb, var(--wl-primary, var(--pzu-primary)) 22%, transparent) !important;
}

.filepond--drop-label {
    color: var(--pzu-muted) !important;
}

.filepond--file {
    background: linear-gradient(135deg, var(--pzu-button), var(--pzu-button-dark)) !important;
    color: var(--pzu-button-text) !important;
}

/* Estados de foco/seleção usando a cor primária do white label */
.fi-input:focus,
.fi-select-input:focus,
.fi-textarea:focus,
.fi-checkbox-input:focus,
.fi-radio-input:focus,
.filepond--root:focus-within {
    border-color: var(--wl-primary, var(--pzu-primary)) !important;
    box-shadow: 0 0 0 4px rgba(var(--wl-primary-rgb, 109, 45, 246), .14) !important;
}

/* =========================================================
   White Label - Correção de prioridade para utilitários Filament
   =========================================================
   O Filament usa variáveis internas (--color-*, --bg, --text, --border)
   em classes como .fi-bg-color-600 e .fi-tabs-item.fi-active.
   Estes overrides conectam essas variáveis aos tokens do White Label.
*/
.fi-color-primary,
.fi-color-warning,
.fi-color-success,
.fi-color-info,
.fi-color-danger,
.fi-color-gray,
.fi-color-custom,
.fi-btn,
.fi-btn.fi-color-primary,
.fi-btn.fi-color-warning,
.fi-btn.fi-color-success,
.fi-btn.fi-color-info,
.fi-btn.fi-color-danger,
.fi-btn.fi-color-gray,
.fi-btn.fi-color-custom,
.fi-ac-btn-action,
.fi-tabs-item,
.fi-tabs-item.fi-active,
.fi-tabs-item[aria-selected="true"],
.fi-dropdown-list-item,
.fi-ta-actions .fi-btn,
.fi-form-actions .fi-btn,
.fi-modal-footer-actions .fi-btn,
.fi-page-header-actions .fi-btn {
    --color-50: var(--wl-button-soft, var(--pzu-button-soft)) !important;
    --color-100: var(--wl-button-soft, var(--pzu-button-soft)) !important;
    --color-200: var(--wl-button-soft, var(--pzu-button-soft)) !important;
    --color-300: var(--wl-button, var(--pzu-button)) !important;
    --color-400: var(--wl-button, var(--pzu-button)) !important;
    --color-500: var(--wl-button, var(--pzu-button)) !important;
    --color-600: var(--wl-button, var(--pzu-button)) !important;
    --color-700: var(--wl-button-dark, var(--pzu-button-dark)) !important;
    --color-800: var(--wl-button-dark, var(--pzu-button-dark)) !important;
    --color-900: var(--wl-button-text, var(--pzu-button-text)) !important;
    --color-950: var(--wl-button-text, var(--pzu-button-text)) !important;
}

.fi-bg-color-300,
.fi-bg-color-400,
.fi-bg-color-500,
.fi-bg-color-600,
.fi-bg-color-700,
.hover\:fi-bg-color-300:hover,
.hover\:fi-bg-color-400:hover,
.hover\:fi-bg-color-500:hover,
.hover\:fi-bg-color-600:hover,
.dark\:fi-bg-color-500:is(.dark *),
.dark\:fi-bg-color-600:is(.dark *),
.dark\:hover\:fi-bg-color-500:hover:is(.dark *),
.dark\:hover\:fi-bg-color-600:hover:is(.dark *) {
    --bg: var(--wl-button, var(--pzu-button)) !important;
    background-color: var(--wl-button, var(--pzu-button)) !important;
    background-image: linear-gradient(135deg, var(--wl-button, var(--pzu-button)), var(--wl-button-dark, var(--pzu-button-dark))) !important;
    color: var(--wl-button-text, var(--pzu-button-text)) !important;
}

.fi-text-color-800,
.fi-text-color-900,
.fi-text-color-950,
.hover\:fi-text-color-800:hover,
.hover\:fi-text-color-900:hover,
.dark\:fi-text-color-950:is(.dark *),
.dark\:hover\:fi-text-color-950:hover:is(.dark *) {
    --text: var(--wl-button-text, var(--pzu-button-text)) !important;
    color: var(--wl-button-text, var(--pzu-button-text)) !important;
}

.fi-tabs,
.fi-tabs-item,
.fi-tabs-item.fi-active,
.fi-tabs-item[aria-selected="true"] {
    --color-400: var(--wl-primary, var(--pzu-primary)) !important;
    --color-500: var(--wl-primary, var(--pzu-primary)) !important;
    --color-600: var(--wl-primary, var(--pzu-primary)) !important;
    --color-700: var(--wl-primary-dark, var(--pzu-primary-dark)) !important;
}

.fi-tabs-item.fi-active,
.fi-tabs-item[aria-selected="true"] {
    background: color-mix(in srgb, var(--wl-primary, var(--pzu-primary)) 10%, transparent) !important;
    border-color: color-mix(in srgb, var(--wl-primary, var(--pzu-primary)) 22%, transparent) !important;
    box-shadow: inset 0 -2px 0 var(--wl-primary, var(--pzu-primary)) !important;
}

.fi-tabs-item.fi-active .fi-tabs-item-label,
.fi-tabs-item.fi-active .fi-icon,
.fi-tabs-item[aria-selected="true"] .fi-tabs-item-label,
.fi-tabs-item[aria-selected="true"] .fi-icon,
.fi-tabs-item.fi-active svg,
.fi-tabs-item[aria-selected="true"] svg {
    color: var(--wl-primary, var(--pzu-primary)) !important;
    stroke: currentColor !important;
}

.fi-tabs-item:hover .fi-tabs-item-label,
.fi-tabs-item:hover .fi-icon,
.fi-tabs-item:hover svg {
    color: var(--wl-primary-dark, var(--pzu-primary-dark)) !important;
}


/* Portal do Cliente - login público (Lote 7) */
body.portal-cliente-login {
            min-height: 100vh;
            margin: 0;
            font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
            color: var(--prazzu-text, #111827);
            background:
                radial-gradient(circle at 12% 18%, rgba(37, 99, 235, .28), transparent 28rem),
                radial-gradient(circle at 82% 4%, rgba(253, 134, 5, .20), transparent 24rem),
                linear-gradient(135deg, #020617 0%, #06376d 48%, #0f172a 100%);
        }

        .portal-login-shell {
            min-height: 100vh;
            display: grid;
            grid-template-columns: minmax(0, 1.1fr) minmax(380px, 520px);
            gap: 40px;
            align-items: center;
            max-width: 1240px;
            margin: 0 auto;
            padding: 48px 24px;
            box-sizing: border-box;
        }

        .portal-login-brand {
            color: #fff;
        }

        .portal-login-logo {
            width: 64px;
            height: 64px;
            display: grid;
            place-items: center;
            border-radius: 22px;
            background: linear-gradient(135deg, rgba(255, 255, 255, .96), rgba(147, 197, 253, .28));
            box-shadow: 0 24px 70px rgba(0, 0, 0, .28);
            color: #06376d;
            font-size: 30px;
            margin-bottom: 28px;
        }

        .portal-login-brand h1 {
            max-width: 720px;
            margin: 0 0 16px;
            font-size: clamp(2.1rem, 5vw, 4.8rem);
            line-height: .98;
            letter-spacing: -.06em;
            font-weight: 900;
        }

        .portal-login-brand p {
            max-width: 620px;
            margin: 0;
            color: rgba(255, 255, 255, .78);
            font-size: 1.08rem;
            line-height: 1.8;
        }

        .portal-login-highlights {
            display: grid;
            grid-template-columns: repeat(3, minmax(0, 1fr));
            gap: 14px;
            max-width: 680px;
            margin-top: 34px;
        }

        .portal-login-highlight {
            padding: 18px;
            border: 1px solid rgba(255, 255, 255, .14);
            border-radius: 22px;
            background: rgba(255, 255, 255, .08);
            backdrop-filter: blur(14px);
            color: rgba(255, 255, 255, .86);
            font-size: .9rem;
            line-height: 1.45;
        }

        .portal-login-highlight strong {
            display: block;
            margin-bottom: 6px;
            color: #fff;
            font-size: 1rem;
        }

        .portal-login-card {
            width: 100%;
            border: 1px solid rgba(255, 255, 255, .48);
            border-radius: 30px;
            background: rgba(255, 255, 255, .96);
            box-shadow: 0 30px 90px rgba(2, 6, 23, .35);
            overflow: hidden;
        }

        .portal-login-card-header {
            padding: 34px 34px 20px;
            border-bottom: 1px solid rgba(15, 23, 42, .08);
        }

        .portal-login-card-header span {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            margin-bottom: 12px;
            padding: 7px 12px;
            border-radius: 999px;
            color: #065f46;
            background: #d1fae5;
            font-size: .78rem;
            font-weight: 800;
        }

        .portal-login-card-header h2 {
            margin: 0 0 8px;
            color: #0f172a;
            font-size: 1.75rem;
            letter-spacing: -.03em;
        }

        .portal-login-card-header p {
            margin: 0;
            color: #64748b;
            line-height: 1.6;
        }

        .portal-login-form {
            display: grid;
            gap: 18px;
            padding: 28px 34px 34px;
        }

        .portal-login-alert {
            padding: 14px 16px;
            border-radius: 16px;
            border: 1px solid #fecaca;
            color: #991b1b;
            background: #fef2f2;
            font-size: .92rem;
            line-height: 1.5;
        }

        .portal-login-success {
            padding: 14px 16px;
            border-radius: 16px;
            border: 1px solid #bbf7d0;
            color: #166534;
            background: #f0fdf4;
            font-size: .92rem;
        }

        .portal-login-field {
            display: grid;
            gap: 8px;
        }

        .portal-login-field label {
            color: #0f172a;
            font-size: .9rem;
            font-weight: 800;
        }

        .portal-login-field input[type="email"],
        .portal-login-field input[type="password"] {
            width: 100%;
            box-sizing: border-box;
            border: 1px solid #dbe3ef;
            border-radius: 18px;
            background: #f8fafc;
            padding: 15px 16px;
            color: #0f172a;
            font-size: 1rem;
            outline: none;
            transition: border-color .18s ease, box-shadow .18s ease, background .18s ease;
        }

        .portal-login-field input:focus {
            border-color: #2563eb;
            background: #fff;
            box-shadow: 0 0 0 4px rgba(37, 99, 235, .12);
        }

        .portal-login-error {
            color: #dc2626;
            font-size: .82rem;
            font-weight: 700;
        }

        .portal-login-options {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 16px;
            color: #475569;
            font-size: .9rem;
        }

        .portal-login-options label {
            display: inline-flex;
            align-items: center;
            gap: 9px;
            cursor: pointer;
        }

        .portal-login-button {
            display: inline-flex;
            justify-content: center;
            align-items: center;
            gap: 10px;
            width: 100%;
            border: 0;
            border-radius: 18px;
            background: linear-gradient(135deg, #06376d, #0b4ea2);
            color: #fff;
            padding: 15px 18px;
            font-size: 1rem;
            font-weight: 900;
            cursor: pointer;
            box-shadow: 0 18px 40px rgba(6, 55, 109, .28);
            transition: transform .18s ease, box-shadow .18s ease;
        }

        .portal-login-button:hover {
            transform: translateY(-1px);
            box-shadow: 0 22px 48px rgba(6, 55, 109, .34);
        }

        .portal-login-footer {
            padding-top: 4px;
            color: #64748b;
            text-align: center;
            font-size: .86rem;
            line-height: 1.5;
        }

        .portal-login-footer strong {
            color: #0f172a;
        }

        @media (max-width: 980px) {
            .portal-login-shell {
                grid-template-columns: 1fr;
                gap: 28px;
                padding: 28px 16px;
            }

            .portal-login-brand h1,
            .portal-login-brand p {
                max-width: none;
            }

            .portal-login-highlights {
                grid-template-columns: 1fr;
            }
        }

        @media (max-width: 560px) {
            .portal-login-card-header,
            .portal-login-form {
                padding-left: 22px;
                padding-right: 22px;
            }

            .portal-login-options {
                align-items: flex-start;
                flex-direction: column;
            }
        }

/* Lote 8 - links de recuperação/convite do Portal do Cliente */
.portal-login-inline-link,
.portal-login-footer a {
    color: #0b4ea2;
    font-weight: 900;
    text-decoration: none;
}

.portal-login-inline-link:hover,
.portal-login-footer a:hover {
    color: #06376d;
    text-decoration: underline;
}

.portal-login-field input:disabled {
    cursor: not-allowed;
    color: #64748b;
    background: #eef2f7;
}

