.dec-cockpit {
    --dec-card: rgba(255, 255, 255, 0.96);
    --dec-border: rgba(15, 23, 42, 0.1);
    --dec-text: #0f172a;
    --dec-muted: #64748b;
    --dec-soft: #f8fafc;
    --dec-info: #2563eb;
    --dec-success: #16a34a;
    --dec-warning: #d97706;
    --dec-danger: #dc2626;

    display: grid;
    gap: 1rem;
    color: var(--dec-text);
}

.dec-cockpit * {
    box-sizing: border-box;
}

.dec-hero,
.dec-decision,
.dec-panel,
.dec-trend,
.dec-footer-note,
.dec-empty {
    border: 1px solid var(--dec-border);
    background: var(--dec-card);
    box-shadow: 0 16px 42px rgba(15, 23, 42, 0.07);
}

.dec-hero {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(260px, 360px);
    gap: 1rem;
    min-height: 210px;
    padding: 1.25rem;
    border-radius: 1.5rem;
    background:
        radial-gradient(circle at 96% 10%, rgba(37, 99, 235, 0.16), transparent 34%),
        linear-gradient(135deg, #ffffff, #f8fafc);
    overflow: hidden;
}

.dec-hero.dec-tone-success {
    background: radial-gradient(circle at 96% 10%, rgba(22, 163, 74, 0.15), transparent 34%), linear-gradient(135deg, #ffffff, #f8fafc);
}

.dec-hero.dec-tone-warning {
    background: radial-gradient(circle at 96% 10%, rgba(217, 119, 6, 0.17), transparent 34%), linear-gradient(135deg, #ffffff, #fffbeb);
}

.dec-hero.dec-tone-danger {
    background: radial-gradient(circle at 96% 10%, rgba(220, 38, 38, 0.17), transparent 34%), linear-gradient(135deg, #ffffff, #fff1f2);
}

.dec-hero__content {
    display: grid;
    align-content: center;
    min-width: 0;
}

.dec-eyebrow {
    display: inline-flex;
    width: fit-content;
    margin-bottom: 0.5rem;
    padding: 0.25rem 0.65rem;
    border-radius: 999px;
    background: rgba(15, 23, 42, 0.06);
    color: var(--dec-muted);
    font-size: 0.72rem;
    font-weight: 900;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

.dec-hero h1,
.dec-panel h2,
.dec-action h3,
.dec-blocker h3 {
    margin: 0;
    color: var(--dec-text);
}

.dec-hero h1 {
    font-size: clamp(2rem, 4vw, 3.2rem);
    line-height: 0.95;
    font-weight: 950;
    letter-spacing: -0.05em;
}

.dec-hero p,
.dec-panel p,
.dec-decision p,
.dec-trend p,
.dec-footer-note span,
.dec-empty p,
.dec-action p,
.dec-blocker p {
    margin: 0;
    color: var(--dec-muted);
    line-height: 1.45;
}

.dec-hero__content > p {
    max-width: 760px;
    margin-top: 0.75rem;
    font-size: 1rem;
}

.dec-hero__meta {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
    margin-top: 1.2rem;
}

.dec-hero__meta span,
.dec-control small,
.dec-action small,
.dec-blocker small,
.dec-trend small {
    color: var(--dec-muted);
    font-size: 0.78rem;
    font-weight: 700;
}

.dec-hero__meta span {
    padding: 0.42rem 0.7rem;
    border: 1px solid var(--dec-border);
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.72);
}

.dec-control {
    display: grid;
    align-content: center;
    gap: 0.8rem;
    padding: 1rem;
    border-radius: 1.1rem;
    background: rgba(255, 255, 255, 0.72);
    border: 1px solid rgba(15, 23, 42, 0.08);
}

.dec-control__head,
.dec-panel__header,
.dec-action__top,
.dec-action__footer,
.dec-trend__metric {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
}

.dec-control__head span,
.dec-decision__label {
    color: var(--dec-muted);
    font-size: 0.78rem;
    font-weight: 900;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

.dec-control__head strong {
    font-size: 2.1rem;
    font-weight: 950;
    letter-spacing: -0.04em;
}

.dec-control__bar {
    height: 0.55rem;
    overflow: hidden;
    border-radius: 999px;
    background: rgba(15, 23, 42, 0.1);
}

.dec-control__bar i {
    display: block;
    height: 100%;
    border-radius: inherit;
    background: var(--dec-info);
}

.dec-tone-success .dec-control__bar i,
.dec-decision.dec-tone-success::before,
.dec-action.dec-tone-success::before,
.dec-blocker.dec-tone-success::before,
.dec-trend.dec-tone-success::before {
    background: var(--dec-success);
}

.dec-tone-warning .dec-control__bar i,
.dec-decision.dec-tone-warning::before,
.dec-action.dec-tone-warning::before,
.dec-blocker.dec-tone-warning::before,
.dec-trend.dec-tone-warning::before {
    background: var(--dec-warning);
}

.dec-tone-danger .dec-control__bar i,
.dec-decision.dec-tone-danger::before,
.dec-action.dec-tone-danger::before,
.dec-blocker.dec-tone-danger::before,
.dec-trend.dec-tone-danger::before {
    background: var(--dec-danger);
}

.dec-primary,
.dec-action a,
.dec-blocker a,
.dec-decision em {
    color: var(--dec-info);
    font-weight: 900;
    text-decoration: none;
}

.dec-primary {
    display: inline-flex;
    width: fit-content;
    align-items: center;
    justify-content: center;
    padding: 0.65rem 0.9rem;
    border-radius: 0.8rem;
    background: var(--dec-text);
    color: #ffffff;
}

.dec-decision-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0.85rem;
}

.dec-decision {
    position: relative;
    display: grid;
    min-height: 168px;
    padding: 1rem;
    border-radius: 1.15rem;
    text-decoration: none;
    overflow: hidden;
    transition: transform 0.16s ease, box-shadow 0.16s ease;
}

.dec-decision:hover {
    transform: translateY(-2px);
    box-shadow: 0 20px 46px rgba(15, 23, 42, 0.1);
}

.dec-decision--static {
    cursor: default;
}

.dec-decision::before,
.dec-action::before,
.dec-blocker::before,
.dec-trend::before {
    content: '';
    position: absolute;
    inset: 0 auto 0 0;
    width: 4px;
    background: var(--dec-info);
}

.dec-decision__icon {
    font-size: 1.35rem;
}

.dec-decision strong {
    margin-top: 0.45rem;
    color: var(--dec-text);
    font-size: 2.3rem;
    font-weight: 950;
    letter-spacing: -0.05em;
}

.dec-decision p {
    margin-top: 0.35rem;
    font-size: 0.82rem;
}

.dec-decision em {
    margin-top: 0.8rem;
    font-size: 0.78rem;
    font-style: normal;
}

.dec-main-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.25fr) minmax(320px, 0.75fr);
    gap: 1rem;
    align-items: start;
}

.dec-side-stack {
    display: grid;
    gap: 1rem;
}

.dec-panel,
.dec-trend,
.dec-footer-note {
    border-radius: 1.25rem;
}

.dec-panel {
    padding: 1rem;
}

.dec-panel__header {
    align-items: flex-start;
    padding-bottom: 0.85rem;
    border-bottom: 1px solid rgba(15, 23, 42, 0.08);
}

.dec-panel__header--compact {
    display: grid;
}

.dec-panel__header h2 {
    font-size: 1.25rem;
    font-weight: 950;
    letter-spacing: -0.03em;
}

.dec-panel__header p {
    margin-top: 0.3rem;
    font-size: 0.86rem;
}

.dec-panel__header > strong {
    display: inline-grid;
    min-width: 2.6rem;
    height: 2.6rem;
    place-items: center;
    border-radius: 999px;
    background: rgba(15, 23, 42, 0.06);
    font-size: 1.2rem;
    font-weight: 950;
}

.dec-action-list,
.dec-blocker-list {
    display: grid;
    gap: 0.7rem;
    padding-top: 0.85rem;
}

.dec-action,
.dec-blocker,
.dec-trend {
    position: relative;
    overflow: hidden;
}

.dec-action,
.dec-blocker {
    padding: 0.85rem;
    border: 1px solid rgba(15, 23, 42, 0.08);
    border-radius: 0.95rem;
    background: #ffffff;
}

.dec-action h3,
.dec-blocker h3 {
    font-size: 0.98rem;
    font-weight: 900;
}

.dec-action__top span {
    padding: 0.25rem 0.5rem;
    border-radius: 999px;
    background: rgba(15, 23, 42, 0.06);
    color: var(--dec-muted);
    font-size: 0.72rem;
    font-weight: 900;
}

.dec-action p,
.dec-blocker p {
    margin-top: 0.5rem;
    font-size: 0.84rem;
}

.dec-action__footer {
    margin-top: 0.75rem;
}

.dec-action__footer em {
    color: var(--dec-muted);
    font-size: 0.76rem;
    font-style: normal;
    font-weight: 800;
}

.dec-trend {
    display: grid;
    gap: 0.55rem;
    padding: 1rem;
}

.dec-trend__metric strong {
    color: var(--dec-text);
    font-size: 2.1rem;
    font-weight: 950;
    letter-spacing: -0.05em;
}

.dec-trend__metric span {
    color: var(--dec-muted);
    font-weight: 900;
}

.dec-footer-note {
    display: flex;
    flex-wrap: wrap;
    gap: 0.35rem 0.5rem;
    padding: 0.85rem 1rem;
    background: #f8fafc;
}

.dec-footer-note strong {
    font-weight: 950;
}

.dec-empty {
    padding: 1rem;
    border-radius: 1rem;
    background: #ffffff;
}

.dec-empty--wide {
    grid-column: 1 / -1;
}

.dec-empty--compact {
    padding: 0.85rem;
}

.dec-empty strong {
    display: block;
    margin-bottom: 0.3rem;
    font-weight: 950;
}

@media (max-width: 1180px) {
    .dec-decision-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .dec-main-grid,
    .dec-hero {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 720px) {
    .dec-cockpit {
        gap: 0.75rem;
    }

    .dec-hero,
    .dec-panel,
    .dec-trend {
        border-radius: 1rem;
        padding: 0.85rem;
    }

    .dec-decision-grid {
        grid-template-columns: 1fr;
    }

    .dec-decision {
        min-height: 145px;
    }

    .dec-hero h1 {
        font-size: 2rem;
    }
}

.dec-origin-note {
    width: fit-content;
    margin-top: 0.2rem;
    padding: 0.35rem 0.55rem;
    border-radius: 0.7rem;
    background: rgba(15, 23, 42, 0.05);
    color: var(--dec-muted);
    font-size: 0.72rem;
    font-weight: 800;
}

.dec-primary:focus-visible,
.dec-action a:focus-visible,
.dec-blocker a:focus-visible,
.dec-decision:focus-visible {
    outline: 3px solid rgba(37, 99, 235, 0.35);
    outline-offset: 3px;
}

@media (prefers-reduced-motion: reduce) {
    .dec-decision {
        transition: none;
    }

    .dec-decision:hover {
        transform: none;
    }
}

.dark .dec-cockpit,
.fi-theme-dark .dec-cockpit {
    --dec-card: rgba(15, 23, 42, 0.86);
    --dec-border: rgba(148, 163, 184, 0.22);
    --dec-text: #f8fafc;
    --dec-muted: #cbd5e1;
    --dec-soft: #111827;
}

.dark .dec-hero,
.fi-theme-dark .dec-hero,
.dark .dec-panel,
.fi-theme-dark .dec-panel,
.dark .dec-trend,
.fi-theme-dark .dec-trend,
.dark .dec-empty,
.fi-theme-dark .dec-empty,
.dark .dec-action,
.fi-theme-dark .dec-action,
.dark .dec-blocker,
.fi-theme-dark .dec-blocker,
.dark .dec-footer-note,
.fi-theme-dark .dec-footer-note {
    background: rgba(15, 23, 42, 0.88);
}

.dark .dec-hero,
.fi-theme-dark .dec-hero {
    background: radial-gradient(circle at 96% 10%, rgba(37, 99, 235, 0.18), transparent 34%), linear-gradient(135deg, #0f172a, #111827);
}

.dark .dec-hero__meta span,
.fi-theme-dark .dec-hero__meta span,
.dark .dec-control,
.fi-theme-dark .dec-control,
.dark .dec-panel__header > strong,
.fi-theme-dark .dec-panel__header > strong,
.dark .dec-action__top span,
.fi-theme-dark .dec-action__top span,
.dark .dec-origin-note,
.fi-theme-dark .dec-origin-note {
    background: rgba(148, 163, 184, 0.12);
}

/* System health dashboard - system-health-dashboard.css */
/*
 * CSS escopado do Painel de Saúde do Sistema.
 * Regra de segurança: este arquivo usa apenas classes com prefixo shd- e não altera body,
 * html, links, botões, inputs, tabelas ou componentes globais fora de .shd-panel.
 */
.shd-panel {
    --shd-bg: #ffffff;
    --shd-surface: #f8fafc;
    --shd-border: rgba(15, 23, 42, 0.10);
    --shd-border-soft: rgba(15, 23, 42, 0.07);
    --shd-text: #0f172a;
    --shd-muted: #64748b;
    --shd-muted-strong: #475569;
    --shd-primary: #2563eb;
    --shd-primary-hover: #1d4ed8;
    --shd-dark: #0f172a;
    --shd-ok-bg: #ecfdf5;
    --shd-ok-text: #047857;
    --shd-ok-border: #a7f3d0;
    --shd-warning-bg: #fffbeb;
    --shd-warning-text: #b45309;
    --shd-warning-border: #fde68a;
    --shd-error-bg: #fff1f2;
    --shd-error-text: #be123c;
    --shd-error-border: #fecdd3;
    --shd-neutral-bg: #f8fafc;
    --shd-neutral-text: #334155;
    --shd-neutral-border: #e2e8f0;
    --shd-radius-lg: 24px;
    --shd-radius-md: 18px;
    --shd-radius-sm: 12px;
    --shd-shadow: 0 12px 32px rgba(15, 23, 42, 0.08);
    --shd-shadow-soft: 0 8px 20px rgba(15, 23, 42, 0.06);
    display: flex;
    flex-direction: column;
    gap: 24px;
    color: var(--shd-text);
}

.shd-hero,
.shd-card,
.shd-section-card,
.shd-empty {
    background: var(--shd-bg);
    border: 1px solid var(--shd-border-soft);
    border-radius: var(--shd-radius-lg);
    box-shadow: var(--shd-shadow-soft);
}

.shd-hero {
    overflow: hidden;
}

.shd-hero__content {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 24px;
    padding: 28px;
    background:
        radial-gradient(circle at top left, rgba(37, 99, 235, 0.12), transparent 30%),
        linear-gradient(135deg, #ffffff 0%, #f8fafc 65%, #eef2ff 100%);
}

.shd-hero__text {
    max-width: 820px;
}

.shd-hero__meta {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 12px;
    margin-bottom: 14px;
}

.shd-muted,
.shd-description,
.shd-card__label,
.shd-card__hint,
.shd-section-description,
.shd-check-detail,
.shd-empty__text {
    color: var(--shd-muted);
}

.shd-title {
    margin: 0;
    color: var(--shd-text);
    font-size: clamp(1.45rem, 2.2vw, 2rem);
    font-weight: 800;
    letter-spacing: -0.035em;
    line-height: 1.15;
}

.shd-description {
    margin: 10px 0 0;
    max-width: 760px;
    font-size: 0.95rem;
    line-height: 1.7;
}

.shd-actions {
    display: flex;
    align-items: stretch;
    justify-content: flex-end;
    flex-wrap: wrap;
    gap: 12px;
    min-width: min(100%, 360px);
}

.shd-limit {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    min-height: 46px;
    padding: 8px 10px 8px 14px;
    background: rgba(255, 255, 255, 0.92);
    border: 1px solid var(--shd-border-soft);
    border-radius: var(--shd-radius-md);
    box-shadow: 0 4px 12px rgba(15, 23, 42, 0.05);
}

.shd-limit__label {
    color: var(--shd-muted-strong);
    font-size: 0.875rem;
    font-weight: 700;
}

.shd-input {
    width: 92px;
    min-height: 34px;
    padding: 6px 10px;
    color: var(--shd-text);
    background: #ffffff;
    border: 1px solid #cbd5e1;
    border-radius: var(--shd-radius-sm);
    font-size: 0.875rem;
    outline: none;
}

.shd-input:focus {
    border-color: var(--shd-primary);
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.16);
}

.shd-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 46px;
    padding: 11px 18px;
    border: 0;
    border-radius: var(--shd-radius-md);
    cursor: pointer;
    font-size: 0.875rem;
    font-weight: 800;
    line-height: 1;
    text-decoration: none;
    transition: transform 150ms ease, box-shadow 150ms ease, background-color 150ms ease, opacity 150ms ease;
}

.shd-button:hover {
    transform: translateY(-1px);
}

.shd-button:disabled {
    cursor: wait;
    opacity: 0.7;
    transform: none;
}

.shd-button--primary {
    color: #ffffff;
    background: var(--shd-primary);
    box-shadow: 0 10px 22px rgba(37, 99, 235, 0.24);
}

.shd-button--primary:hover {
    background: var(--shd-primary-hover);
}

.shd-button--dark {
    color: #ffffff;
    background: var(--shd-dark);
    box-shadow: 0 10px 22px rgba(15, 23, 42, 0.22);
}

.shd-summary-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 16px;
}

.shd-card {
    padding: 20px;
}

.shd-card--summary {
    min-height: 132px;
}

.shd-card__label,
.shd-card__hint {
    margin: 0;
    font-size: 0.83rem;
    font-weight: 700;
}

.shd-card__value {
    margin: 10px 0 8px;
    color: var(--shd-text);
    font-size: 2rem;
    font-weight: 850;
    letter-spacing: -0.04em;
    line-height: 1.05;
}

.shd-text-ok { color: var(--shd-ok-text); }
.shd-text-warning { color: var(--shd-warning-text); }
.shd-text-error { color: var(--shd-error-text); }

.shd-section-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 16px;
}

.shd-section-card {
    overflow: hidden;
}

.shd-section-card__header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 18px;
    padding: 20px;
    border-bottom: 1px solid var(--shd-border-soft);
}

.shd-section-card__heading {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    min-width: 0;
}

.shd-section-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 auto;
    width: 38px;
    height: 38px;
    border-radius: 16px;
    font-size: 0.78rem;
    font-weight: 900;
}

.shd-section-title {
    margin: 0;
    color: var(--shd-text);
    font-size: 1rem;
    font-weight: 850;
    line-height: 1.25;
}

.shd-section-description {
    margin: 4px 0 0;
    font-size: 0.78rem;
    line-height: 1.45;
}

.shd-section-counts {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    flex-wrap: wrap;
    gap: 6px;
    flex: 0 0 auto;
}

.shd-badge,
.shd-pill,
.shd-check-status {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 1px solid transparent;
    font-weight: 850;
    white-space: nowrap;
}

.shd-badge {
    min-height: 30px;
    padding: 5px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
}

.shd-pill {
    min-height: 26px;
    padding: 4px 9px;
    border-radius: 999px;
    font-size: 0.72rem;
}

.shd-check-list {
    display: flex;
    flex-direction: column;
}

.shd-check-item {
    padding: 18px 20px;
}

.shd-check-item + .shd-check-item {
    border-top: 1px solid var(--shd-border-soft);
}

.shd-check-item__layout {
    display: flex;
    align-items: flex-start;
    gap: 12px;
}

.shd-check-status {
    min-width: 58px;
    min-height: 28px;
    margin-top: 2px;
    padding: 4px 8px;
    border-radius: 999px;
    font-size: 0.68rem;
}

.shd-check-item__content {
    min-width: 0;
    flex: 1;
}

.shd-check-title {
    margin: 0;
    color: var(--shd-text);
    font-size: 0.9rem;
    font-weight: 800;
    line-height: 1.4;
}

.shd-check-detail {
    margin: 5px 0 0;
    font-size: 0.86rem;
    line-height: 1.55;
}

.shd-action-note {
    margin: 10px 0 0;
    padding: 10px 12px;
    color: var(--shd-muted-strong);
    background: var(--shd-surface);
    border: 1px solid var(--shd-border-soft);
    border-radius: var(--shd-radius-sm);
    font-size: 0.78rem;
    font-weight: 700;
    line-height: 1.45;
}

.shd-details {
    margin-top: 10px;
}

.shd-details__summary {
    color: var(--shd-primary);
    cursor: pointer;
    font-size: 0.78rem;
    font-weight: 800;
}

.shd-code-block {
    overflow: auto;
    max-height: 280px;
    margin: 10px 0 0;
    padding: 12px;
    color: #e2e8f0;
    background: #0f172a;
    border-radius: var(--shd-radius-sm);
    font-family: Consolas, Monaco, 'Courier New', monospace;
    font-size: 0.76rem;
    line-height: 1.55;
}

.shd-empty {
    grid-column: 1 / -1;
    padding: 34px;
    text-align: center;
}

.shd-empty__title {
    margin: 0;
    color: var(--shd-text);
    font-size: 1.1rem;
    font-weight: 850;
}

.shd-empty__text {
    margin: 8px 0 0;
    font-size: 0.9rem;
}

.shd-badge--ok,
.shd-pill--ok {
    color: var(--shd-ok-text);
    background: var(--shd-ok-bg);
    border-color: var(--shd-ok-border);
}

.shd-badge--warning,
.shd-pill--warning {
    color: var(--shd-warning-text);
    background: var(--shd-warning-bg);
    border-color: var(--shd-warning-border);
}

.shd-badge--error,
.shd-pill--error {
    color: var(--shd-error-text);
    background: var(--shd-error-bg);
    border-color: var(--shd-error-border);
}

.shd-badge--neutral {
    color: var(--shd-neutral-text);
    background: var(--shd-neutral-bg);
    border-color: var(--shd-neutral-border);
}

@media (prefers-color-scheme: dark) {
    .shd-panel {
        --shd-bg: #111827;
        --shd-surface: #0f172a;
        --shd-border: rgba(255, 255, 255, 0.12);
        --shd-border-soft: rgba(255, 255, 255, 0.10);
        --shd-text: #f8fafc;
        --shd-muted: #cbd5e1;
        --shd-muted-strong: #e2e8f0;
        --shd-neutral-bg: rgba(148, 163, 184, 0.12);
        --shd-neutral-text: #e2e8f0;
        --shd-neutral-border: rgba(148, 163, 184, 0.28);
        --shd-shadow: 0 12px 32px rgba(0, 0, 0, 0.26);
        --shd-shadow-soft: 0 8px 20px rgba(0, 0, 0, 0.20);
    }

    .shd-hero__content {
        background:
            radial-gradient(circle at top left, rgba(59, 130, 246, 0.20), transparent 34%),
            linear-gradient(135deg, #111827 0%, #0f172a 72%, #020617 100%);
    }

    .shd-limit,
    .shd-input {
        background: #0f172a;
        border-color: rgba(255, 255, 255, 0.14);
    }

    .shd-input {
        color: #f8fafc;
    }

    .shd-button--dark {
        color: #0f172a;
        background: #ffffff;
    }
}

@media (max-width: 1180px) {
    .shd-hero__content {
        align-items: stretch;
        flex-direction: column;
    }

    .shd-actions {
        justify-content: flex-start;
    }
}

@media (max-width: 980px) {
    .shd-summary-grid,
    .shd-section-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 680px) {
    .shd-panel {
        gap: 16px;
    }

    .shd-hero__content,
    .shd-card,
    .shd-section-card__header,
    .shd-check-item,
    .shd-empty {
        padding: 16px;
    }

    .shd-actions,
    .shd-button,
    .shd-limit {
        width: 100%;
    }

    .shd-summary-grid,
    .shd-section-grid {
        grid-template-columns: 1fr;
    }

    .shd-section-card__header {
        flex-direction: column;
    }

    .shd-section-counts {
        justify-content: flex-start;
    }
}

