/* Lote 9 refeito - suporte completo com anexo na resposta ao cliente */
.at-file-field input[type="file"] {
    padding: .65rem;
    background: #fff;
    cursor: pointer;
}

.at-file-field small {
    color: #64748b;
    font-size: .76rem;
    font-weight: 750;
}

.at-btn[disabled] {
    opacity: .68;
    cursor: wait;
    transform: none !important;
}

.at-log-attachments {
    display: grid;
    gap: .45rem;
    margin-top: .65rem;
}

.at-log-file {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    gap: .2rem .55rem;
    align-items: center;
    padding: .6rem;
    border-radius: .85rem;
    border: 1px solid #cbd5e1;
    background: #fff;
    color: #0f172a;
    text-decoration: none;
    transition: .16s ease;
}

.at-log-file:hover {
    transform: translateY(-1px);
    border-color: #60a5fa;
    box-shadow: 0 12px 24px rgba(37,99,235,.12);
}

.at-log-file span {
    grid-row: span 2;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 42px;
    min-height: 42px;
    border-radius: .75rem;
    background: #dbeafe;
    color: #1d4ed8;
    font-weight: 950;
    font-size: .7rem;
}

.at-log-file strong {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.at-log-file small {
    color: #64748b;
    font-weight: 750;
}

.dark .at-log-file,
.dark .at-file-field input[type="file"] {
    background: rgba(15, 23, 42, .72);
    border-color: rgba(148, 163, 184, .24);
    color: #f8fafc;
}

.dark .at-log-file span {
    background: rgba(37, 99, 235, .22);
    color: #bfdbfe;
}

/* Lote 10 - fechamento UX/segurança/notificações */
.at-last-sync {
    display: inline-flex;
    align-items: center;
    min-height: 38px;
    padding: 0 .75rem;
    border-radius: 999px;
    background: rgba(15, 23, 42, .06);
    color: #475569;
    font-weight: 800;
    white-space: nowrap;
}

.at-loading-panel {
    position: fixed;
    right: 1rem;
