/* Lote 1 Atendimentos - layout SaaS limpo inspirado na referência aprovada */
.at-page-head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 1rem;
    padding: .35rem 0 .15rem;
}

.at-title-block {
    display: grid;
    gap: .25rem;
}

.at-eyebrow {
    color: #4f46e5;
    font-size: .72rem;
    font-weight: 950;
    letter-spacing: .14em;
}

.at-title-block h1 {
    margin: 0;
    color: #0f172a;
    font-size: clamp(1.55rem, 2.5vw, 2.15rem);
    font-weight: 950;
    letter-spacing: -.04em;
}

.at-title-block p {
    margin: 0;
    color: #475569;
    font-weight: 650;
    line-height: 1.45;
}

.at-head-actions {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: .6rem;
    flex-wrap: wrap;
}

.at-kpis-saas {
    grid-template-columns: repeat(4, minmax(0, 1fr));
}

.at-kpi-focus {
    position: relative;
    display: grid;
    grid-template-columns: 58px minmax(0, 1fr);
    grid-template-areas:
        "icon number"
        "icon label"
        "icon hint";
    align-items: center;
    gap: 0 .85rem;
    min-height: 104px;
    padding: 1rem 1.1rem;
    border-radius: 1.1rem;
    box-shadow: 0 14px 30px rgba(15, 23, 42, .06);
}

.at-kpi-focus .at-kpi-icon {
    grid-area: icon;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 54px;
    height: 54px;
    border-radius: 999px;
    font-weight: 950;
    font-size: 1.1rem;
}

.at-kpi-icon.danger { background: #fee2e2; color: #dc2626; }
.at-kpi-icon.warning { background: #fef3c7; color: #d97706; }
.at-kpi-icon.primary { background: #dbeafe; color: #2563eb; }
.at-kpi-icon.success { background: #dcfce7; color: #16a34a; }

.at-kpi-focus strong {
    grid-area: number;
    margin: 0;
    font-size: 1.75rem;
    line-height: 1;
}

.at-kpi-focus > span:not(.at-kpi-icon) {
    grid-area: label;
    color: #334155;
    font-size: .86rem;
}

.at-kpi-focus small {
    grid-area: hint;
    color: #4f46e5;
    font-weight: 800;
}

.at-kpi-focus.warning small { color: #d97706; }
.at-kpi-focus.success small { color: #16a34a; }

.at-workspace {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 280px;
    gap: 1rem;
    align-items: start;
}

.at-main-column {
    min-width: 0;
    display: grid;
    gap: 1rem;
}

.at-filter-bar {
    display: grid;
    grid-template-columns: minmax(280px, 1fr) auto auto;
    gap: .75rem;
    align-items: center;
    padding: .9rem;
    border: 1px solid rgba(148, 163, 184, .28);
    border-radius: 1.15rem;
    background: #fff;
    box-shadow: 0 16px 34px rgba(15, 23, 42, .05);
}

.at-search-field {
    position: relative;
    display: grid;
    gap: .35rem;
}

.at-search-field span,
.at-filter-grid span {
    font-size: .72rem;
    color: #64748b;
    font-weight: 950;
}

.at-search-field input,
.at-filter-grid select {
    width: 100%;
    border: 1px solid #cbd5e1;
    border-radius: .85rem;
    padding: .78rem .9rem;
    background: #fff;
    color: #0f172a;
}

.at-filter-drawer {
    position: relative;
}

.at-filter-drawer summary {
    list-style: none;
    display: inline-flex;
    align-items: center;
    gap: .45rem;
    min-height: 42px;
    padding: .7rem 1rem;
    border: 1px solid #cbd5e1;
    border-radius: .85rem;
    background: #fff;
    color: #0f172a;
    font-weight: 950;
    cursor: pointer;
    user-select: none;
}

.at-filter-drawer summary::-webkit-details-marker { display: none; }

.at-filter-drawer summary strong {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 24px;
    min-height: 24px;
    padding: 0 .45rem;
    border-radius: 999px;
    background: #4f46e5;
    color: #fff;
    font-size: .72rem;
}

.at-filter-grid {
    position: absolute;
    right: 0;
    top: calc(100% + .55rem);
    z-index: 30;
    width: min(720px, calc(100vw - 2rem));
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: .75rem;
    padding: 1rem;
    border: 1px solid #e2e8f0;
    border-radius: 1rem;
    background: #fff;
