}

.at-clear-link:hover { color: #4f46e5; }

.at-side-panel {
    display: grid;
    gap: 1rem;
    position: sticky;
    top: 1rem;
}

.at-side-card {
    padding: 1rem;
    border: 1px solid rgba(148, 163, 184, .28);
    border-radius: 1.15rem;
    background: #fff;
    box-shadow: 0 16px 34px rgba(15, 23, 42, .05);
}

.at-side-card header {
    padding-bottom: .75rem;
