}

.at-side-list {
    display: grid;
    gap: .45rem;
}

.at-side-filter {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto;
    gap: .55rem;
    align-items: center;
    width: 100%;
    border: 0;
    border-radius: .85rem;
    padding: .62rem .7rem;
    background: transparent;
    color: #334155;
    font-weight: 850;
    cursor: pointer;
    text-align: left;
}

.at-side-filter:hover,
.at-side-filter.active {
    background: #f1f5ff;
    color: #312e81;
}

.at-side-filter strong {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 28px;
    min-height: 24px;
    border-radius: 999px;
    background: #f1f5f9;
    color: #64748b;
