}
.at-dot.danger { background: #ef4444; }
.at-dot.warning { background: #f59e0b; }
.at-dot.primary,
.at-dot.info { background: #3b82f6; }
.at-dot.success { background: #22c55e; }

.at-tip-card {
    background: linear-gradient(135deg, #eef2ff, #fff);
