/* =========================================================
   Lote final real - reconstrução de fidelidade visual da referência
   Mantém Livewire/Blade existentes e corrige somente composição visual.
   ========================================================= */
.at-reference-layout{
    --ref-bg:#f7f8fc;
    --ref-card:#fff;
    --ref-line:#e9edf5;
    --ref-text:#111827;
    --ref-muted:#667085;
    --ref-primary:#3730d9;
    --ref-primary-soft:#eef2ff;
    min-height:calc(100vh - 1rem);
    padding:clamp(1rem,2.1vw,1.75rem);
    border-radius:0;
    background:linear-gradient(180deg,#fbfcff 0%, var(--ref-bg) 100%);
    gap:1.35rem;
    color:var(--ref-text);
}

.at-reference-head{
    display:grid;
    grid-template-columns:minmax(0,1fr) auto;
    align-items:start;
    gap:1.25rem;
    padding:0;
    border:0;
    border-radius:0;
    background:transparent;
    box-shadow:none;
    backdrop-filter:none;
}
.at-reference-head .at-eyebrow{display:none;}
.at-reference-head h1{
    margin:0 0 .35rem;
    font-size:clamp(1.7rem,2.15vw,2.15rem);
    line-height:1.05;
    color:#0f172a;
    letter-spacing:-.045em;
    font-weight:900;
}
.at-reference-head p{
    margin:0;
    max-width:560px;
    color:#475467;
    font-size:1rem;
    line-height:1.45;
    font-weight:500;
}
.at-reference-head .at-head-actions{display:flex;gap:.75rem;align-items:center;justify-content:flex-end;}
.at-reference-head .at-last-sync{display:none;}
.at-reference-head .at-btn,
.at-reference-head .at-btn.ghost{
    display:inline-flex;
    align-items:center;
    justify-content:center;
    gap:.45rem;
    min-height:48px;
    padding:.75rem 1.2rem;
    border-radius:.7rem;
    font-size:.9rem;
    font-weight:800;
    box-shadow:none;
}
.at-reference-head .at-btn.ghost{
    background:#fff;
    color:#111827;
    border:1px solid #dfe5ef;
}
.at-reference-head .at-btn:not(.ghost){
    border:1px solid #3730d9;
    background:#3730d9;
    color:#fff;
    box-shadow:0 14px 30px rgba(55,48,217,.18);
}
.at-btn-icon{font-weight:950;font-size:1rem;line-height:1;}

.at-reference-metrics{
    display:grid;
    grid-template-columns:repeat(4,minmax(0,1fr));
    gap:1.15rem;
}
.at-reference-metrics .at-kpi-button{
    display:grid;
    grid-template-columns:auto minmax(0,1fr);
    grid-template-rows:auto auto auto;
    column-gap:1rem;
    align-items:center;
    min-height:118px;
    padding:1.3rem 1.25rem;
    border:1px solid #e6ebf3;
    border-radius:.95rem;
    background:#fff;
    box-shadow:0 14px 35px rgba(15,23,42,.045);
    overflow:hidden;
}
.at-reference-metrics .at-kpi-button::after{display:none;}
.at-reference-metrics .at-kpi-icon{
    grid-row:1 / span 3;
    width:58px;
    height:58px;
    margin:0;
    border-radius:999px;
    font-size:1.35rem;
}
.at-reference-metrics strong{
    display:block;
    margin:0;
    color:#0f172a;
    font-size:1.8rem;
    line-height:1;
    font-weight:900;
    letter-spacing:-.035em;
}
.at-reference-metrics span:not(.at-kpi-icon){
    margin-top:.15rem;
    color:#344054;
    font-size:.92rem;
    font-weight:650;
}
.at-reference-metrics small{
    display:block;
    margin-top:.28rem;
    color:#dc2626;
    font-size:.82rem;
    font-weight:650;
}
.at-reference-metrics .warning small{color:#d97706;}
.at-reference-metrics .primary small{color:#2563eb;}
.at-reference-metrics .success small{color:#16a34a;}

.at-reference-workspace{
    display:grid;
    grid-template-columns:minmax(0,1fr) 300px;
    gap:1.15rem;
    align-items:start;
}
.at-reference-layout .at-filter-bar,
.at-reference-layout .at-table-card,
.at-reference-layout .at-side-card{
    background:#fff;
    border:1px solid #e6ebf3;
    box-shadow:0 15px 35px rgba(15,23,42,.045);
    backdrop-filter:none;
}
.at-reference-layout .at-filter-bar{
    position:relative;
    z-index:5;
    display:grid;
    grid-template-columns:minmax(300px,1fr) auto auto;
    gap:1rem;
    align-items:center;
    padding:1.1rem;
    border-radius:.95rem .95rem 0 0;
    border-bottom:0;
    box-shadow:0 8px 24px rgba(15,23,42,.035);
}
.at-reference-layout .at-search-field{gap:0;}
.at-reference-layout .at-search-field span{display:none;}
.at-reference-layout .at-search-field::after{
    content:'⌕';
    position:absolute;
    right:1rem;
    top:50%;
    transform:translateY(-50%);
    color:#667085;
    font-size:1.2rem;
    pointer-events:none;
}
.at-reference-layout .at-search-field input{
    width:100%;
    min-height:48px;
    padding:.78rem 2.8rem .78rem 1rem;
    border:1px solid #dfe5ef;
    border-radius:.55rem;
    background:#fff;
    color:#111827;
    box-shadow:none;
    font-size:.92rem;
}
.at-reference-layout .at-filter-drawer{min-width:150px;}
.at-reference-layout .at-filter-drawer summary{
    min-height:48px;
    border:1px solid #dfe5ef;
    border-radius:.55rem;
    background:#fff;
    color:#111827;
    font-size:.92rem;
    font-weight:800;
}
.at-reference-layout .at-filter-drawer summary::before{content:'≡';color:#3730d9;font-weight:950;}
.at-reference-layout .at-filter-drawer summary strong{
    min-width:22px;
    height:22px;
    background:#3730d9;
    color:#fff;
    font-size:.74rem;
}
.at-reference-layout .at-clear-link{
    min-height:48px;
    padding:.72rem 1rem;
    border-radius:.55rem;
    background:transparent;
    color:#475467;
    font-size:.9rem;
    font-weight:800;
}
.at-reference-layout .at-clear-link::before{content:'× ';font-size:1.1rem;}
.at-reference-layout .at-filter-drawer[open] .at-filter-grid{
    top:calc(100% + .55rem);
    right:0;
    width:min(760px,calc(100vw - 3rem));
    border-radius:.9rem;
    border:1px solid #dfe5ef;
    box-shadow:0 24px 60px rgba(15,23,42,.16);
}

.at-reference-layout .at-table-card{
    margin-top:0;
    border-radius:0 0 .95rem .95rem;
    overflow:hidden;
    padding:0;
}
.at-reference-list-head{display:none!important;}
.at-reference-layout .at-table-wrap{border:0;border-radius:0;overflow:auto;background:#fff;}
.at-reference-layout .at-queue-table{
    min-width:1060px;
    border-collapse:separate;
    border-spacing:0;
    background:#fff;
}
.at-reference-layout .at-queue-table th{
    background:#fbfcff;
    border-top:1px solid #eef2f7;
    border-bottom:1px solid #e6ebf3;
    color:#475467;
    font-size:.72rem;
    font-weight:850;
    text-transform:uppercase;
    letter-spacing:.035em;
    vertical-align:middle;
}
.at-reference-layout .at-queue-table td{
    height:76px;
    border-top:0;
    border-bottom:1px solid #eef2f7;
    vertical-align:middle;
    background:#fff;
}
.at-reference-layout .at-queue-table tbody tr{transition:background .16s ease, box-shadow .16s ease;}
.at-reference-layout .at-queue-table tbody tr:hover td{background:#fbfdff;}
.at-reference-layout .at-queue-table tbody tr.is-late td{background:#fffdfd;}
.at-select-col{width:42px;text-align:center;}
.at-fake-checkbox{
    display:inline-flex;
    width:16px;
    height:16px;
    border:1.5px solid #b8c2d1;
    border-radius:.22rem;
    background:#fff;
    vertical-align:middle;
}
.at-reference-layout .at-ticket-cell{
    display:flex;
    align-items:center;
    gap:.9rem;
    min-width:320px;
}
.at-reference-layout .at-ticket-icon{
    width:44px;
    height:44px;
    border-radius:999px;
    font-size:1rem;
}
.at-ticket-title-row{display:flex;align-items:center;gap:.25rem;flex-wrap:wrap;}
.at-ticket-id{font-weight:900;color:#111827;}
.at-reference-layout .at-ticket-main strong{
    display:inline;
    color:#111827;
    font-size:.92rem;
    font-weight:850;
}
.at-reference-layout .at-ticket-main small{
    max-width:320px;
    margin-top:.22rem;
    color:#667085;
    font-size:.8rem;
    line-height:1.35;
    white-space:nowrap;
    overflow:hidden;
    text-overflow:ellipsis;
}
.at-ticket-meta-line{display:none!important;}
.at-client-cell{display:flex;align-items:center;gap:.75rem;min-width:210px;}
.at-client-avatar{
    flex:0 0 auto;
    width:34px;
    height:34px;
    display:inline-flex;
    align-items:center;
    justify-content:center;
    border-radius:999px;
    background:linear-gradient(135deg,#dbeafe,#ede9fe);
    color:#3730d9;
    font-size:.86rem;
    font-weight:900;
}
.at-client-cell strong{color:#111827;font-size:.9rem;font-weight:850;}
.at-client-cell small{color:#667085;font-size:.78rem;}
.at-reference-layout .at-badge{
    border-radius:.48rem;
    padding:.28rem .6rem;
    font-size:.74rem;
    font-weight:800;
    border:1px solid transparent;
}
.at-reference-layout .at-badge.danger{background:#fff1f1;color:#e11d48;border-color:#fecdd3;}
.at-reference-layout .at-badge.warning{background:#fffbeb;color:#d97706;border-color:#fde68a;}
.at-reference-layout .at-badge.primary,.at-reference-layout .at-badge.info{background:#eef2ff;color:#2563eb;border-color:#c7d2fe;}
.at-reference-layout .at-badge.success{background:#ecfdf3;color:#16a34a;border-color:#bbf7d0;}
.at-reference-layout .at-badge.neutral{background:#f2f4f7;color:#475467;border-color:#e4e7ec;}
.at-time-cell strong{color:#e11d48;font-size:.82rem;font-weight:800;}
.at-time-cell small{display:none!important;}
.at-reference-layout .at-row-actions{display:flex;align-items:center;justify-content:flex-end;gap:.5rem;flex-wrap:nowrap;}
.at-reference-layout .at-open-btn{
    min-height:36px;
    padding:.48rem .85rem;
    border-radius:.42rem;
    border:1px solid #c7d2fe;
    background:#fff;
    color:#3730d9;
    box-shadow:none;
    font-size:.82rem;
    font-weight:850;
}
.at-reference-layout .at-open-btn:hover{background:#eef2ff;transform:none;}
.at-reference-layout .at-secondary-btn{display:none;}
.at-more-btn{
    width:36px;
    height:36px;
    border:1px solid #e6ebf3;
    border-radius:.5rem;
    background:#fff;
    color:#667085;
    font-size:1.15rem;
    line-height:1;
    cursor:pointer;
}

.at-reference-aside{position:sticky;top:1rem;gap:1rem;}
.at-reference-layout .at-side-card{
    border-radius:.95rem;
    padding:1.05rem;
}
.at-filter-panel-card{min-height:0;}
.at-reference-layout .at-side-card header{
    margin:0 0 1rem;
    padding-bottom:.85rem;
    border-bottom:1px solid #eef2f7;
}
.at-reference-layout .at-side-card h3{
    color:#111827;
    font-size:1rem;
    font-weight:900;
}
.at-filter-icon{color:#3730d9;font-weight:950;}
.at-filter-section{
    border-bottom:1px solid #eef2f7;
    padding:.2rem 0;
}
.at-filter-section:last-of-type{border-bottom:0;}
.at-filter-section-title{
    min-height:50px;
    display:flex;
    align-items:center;
    justify-content:space-between;
    gap:.75rem;
    color:#111827;
    font-size:.92rem;
    font-weight:850;
    cursor:pointer;
    list-style:none;
}
.at-filter-section-title::-webkit-details-marker{display:none;}
.at-filter-section-body{display:grid;gap:.65rem;padding:.35rem 0 .9rem;}
.at-filter-check-row{
    display:grid;
    grid-template-columns:20px 8px minmax(0,1fr) auto;
    align-items:center;
    gap:.55rem;
    width:100%;
    min-height:30px;
    border:0;
    background:transparent;
    padding:.18rem 0;
    color:#344054;
    font-size:.84rem;
    font-weight:650;
    text-align:left;
    cursor:pointer;
}
.at-check-box{
    width:18px;
    height:18px;
    display:inline-flex;
    align-items:center;
    justify-content:center;
    border:1px solid #cbd5e1;
    border-radius:.28rem;
    color:transparent;
    font-size:.7rem;
    font-weight:950;
}
.at-filter-check-row.active .at-check-box{
    background:#3730d9;
    border-color:#3730d9;
    color:#fff;
}
.at-filter-check-row strong{
    min-width:28px;
    height:24px;
    display:inline-flex;
    align-items:center;
    justify-content:center;
    border-radius:999px;
    background:#f2f4f7;
    color:#667085;
    font-size:.75rem;
    font-weight:800;
}
.at-side-select{display:grid;gap:.4rem;}
.at-side-select span{color:#667085;font-size:.76rem;font-weight:850;}
.at-side-select select{
    min-height:40px;
    width:100%;
    border:1px solid #dfe5ef;
    border-radius:.55rem;
    padding:.55rem .7rem;
    background:#fff;
    color:#111827;
}
.at-clear-filters-wide{
    width:100%;
    margin-top:.95rem;
    min-height:42px;
    border:1px solid #e6ebf3;
    border-radius:.55rem;
    background:#fff;
    color:#344054;
    font-size:.86rem;
    font-weight:800;
    cursor:pointer;
}
.at-tip-card{
    background:linear-gradient(135deg,#f5f3ff,#fff)!important;
    border-color:#eef2ff!important;
}
.at-tip-card strong{display:block;color:#3730d9;font-size:1rem;margin-bottom:.45rem;}
.at-tip-card p{margin:0;color:#475467;font-size:.9rem;line-height:1.5;font-weight:500;}

@media (max-width:1280px){
    .at-reference-workspace{grid-template-columns:1fr;}
    .at-reference-aside{position:static;grid-template-columns:1fr 1fr;display:grid;}
}
@media (max-width:980px){
    .at-reference-head{grid-template-columns:1fr;}
    .at-reference-head .at-head-actions{justify-content:flex-start;flex-wrap:wrap;}
    .at-reference-metrics{grid-template-columns:repeat(2,minmax(0,1fr));}
    .at-reference-layout .at-filter-bar{grid-template-columns:1fr;}
    .at-reference-layout .at-filter-drawer{min-width:0;}
    .at-reference-layout .at-filter-drawer[open] .at-filter-grid{position:static;width:100%;margin-top:.65rem;box-shadow:none;}
    .at-reference-aside{grid-template-columns:1fr;}
}
@media (max-width:720px){
    .at-reference-layout{padding:.75rem;gap:1rem;}
    .at-reference-head .at-head-actions{display:grid;grid-template-columns:1fr; width:100%;}
    .at-reference-head .at-head-actions .at-btn{width:100%;}
    .at-reference-metrics{grid-template-columns:1fr;gap:.8rem;}
    .at-reference-metrics .at-kpi-button{min-height:96px;padding:1rem;}
    .at-reference-metrics .at-kpi-icon{width:48px;height:48px;}
    .at-reference-layout .at-filter-bar{border-radius:.95rem;margin-bottom:.85rem;border-bottom:1px solid #e6ebf3;}
    .at-reference-layout .at-table-card{border-radius:.95rem;}
    .at-reference-layout .at-queue-table{min-width:0;}
    .at-reference-layout .at-queue-table thead{display:none;}
    .at-reference-layout .at-queue-table,
    .at-reference-layout .at-queue-table tbody,
    .at-reference-layout .at-queue-table tr,
    .at-reference-layout .at-queue-table td{display:block;width:100%;}
    .at-reference-layout .at-queue-table tr{padding:1rem;border-bottom:1px solid #eef2f7;}
    .at-reference-layout .at-queue-table td{height:auto;border:0;background:transparent!important;}
    .at-select-col{display:none!important;}
    .at-reference-layout .at-ticket-cell{min-width:0;align-items:flex-start;}
    .at-reference-layout .at-ticket-main small{white-space:normal;max-width:none;}
    .at-client-cell{min-width:0;}
    .at-reference-layout .at-queue-table td:not(.at-ticket-cell):not(.at-select-col)::before{content:attr(data-label);display:block;margin-bottom:.2rem;color:#98a2b3;font-size:.68rem;font-weight:900;text-transform:uppercase;letter-spacing:.04em;}
    .at-reference-layout .at-row-actions{justify-content:stretch;margin-top:.4rem;}
    .at-reference-layout .at-open-btn{flex:1;}
    .at-more-btn{width:42px;}
}


