}

.at-ticket-control,
.at-ticket-icon-btn,
.at-ticket-side-btn,
.at-ticket-quick-btn,
.at-ticket-send-btn,
.at-ticket-attachment-btn {
    border: 1px solid #e2e8f0;
    border-radius: .72rem;
    background: #fff;
    color: #334155;
    font-weight: 900;
    cursor: pointer;
    transition: .16s ease;
}

.at-ticket-control:hover,
.at-ticket-icon-btn:hover,
.at-ticket-side-btn:hover,
.at-ticket-quick-btn:hover,
.at-ticket-attachment-btn:hover {
