}
.co-dot.green { background: #15c76c; box-shadow: 0 0 0 5px rgba(21,199,108,.12); }
.co-dot.blue { background: #2474ff; box-shadow: 0 0 0 5px rgba(36,116,255,.12); }
.co-dot.orange { background: #ff9f1c; box-shadow: 0 0 0 5px rgba(255,159,28,.12); }
