.co-deadline-total span { color: #101828; font-size: 18px; font-weight: 900; }
.co-deadline-total strong { color: #233bdf; font-size: 34px; line-height: .9; font-weight: 900; }

.co-bottom-model-grid {
    display: grid;
    grid-template-columns: 1.12fr 1.1fr .92fr .9fr;
    gap: 26px;
}

.co-workload-list-model { display: flex; flex-direction: column; gap: 13px; }
.co-workload-model-row { display: grid; grid-template-columns: 42px minmax(90px, .75fr) minmax(118px, 1fr) 44px; align-items: center; gap: 12px; }
.co-person-avatar {
