.co-small-model-row { display: grid; grid-template-columns: 38px minmax(0, 1fr) auto; align-items: center; gap: 12px; min-height: 68px; border-bottom: 1px solid var(--co-border); }
.co-small-icon { width: 34px; height: 34px; border-radius: 9px; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 15px; }
.co-small-icon.danger { background: #ef334e; }
.co-mini-pill.warning { background: #fff1dc; color: #f07800; }
.co-mini-pill.muted { background: #f1f5f9; color: #475569; }

.co-results-panel { background: #fff; }
.co-party { color: #27c0aa; font-size: 34px; }
.co-result-grid-model { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.co-result-model-card {
    position: relative;
    min-height: 82px;
    padding: 15px 14px;
    border: 1px solid #e2f3e8;
    border-radius: 12px;
