.co-result-model-card span { display: block; margin-top: 8px; color: #243349; font-size: 12px; font-weight: 900; }
.co-result-model-card i {
    position: absolute;
    top: 12px;
    right: 12px;
    width: 22px;
    height: 22px;
    border-radius: 999px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #bdf0cf;
    color: #128544;
    font-size: 12px;
