}
.co-success-message { margin: 18px 0 0; color: #16a34a; font-size: 14px; font-weight: 900; }
.co-empty.clean { padding: 22px; border: 1px dashed #cbd5e1; border-radius: 14px; background: #f8fafc; color: #64748b; text-align: center; }
.co-empty.clean strong { display: block; color: #0f172a; }
.co-empty.clean p { margin: 6px 0 0; color: #64748b; }

@media (max-width: 1600px) {
    .co-page.co-model { padding-inline: 24px; }
    .co-focus-grid { grid-template-columns: minmax(0, 1fr) minmax(0, .95fr); }
    .co-deadline-panel { grid-column: 1 / -1; }
    .co-bottom-model-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 1200px) {
    .co-topbar { flex-direction: column; }
    .co-top-actions { justify-content: flex-start; }
    .co-kpi-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .co-focus-grid, .co-bottom-model-grid { grid-template-columns: 1fr; }
    .co-department-content { grid-template-columns: 1fr; }
    .co-donut { margin: auto; }
}
@media (max-width: 760px) {
    .co-page.co-model { padding: 16px 12px 32px; }
    .co-topbar h1 { font-size: 28px; }
    .co-top-actions, .co-toolbar-btn, .co-refresh-btn, .co-date-btn { width: 100%; }
    .co-toolbar-btn, .co-refresh-btn { justify-content: center; }
    .co-kpi-grid { grid-template-columns: 1fr; }
    .co-action-row, .co-client-model-row, .co-small-model-row, .co-workload-model-row { grid-template-columns: 1fr; align-items: flex-start; }
    .co-action-icon, .co-client-avatar, .co-small-icon { display: none; }
    .co-time { text-align: left; }
    .co-risk-badge { justify-self: start; }
    .co-result-grid-model { grid-template-columns: 1fr; }
}

