/* Gráfico real por SVG - Pendências por Departamento */
.co-chart-wrap {
    width: 156px;
    height: 156px;
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-inline: auto;
}

.co-donut-chart {
    width: 156px;
    height: 156px;
    display: block;
    filter: drop-shadow(0 16px 28px rgba(15, 23, 42, .10));
    transform: rotate(-90deg);
}

.co-donut-track,
.co-donut-segment {
    fill: none;
    stroke-width: 24;
    stroke-linecap: butt;
}

.co-donut-track {
    stroke: #eef2f7;
}

.co-donut-segment {
    transition: stroke-width .18s ease, opacity .18s ease, filter .18s ease;
    cursor: pointer;
}

.co-donut-segment:hover {
    stroke-width: 28;
    opacity: .92;
    filter: brightness(1.04);
}

.co-chart-center {
    position: absolute;
    inset: 39px;
    border-radius: 999px;
    background: #fff;
    box-shadow: inset 0 4px 12px rgba(15, 23, 42, .04);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    pointer-events: none;
}

.co-chart-center strong {
    color: #071229;
    font-size: 26px;
    line-height: 1;
    font-weight: 780;
}

.co-chart-center span {
    margin-top: 4px;
    color: #667085;
    font-size: 11px;
    line-height: 1;
    font-weight: 650;
    text-transform: uppercase;
    letter-spacing: .04em;
}

.co-donut-empty {
    width: 138px;
    height: 138px;
    border-radius: 999px;
    background: #f4f7fb;
    color: #16a34a;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 42px;
    box-shadow: 0 16px 28px rgba(15, 23, 42, .08);
}

