.co-global-search-icon.success { color: #16a34a; background: rgba(22, 163, 74, .1); }
.co-global-search-icon.info { color: #2563eb; background: rgba(37, 99, 235, .09); }

.co-global-search-content {
    display: grid;
    gap: 3px;
