    margin: 0 auto !important;
}

.co-detail-modal-card,
.co-workload-modal-card {
    width: min(920px, calc(100vw - 32px)) !important;
}

.co-workload-modal-card {
    width: min(980px, calc(100vw - 32px)) !important;
}

.co-detail-modal-body {
    overflow: visible !important;
    max-height: none !important;
}

.co-detail-insight-card,
.co-related-client-card,
.co-workload-modal-list {
    max-height: 342px !important;
    overflow-y: auto !important;
    overscroll-behavior: contain !important;
}

.co-detail-insight-card article:nth-of-type(n+6),
.co-related-client-card article:nth-of-type(n+6),
.co-workload-modal-list article:nth-of-type(n+6) {
    /* Mantém todos os registros disponíveis, mas garante que a área visível seja limitada a aproximadamente 5 itens. */
}

