/* Lote 3 - Clientes e responsáveis em risco */
.co-client-risk-panel .co-panel-header,
.co-people-risk-panel .co-panel-header {
    align-items: flex-start;
}

.co-risk-summary-strip {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 10px;
    margin-bottom: 14px;
}

.co-risk-summary-strip article {
    padding: 12px 14px;
    border: 1px solid rgba(239, 51, 78, .12);
    border-radius: 16px;
    background: linear-gradient(180deg, #fff 0%, #fff7f8 100%);
}

.co-risk-summary-strip small,
.co-people-risk-summary small,
.co-people-risk-summary span {
    display: block;
