    font-size: 24px;
    font-weight: 950;
    letter-spacing: -.04em;
}

.co-client-risk-list {
    gap: 11px;
}

.co-client-risk-row {
    position: relative;
    border: 1px solid rgba(15, 23, 42, .08);
