}

.co-client-risk-row.danger {
    border-color: rgba(239, 51, 78, .22);
    background: linear-gradient(90deg, rgba(239, 51, 78, .08), #fff 34%);
}

.co-client-risk-row.warning,
.co-client-risk-row.attention {
    border-color: rgba(245, 158, 11, .24);
    background: linear-gradient(90deg, rgba(245, 158, 11, .08), #fff 34%);
}

.co-client-risk-row .co-client-row-link {
    grid-template-columns: 34px 42px minmax(0, 1fr) auto;
}

.co-client-rank {
    width: 30px;
    height: 30px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 11px;
    background: #111827;
    color: #fff;
    font-size: 11px;
    font-weight: 950;
}

.co-client-main small {
    display: flex;
    align-items: center;
    gap: 5px;
    margin-top: 5px;
    color: #9a3412;
