    font-weight: 800;
}

.co-people-risk-panel {
    margin: 18px 0;
}

.co-people-risk-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.25fr) minmax(280px, .85fr) minmax(180px, .45fr);
    gap: 14px;
