    font-weight: 950;
}

.co-people-risk-column-head strong {
    width: 30px;
    height: 30px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 999px;
    background: #111827;
    color: #fff;
    font-size: 12px;
    font-weight: 950;
}

.co-person-risk-row {
    display: grid;
    grid-template-columns: 38px minmax(0, 1fr) 54px auto;
    gap: 10px;
    align-items: center;
    padding: 11px;
    border: 1px solid rgba(15, 23, 42, .07);
    border-radius: 16px;
    background: rgba(255, 255, 255, .82);
}

.co-person-risk-row + .co-person-risk-row {
    margin-top: 9px;
}

.co-person-risk-row.danger {
    border-color: rgba(239, 51, 78, .2);
}

.co-person-risk-row.warning,
.co-person-risk-row.attention {
    border-color: rgba(245, 158, 11, .22);
}

.co-person-risk-row.success {
    border-color: rgba(22, 163, 74, .16);
}

.co-person-avatar {
    width: 38px;
    height: 38px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
