}

.co-person-info strong,
.co-person-info small {
    display: block;
}

.co-person-info strong {
    color: var(--co-text);
    font-size: 14px;
    font-weight: 950;
}

.co-person-info small {
    margin-top: 2px;
    color: var(--co-muted);
    font-size: 12px;
    font-weight: 700;
}

.co-person-risk-row .co-progress {
    margin-top: 8px;
