}

.co-person-risk-row.success .co-progress span {
    background: var(--co-green);
}

.co-person-risk-row b {
    color: var(--co-text);
    font-size: 15px;
    font-weight: 950;
    text-align: right;
}

.co-person-risk-row.compact {
