    }

    .co-person-risk-row b {
        text-align: left;
    }
}

/* Lote 4 - Tendência operacional e alertas separados por criticidade.
   Mantém a tela leve: apenas CSS e dados já calculados pelo service. */
.co-trend-strip {
    display: grid;
    grid-template-columns: minmax(230px, .58fr) minmax(0, 1.42fr);
    gap: 16px;
    align-items: stretch;
    margin: 0 0 24px;
    padding: 16px;
    border: 1px solid rgba(148, 163, 184, .22);
    border-radius: 22px;
    background: rgba(255, 255, 255, .96);
    box-shadow: 0 14px 38px rgba(15, 23, 42, .06);
}

.co-trend-strip-head {
    display: flex;
    align-items: center;
    gap: 12px;
    min-width: 0;
    padding: 12px 14px;
    border-radius: 18px;
    background: linear-gradient(135deg, #f8fafc 0%, #ffffff 100%);
    border: 1px solid rgba(226, 232, 240, .92);
}

.co-trend-strip-head strong {
    display: block;
    color: #0f172a;
    font-size: .96rem;
    font-weight: 950;
    letter-spacing: -.02em;
}

.co-trend-strip-head small {
    display: block;
    margin-top: 4px;
    color: #64748b;
    font-size: .78rem;
    line-height: 1.32;
    font-weight: 720;
}

.co-trend-cards {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 10px;
}

.co-trend-card {
    min-width: 0;
    padding: 13px;
    border-radius: 17px;
    border: 1px solid rgba(148, 163, 184, .18);
    background: #f8fafc;
}

.co-trend-card.success {
    border-color: rgba(22, 163, 74, .18);
    background: linear-gradient(180deg, #ffffff 0%, #f2fff6 100%);
}

.co-trend-card.danger {
    border-color: rgba(239, 51, 78, .20);
    background: linear-gradient(180deg, #ffffff 0%, #fff6f7 100%);
}

.co-trend-label {
    display: block;
    color: #64748b;
    font-size: .7rem;
    font-weight: 950;
    letter-spacing: .045em;
    text-transform: uppercase;
}

.co-trend-value-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    margin-top: 8px;
}

.co-trend-value-row strong {
    color: #071229;
    font-size: 1.55rem;
    line-height: .9;
    font-weight: 950;
    letter-spacing: -.045em;
}

.co-trend-delta {
    display: inline-flex;
    align-items: center;
    gap: 2px;
    min-height: 26px;
    padding: 4px 8px;
    border-radius: 999px;
    font-size: .72rem;
    font-weight: 950;
    white-space: nowrap;
}

.co-trend-delta.up { color: #b91c1c; background: rgba(239, 51, 78, .10); }
.co-trend-delta.down { color: #15803d; background: rgba(22, 163, 74, .11); }
.co-trend-delta.stable { color: #475569; background: rgba(100, 116, 139, .12); }

.co-trend-card > small {
    display: block;
    margin-top: 9px;
    color: #64748b;
    font-size: .73rem;
    line-height: 1.28;
    font-weight: 700;
}

.co-alerts-toggle-count.danger {
    flex-direction: column;
    gap: 1px;
    color: #b91c1c;
    background: rgba(239, 51, 78, .10);
}

.co-alerts-toggle-count.success {
    flex-direction: column;
    gap: 1px;
    color: #15803d;
    background: rgba(22, 163, 74, .10);
}

.co-alerts-toggle-count small {
    color: inherit;
    font-size: .66rem;
    font-weight: 850;
    opacity: .74;
}

.co-alerts-priority-layout {
    display: grid;
    gap: 16px;
}

.co-alerts-priority-block {
    display: grid;
    gap: 12px;
    min-width: 0;
    padding: 14px;
    border-radius: 22px;
    border: 1px solid rgba(148, 163, 184, .20);
    background: #f8fafc;
}

.co-alerts-priority-block.critical {
    border-color: rgba(239, 51, 78, .16);
    background: linear-gradient(180deg, #fff 0%, #fff7f8 100%);
}

.co-alerts-priority-block.informative {
    background: linear-gradient(180deg, #fff 0%, #f8fafc 100%);
}

.co-alerts-priority-block > header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
}

.co-alerts-priority-block > header span {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    color: #0f172a;
    font-size: .86rem;
    font-weight: 950;
}

.co-alerts-priority-block.critical > header span i { color: #dc2626; }
.co-alerts-priority-block.informative > header span i { color: #2474ff; }

.co-alerts-priority-block > header b {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 34px;
    min-height: 28px;
    padding: 5px 9px;
    border-radius: 999px;
    background: rgba(15, 23, 42, .08);
    color: #0f172a;
    font-size: .78rem;
    font-weight: 950;
}

.co-alerts-priority-block > p {
    margin: -4px 0 0;
    color: #64748b;
    font-size: .79rem;
    line-height: 1.35;
    font-weight: 720;
}

.co-alerts-grid.priority {
    grid-template-columns: repeat(3, minmax(0, 1fr));
}

.co-alerts-grid.informative {
    grid-template-columns: repeat(4, minmax(0, 1fr));
}

.co-alert-empty-wide {
    min-height: 96px;
    justify-content: center;
    border-radius: 18px;
    background: rgba(255, 255, 255, .76);
}

@media (max-width: 1280px) {
    .co-trend-strip {
        grid-template-columns: 1fr;
    }

    .co-trend-cards,
    .co-alerts-grid.priority,
    .co-alerts-grid.informative {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 760px) {
    .co-trend-strip {
        padding: 12px;
        border-radius: 18px;
    }

    .co-trend-cards,
    .co-alerts-grid.priority,
    .co-alerts-grid.informative {
        grid-template-columns: 1fr;
    }

    .co-alerts-toggle-count {
        align-items: flex-end;
        min-width: 92px;
    }
}

/* Ajuste extra — Popups do Centro Operacional seguindo o layout da Home / Fila de Prioridade */

.pz-resolution-modal {
    position: fixed;
    inset: 0;
    z-index: 9999;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 18px;
}

.pz-resolution-backdrop {
    position: absolute;
    inset: 0;
    background: rgba(15, 23, 42, .46);
    backdrop-filter: blur(10px);
}

.pz-resolution-shell {
    position: relative;
    z-index: 1;
    width: min(1460px, calc(100vw - 32px));
    max-height: min(94vh, 920px);
    overflow: hidden;
    border: 1px solid rgba(226, 232, 240, .92);
    border-radius: 18px;
    background: #fff;
    box-shadow: 0 34px 100px rgba(15, 23, 42, .34);
}

.pz-resolution-head {
    min-height: 74px;
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 18px;
    padding: 16px 20px;
    border-bottom: 1px solid #e5e7eb;
    background: #fff;
}

.pz-resolution-title-group {
    display: grid;
    grid-template-columns: 42px minmax(0, 1fr);
    gap: 12px;
    align-items: start;
}

.pz-resolution-icon {
    width: 40px;
    height: 40px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 14px;
    color: #4f46e5;
    background: #eef2ff;
    font-weight: 950;
}

.pz-resolution-icon.is-client {
    color: #dc2626;
    background: #fee2e2;
}

.pz-resolution-kicker {
    margin: 0 0 3px;
    color: #64748b;
    font-size: 11px;
    font-weight: 950;
    letter-spacing: .08em;
}

.pz-resolution-title-group h2 {
    margin: 0;
    color: #0f172a;
    font-size: 20px;
    line-height: 1.16;
    font-weight: 950;
    letter-spacing: -.04em;
}

.pz-resolution-title-group small {
    display: block;
    margin-top: 5px;
    color: #64748b;
    font-size: 13px;
    font-weight: 700;
}

.pz-resolution-head-actions {
    display: flex;
    align-items: center;
    gap: 10px;
}

.pz-resolution-open-link,
.pz-resolution-close,
.pz-resolution-action-list a,
.pz-resolution-action-list button {
    min-height: 38px;
    border: 1px solid #e5e7eb;
    border-radius: 10px;
    background: #fff;
    color: #0f172a;
    font-size: 13px;
    font-weight: 900;
    text-decoration: none;
}

.pz-resolution-open-link {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0 14px;
    color: #fff;
    border-color: #5b21b6;
    background: linear-gradient(135deg, #7c3aed, #4f46e5);
}

.pz-resolution-close {
    width: 38px;
    padding: 0;
    font-size: 24px;
    line-height: 1;
    cursor: pointer;
}

.pz-resolution-body {
    height: calc(min(94vh, 920px) - 74px);
    display: grid;
    grid-template-columns: 292px minmax(520px, 1fr) 330px;
    gap: 16px;
    overflow: auto;
    padding: 16px;
