    padding-top: 13px;
}

.pz-resolution-steps:before,
.pz-resolution-steps:after {
    content: '';
    position: absolute;
    top: 31px;
    left: 28px;
    right: 28px;
    height: 4px;
    border-radius: 999px;
    background: #e6edf6;
}

.pz-resolution-steps:after {
    right: auto;
    width: calc(var(--pz-progress) * 1%);
    background: linear-gradient(90deg, #2563eb, #6d28d9);
}

.pz-resolution-step {
