    border-bottom: 1px solid #edf2f7;
    color: #475569;
    font-size: 13px;
    font-weight: 850;
}

.pz-resolution-warning-box {
    margin-top: 14px;
    padding: 13px 14px;
    border-radius: 12px;
    color: #92400e;
    background: #fff7ed;
    font-size: 12px;
    font-weight: 850;
}

.pz-resolution-client-main,
.pz-resolution-owner-main {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 14px;
}

.pz-resolution-client-main > span,
.pz-resolution-owner-main > span {
    width: 44px;
    height: 44px;
    border-radius: 14px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: #2563eb;
    background: #dbeafe;
    font-weight: 950;
}

.pz-resolution-owner-main > span {
    color: #7c2d12;
    background: #fed7aa;
}

.pz-resolution-client-main strong,
.pz-resolution-owner-main strong {
    display: block;
    color: #0f172a;
    font-size: 16px;
    font-weight: 950;
}

.pz-resolution-client-main small,
.pz-resolution-owner-main small {
    color: #64748b;
    font-size: 12px;
    font-weight: 800;
}

.pz-resolution-client-kpis {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 8px;
}

.pz-resolution-client-kpis div {
    padding: 10px;
    border-radius: 10px;
    background: #f8fafc;
    display: grid;
    gap: 6px;
}

.pz-resolution-client-kpis span {
    color: #64748b;
    font-size: 10px;
    font-weight: 850;
}

.pz-resolution-contact-row {
    display: flex;
    gap: 8px;
    margin-bottom: 10px;
}

.pz-resolution-contact-row button {
    width: 34px;
    height: 34px;
    border-radius: 10px;
    border: 1px solid #e2e8f0;
    background: #fff;
    cursor: pointer;
}

.pz-resolution-list-v2 {
    display: grid;
    gap: 8px;
    margin-bottom: 10px;
}

.pz-resolution-list-v2 div {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto auto;
    gap: 8px;
    align-items: center;
    min-height: 38px;
    padding: 8px 0;
    border-bottom: 1px solid #edf2f7;
}

.pz-resolution-list-v2 b {
    color: #0f172a;
    font-size: 12px;
    font-weight: 950;
}

.pz-resolution-list-v2 span.is-pending {
    color: #ea580c;
    background: #ffedd5;
}

.pz-resolution-list-v2 span.is-validating {
    color: #2563eb;
    background: #dbeafe;
}

.pz-resolution-list-v2 button {
    min-height: 30px;
    border: 1px solid #c4b5fd;
    border-radius: 8px;
    color: #5b21f0;
    background: #faf5ff;
    font-size: 11px;
    font-weight: 950;
    cursor: pointer;
}

.pz-resolution-timeline-v2 {
    display: grid;
    gap: 10px;
}

.pz-resolution-timeline-v2 div {
    display: grid;
    grid-template-columns: 12px 64px minmax(0, 1fr);
    gap: 8px;
    align-items: start;
}

.pz-resolution-timeline-v2 span {
    width: 8px;
    height: 8px;
    margin-top: 5px;
    border-radius: 50%;
    background: #6d28d9;
}

.pz-resolution-timeline-v2 b {
    color: #475569;
    font-size: 11px;
    font-weight: 900;
}

.pz-resolution-timeline-v2 p {
    margin: 0;
    color: #334155;
    font-size: 12px;
    font-weight: 800;
}

.pz-resolution-help-card {
    background: linear-gradient(135deg, #f8fbff, #fff);
    border-color: #dbeafe;
}

.pz-resolution-help-actions {
    display: flex;
    gap: 10px;
}

.pz-resolution-help-actions button {
    min-height: 38px;
    flex: 1;
    border: 1px solid #bfdbfe;
    border-radius: 10px;
    color: #1d4ed8;
    background: #fff;
    font-size: 12px;
    font-weight: 950;
    cursor: pointer;
}

.pz-resolution-footer {
    flex: 0 0 auto;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 14px;
    padding: 14px 28px;
    border-top: 1px solid #e8edf5;
    background: #fff;
}

.pz-resolution-footer span {
    color: #475569;
    font-size: 13px;
    font-weight: 850;
}

.pz-resolution-footer b {
    padding: 6px 10px;
    border-radius: 8px;
    color: #0f172a;
    background: #f1f5f9;
}

.pz-resolution-footer div {
    display: flex;
    gap: 10px;
}

@media (max-width: 1360px) {
    .pz-resolution-top-grid,
    .pz-resolution-content-grid {
        grid-template-columns: 1fr 1fr;
    }

    .pz-resolution-progress-card,
    .pz-resolution-checklist-card {
        grid-column: span 2;
    }

    .pz-resolution-action-grid {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 980px) {
    .pz-resolution-shell-v2 {
        width: calc(100vw - 16px);
        height: calc(100vh - 16px);
        max-height: calc(100vh - 16px);
        border-radius: 16px;
    }

    .pz-resolution-v2-head,
    .pz-resolution-footer {
        display: grid;
    }

    .pz-resolution-v2-actions,
    .pz-resolution-footer div {
        flex-wrap: wrap;
    }

    .pz-resolution-top-grid,
    .pz-resolution-content-grid,
    .pz-resolution-next-action-meta {
        grid-template-columns: 1fr;
    }

    .pz-resolution-progress-card,
    .pz-resolution-checklist-card {
        grid-column: auto;
    }

    .pz-resolution-quick-grid {
        grid-template-columns: 1fr 1fr;
    }

    .pz-resolution-meta-row {
        display: grid;
        gap: 8px;
    }
}

@media (max-width: 640px) {
    .pz-resolution-modal {
        padding: 8px;
    }

    .pz-resolution-v2-body,
    .pz-resolution-v2-head,
    .pz-resolution-footer {
        padding-left: 16px;
        padding-right: 16px;
    }

    .pz-resolution-v2-title-row h2 {
        white-space: normal;
    }

    .pz-resolution-quick-grid,
    .pz-resolution-client-kpis,
    .pz-resolution-list-v2 div,
    .pz-resolution-checklist-v2 label {
        grid-template-columns: 1fr;
    }

    .pz-resolution-tabs {
        overflow-x: auto;
    }
}

/* Ajustes do popup de resolução: todos os elementos clicáveis executam ação visual ou navegação. */
.pz-resolution-action-panel {
    margin-top: 14px;
    padding: 14px;
    border: 1px solid rgba(124, 58, 237, .18);
    border-radius: 18px;
    background: linear-gradient(180deg, rgba(248, 250, 252, .96), rgba(255, 255, 255, .98));
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, .85);
}

.pz-resolution-action-panel-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 12px;
}

.pz-resolution-action-panel-head strong {
    font-size: 13px;
    color: #111827;
}

.pz-resolution-action-panel-head button {
    width: 28px;
    height: 28px;
    border: 0;
    border-radius: 999px;
    background: #f1f5f9;
    color: #475569;
