}

.pz-resolution-tabs button,
.pz-resolution-quick-grid button,
.pz-resolution-quick-grid a,
.pz-resolution-contact-row button,
.pz-resolution-list-v2 button,
.pz-resolution-primary-btn,
.pz-resolution-secondary-btn,
.pz-resolution-outline-full,
.pz-resolution-help-actions button,
.pz-clickable-row {
    cursor: pointer;
}

.pz-resolution-checklist-v2 label:has(input:checked) {
    border-color: rgba(34, 197, 94, .38);
    background: rgba(240, 253, 244, .86);
}

.pz-resolution-checklist-v2 label:has(input:checked) span,
.pz-resolution-checklist-v2 label:has(input:checked) em {
    background: #16a34a;
    color: #fff;
}

.pz-resolution-list-v2 span.is-done {
    background: rgba(34, 197, 94, .12);
    color: #15803d;
}

.pz-central-day-card {
    border: 1px solid var(--op-border);
    cursor: pointer;
    text-align: left;
    font-family: inherit;
}

.pz-central-day-card.is-filter-active {
    border-color: currentColor;
    box-shadow: 0 18px 38px rgba(15, 23, 42, .12);
    transform: translateY(-1px);
}

.pz-central-day-card.is-filter-active em {
    color: currentColor;
}

.pz-central-bell i.bi {
    font-size: 23px;
    line-height: 1;
}

.pz-section-actions {
    flex: 0 0 auto;
    display: inline-flex;
    align-items: center;
    gap: 9px;
}

.pz-section-actions > a,
.pz-clear-filter-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 38px;
    padding: 0 15px;
    border: 1px solid #dfe5ee;
    border-radius: 9px;
    background: #ffffff;
    color: #0f172a;
    font-size: 13px;
    font-weight: 850;
    transition: transform .18s ease, box-shadow .18s ease, border-color .18s ease;
}

.pz-clear-filter-btn {
    cursor: pointer;
    font-family: inherit;
    color: #dc2626;
    border-color: #fecaca;
    background: #fff7f7;
}

.pz-section-actions > a:hover,
.pz-clear-filter-btn:hover {
