/* Centro Operacional: modal padronizado com o mesmo comportamento da Home/Fila de Prioridade */
.co-home-resolution-modal {
    display: flex;
}

.co-home-resolution-modal .pz-resolution-shell-v2 {
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.co-home-resolution-modal .pz-resolution-v2-head,
.co-home-resolution-modal .pz-resolution-footer {
    flex: 0 0 auto;
}

.co-home-resolution-modal .pz-resolution-v2-body {
    flex: 1 1 auto;
    overflow-y: auto;
    min-height: 0;
}

.co-home-resolution-modal .pz-resolution-quick-grid a,
.co-home-resolution-modal .pz-resolution-list-v2 a {
    text-decoration: none;
}

.co-home-resolution-modal .co-modal-field {
    display: grid;
    gap: 8px;
    margin-top: 14px;
}

.co-home-resolution-modal .co-modal-field span {
    color: #64748b;
    font-size: .76rem;
    font-weight: 900;
    text-transform: uppercase;
}

.co-home-resolution-modal .co-modal-field select {
    width: 100%;
    border: 1px solid #dbe4f0;
    border-radius: 14px;
    background: #fff;
    color: #0f172a;
    font-weight: 800;
    padding: 13px 14px;
    outline: none;
}

.co-home-resolution-modal .co-modal-field select:focus {
    border-color: #6d28d9;
    box-shadow: 0 0 0 4px rgba(109, 40, 217, .12);
}


/* Ajuste final: modal no padrão da Home preservando o conteúdo original do Centro Operacional */
.co-home-resolution-modal .co-detail-home-shell {
    display: flex;
    flex-direction: column;
    width: min(1560px, calc(100vw - 72px));
    max-width: 1560px;
    height: min(86vh, 860px);
    max-height: calc(100vh - 56px);
    overflow: hidden;
}

.co-home-resolution-modal .co-detail-home-header {
    flex: 0 0 auto;
    display: flex;
    align-items: flex-start;
    gap: 14px;
    padding: 28px 32px 20px;
    border-bottom: 1px solid rgba(226, 232, 240, 0.9);
    background: rgba(255, 255, 255, 0.98);
}

.co-home-resolution-modal .co-detail-home-header h3 {
    margin: 6px 0 6px;
    font-size: clamp(1.35rem, 2vw, 2rem);
    line-height: 1.1;
    letter-spacing: -0.045em;
    color: #0f172a;
}

.co-home-resolution-modal .co-detail-home-header p {
    margin: 0;
    color: #64748b;
    font-weight: 700;
}

.co-home-resolution-modal .co-detail-home-scroll {
    flex: 1 1 auto;
    min-height: 0;
    overflow-y: auto;
    overflow-x: hidden;
    padding: 22px 32px 28px;
    background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
}

.co-home-resolution-modal .co-detail-home-scroll.compact {
    padding-top: 26px;
}

.co-home-resolution-modal .co-detail-home-scroll .co-detail-modal-body {
    max-height: none;
    overflow: visible;
    padding: 0;
}

.co-home-resolution-modal .co-detail-home-footer {
    flex: 0 0 auto;
    position: sticky;
    bottom: 0;
    z-index: 3;
    display: flex;
    justify-content: flex-end;
    align-items: center;
    gap: 10px;
    padding: 16px 32px;
    border-top: 1px solid rgba(226, 232, 240, 0.95);
    background: rgba(255, 255, 255, 0.96);
    box-shadow: 0 -14px 34px rgba(15, 23, 42, 0.06);
}

.co-home-resolution-modal .co-delegate-home-shell {
    width: min(720px, calc(100vw - 48px));
    height: auto;
    max-height: min(80vh, 680px);
}

.co-home-resolution-modal .co-detail-grid,
.co-home-resolution-modal .co-detail-insights-grid {
    align-items: stretch;
}

@media (max-width: 900px) {
    .co-home-resolution-modal .co-detail-home-shell {
        width: calc(100vw - 20px);
        height: calc(100vh - 28px);
        max-height: calc(100vh - 28px);
        border-radius: 22px;
    }

    .co-home-resolution-modal .co-detail-home-header,
    .co-home-resolution-modal .co-detail-home-scroll,
    .co-home-resolution-modal .co-detail-home-footer {
        padding-left: 18px;
        padding-right: 18px;
    }

    .co-home-resolution-modal .co-detail-home-footer {
        justify-content: stretch;
        flex-wrap: wrap;
    }

    .co-home-resolution-modal .co-detail-home-footer .co-action-btn {
        flex: 1 1 160px;
        justify-content: center;
    }
}

.co-executive-summary {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    padding: 1rem;
    border-radius: 1rem;
    background: linear-gradient(135deg, #fff7ed 0%, #ffffff 100%);
    border: 1px solid rgba(249, 115, 22, .22);
    margin-bottom: 1rem;
}

.co-executive-summary small,
.co-urgency-score em,
.co-critical-client-row small {
    display: block;
    color: #64748b;
    font-size: .72rem;
    font-weight: 700;
    letter-spacing: .04em;
    text-transform: uppercase;
}

.co-executive-summary strong {
    display: block;
    color: #0f172a;
    font-size: .98rem;
    line-height: 1.45;
    margin-top: .22rem;
}

.co-urgency-score {
    min-width: 104px;
    text-align: center;
    border-radius: .95rem;
    padding: .75rem .85rem;
    background: #fff;
    border: 1px solid #e2e8f0;
    box-shadow: 0 12px 24px rgba(15, 23, 42, .08);
}

.co-urgency-score b {
    display: block;
    color: #0f172a;
    font-size: 1.25rem;
    line-height: 1;
}

.co-urgency-score.danger,
.co-urgency-card.danger {
    border-color: rgba(239, 68, 68, .28);
    background: #fef2f2;
}

.co-urgency-score.warning,
.co-urgency-card.warning {
    border-color: rgba(245, 158, 11, .3);
    background: #fffbeb;
}

.co-operational-decision-grid {
    margin-top: 1rem;
}

.co-copy-message-box {
    display: grid;
    gap: .8rem;
}

.co-copy-message-box p {
    margin: 0;
    padding: .9rem;
    border-radius: .85rem;
    background: #f8fafc;
    color: #334155;
    border: 1px dashed #cbd5e1;
    line-height: 1.5;
    white-space: pre-line;
}

.co-copy-hidden {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    opacity: 0;
    pointer-events: none;
}

.co-score-line {
    display: flex;
    align-items: baseline;
    gap: .65rem;
    margin-bottom: .75rem;
}

.co-score-line strong {
    font-size: 1.8rem;
    color: #0f172a;
    line-height: 1;
}

.co-score-line span {
    color: #64748b;
    font-weight: 800;
}

.co-checkline.compact {
    padding-block: .38rem;
}

.co-critical-client-summary {
    margin-top: 1rem;
    border-color: rgba(249, 115, 22, .28) !important;
    background: #fff7ed;
}

.co-critical-client-row {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: .8rem;
}

.co-critical-client-row span {
