/* =========================================================
   Resolver Agora — layout idêntico ao mockup enviado
   ========================================================= */
.ra-modal {
    position: fixed;
    inset: 0;
    z-index: 9999;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 28px;
    font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
.ra-backdrop {
    position: absolute;
    inset: 0;
    background: rgba(2, 6, 23, .86);
    backdrop-filter: blur(3px);
}
.ra-shell {
    position: relative;
    width: min(1560px, calc(100vw - 70px));
    max-height: calc(100vh - 55px);
    overflow: hidden;
    border-radius: 11px;
    border: 1px solid rgba(226, 232, 240, .95);
    background: #ffffff;
    box-shadow: 0 28px 80px rgba(15, 23, 42, .38);
    color: #101827;
}
.ra-close {
    position: absolute;
    top: 24px;
    right: 28px;
    z-index: 5;
    width: 30px;
    height: 30px;
    border: 0;
    background: transparent;
    color: #63708a;
    font-size: 18px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
}
.ra-close:hover { color: #111827; }
.ra-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 22px;
    padding: 26px 54px 18px 34px;
}
.ra-kicker {
    display: block;
    margin-bottom: 8px;
    color: #dc1f35;
    font-size: 12px;
    font-weight: 900;
    letter-spacing: .02em;
    text-transform: uppercase;
}
.ra-title-row {
    display: flex;
    align-items: center;
    gap: 16px;
    min-width: 0;
}
.ra-title-row h2 {
    margin: 0;
    color: #111827;
    font-size: 24px;
    line-height: 1.15;
    font-weight: 850;
    letter-spacing: -.035em;
}
.ra-critical-pill,
.ra-risk-pill {
