    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 28px;
    padding: 0 14px;
    border-radius: 9px;
    border: 1px solid #ff4b5f;
    background: #fff5f6;
    color: #e11d33;
    font-size: 12px;
    font-weight: 850;
}
.ra-risk-pill { min-height: 26px; font-size: 11px; }
.ra-meta-row {
    display: flex;
    align-items: center;
    gap: 11px;
