/* Workload da Equipe - popup executivo isolado */
.co-workload-v3-backdrop {
    align-items: flex-start;
    overflow-y: auto;
    padding: 28px 18px;
}

.co-workload-v3-modal {
    width: min(1380px, 96vw) !important;
    max-width: 1380px !important;
    max-height: none !important;
    overflow: visible !important;
    padding: 0 !important;
    border-radius: 24px !important;
    background: #f6f8fc !important;
    border: 1px solid rgba(148, 163, 184, .24) !important;
    box-shadow: 0 28px 80px rgba(15, 23, 42, .26) !important;
    position: relative;
}

.co-workload-v3-x {
    top: 22px !important;
    right: 22px !important;
    z-index: 5;
    background: #fff !important;
    border: 1px solid #e2e8f0 !important;
    color: #64748b !important;
}

.co-workload-v3-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 24px;
    padding: 28px 32px 22px;
    background: linear-gradient(135deg, #ffffff 0%, #f8fafc 100%);
    border-bottom: 1px solid #e5e7eb;
    border-radius: 24px 24px 0 0;
}

.co-workload-v3-title-row {
    display: flex;
    align-items: center;
    gap: 16px;
    min-width: 0;
}

.co-workload-v3-icon {
    width: 52px;
    height: 52px;
    border-radius: 18px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: #2563eb;
    background: #dbeafe;
    font-size: 24px;
    flex: 0 0 auto;
}

.co-workload-v3-icon.danger { color: #dc2626; background: #fee2e2; }

.co-workload-v3-header h3 {
    margin: 0;
    font-size: 24px;
    line-height: 1.1;
    font-weight: 800;
    color: #0f172a;
}

.co-workload-v3-header p {
    margin: 7px 0 0;
    color: #64748b;
    font-size: 13px;
}

.co-workload-v3-person {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 8px;
}

.co-workload-v3-person strong {
    font-size: 16px;
    color: #111827;
}

.co-workload-v3-person span {
    border-radius: 999px;
    background: #eef2ff;
    color: #4338ca;
    font-size: 11px;
    font-weight: 800;
    padding: 5px 10px;
    text-transform: uppercase;
    letter-spacing: .03em;
}

.co-workload-v3-header-actions {
    display: flex;
    align-items: center;
    gap: 10px;
    padding-right: 46px;
}

.co-workload-v3-header-actions button {
    border: 1px solid #dbe3ef;
    background: #fff;
    color: #334155;
    border-radius: 12px;
    height: 38px;
    padding: 0 14px;
    font-weight: 700;
    font-size: 13px;
    box-shadow: 0 8px 18px rgba(15, 23, 42, .06);
}

.co-workload-v3-header-actions button:last-child {
    width: 38px;
    padding: 0;
}

.co-workload-v3-kpis {
    display: grid;
    grid-template-columns: repeat(6, minmax(0, 1fr));
    gap: 14px;
    padding: 22px 32px 10px;
}

.co-workload-v3-kpi,
.co-workload-v3-panel {
    background: #fff;
    border: 1px solid #e6ebf3;
    border-radius: 18px;
    box-shadow: 0 14px 32px rgba(15, 23, 42, .07);
}

.co-workload-v3-kpi {
    min-height: 156px;
    padding: 18px;
    display: flex;
    flex-direction: column;
    gap: 7px;
}

.co-workload-v3-kpi > span {
    color: #64748b;
    font-size: 12px;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: .04em;
}

.co-workload-v3-kpi > strong {
    font-size: 30px;
    line-height: 1;
    font-weight: 900;
    color: #0f172a;
}

.co-workload-v3-kpi p,
.co-workload-v3-kpi small {
    margin: 0;
    color: #64748b;
    font-size: 13px;
}

.co-workload-v3-kpi p b { color: #0f172a; }
.co-workload-v3-kpi b.danger { color: #dc2626; }
.co-workload-v3-kpi b.ok { color: #16a34a; }

.co-workload-v3-kpi.impact {
    background: linear-gradient(135deg, #fff1f2 0%, #fff 70%);
    border-color: #fecdd3;
}
.co-workload-v3-kpi.impact > strong { color: #b91c1c; font-size: 17px; line-height: 1.25; }
.co-workload-v3-kpi.impact p { color: #dc2626; font-size: 22px; font-weight: 900; }

.co-workload-v3-gauge {
    width: 82px;
    height: 82px;
    border-radius: 50%;
    display: grid;
    place-items: center;
    margin: 2px auto 0;
