/* Lote A - foco seguro em pendências do usuário / prioridades operacionais */
.compliance-personal-focus {
    margin-top: 1rem;
}

.compliance-personal-focus-card {
    border: 1px solid rgba(248, 113, 113, 0.28);
    background:
        radial-gradient(circle at top left, rgba(248, 113, 113, 0.12), transparent 30rem),
        var(--compliance-card-bg, #ffffff);
}

.compliance-personal-focus-card > header {
    align-items: flex-start;
}

.compliance-personal-focus-grid {
    display: grid;
    grid-template-columns: minmax(13rem, 0.35fr) minmax(0, 1fr);
    gap: 1rem;
    margin-top: 1rem;
}

