    line-height: 1;
    font-weight: 800;
}

.compliance-personal-focus-summary span {
    font-size: 0.85rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.compliance-personal-focus-summary p {
    margin: 0.35rem 0 0;
    color: var(--compliance-muted, #64748b);
    font-size: 0.9rem;
}

.compliance-personal-focus-list {
    min-width: 0;
}

@media (max-width: 900px) {
    .compliance-personal-focus-grid {
        grid-template-columns: 1fr;
