/* Lote C refeito - feedback e fluidez seguros para Governança > Interno */
.compliance-page-interno {
    scroll-behavior: smooth;
}

.compliance-interno-toast {
    position: sticky;
    top: .75rem;
    z-index: 30;
    display: flex;
    align-items: center;
    gap: .55rem;
    margin-bottom: .85rem;
    border: 1px solid rgba(59, 130, 246, .24);
    border-radius: 1rem;
    background: rgba(239, 246, 255, .96);
    box-shadow: 0 16px 36px rgba(15, 23, 42, .12);
    color: #1e3a8a;
    font-size: .88rem;
    font-weight: 850;
    line-height: 1.35;
    padding: .85rem 1rem;
    opacity: 0;
    transform: translateY(-.4rem);
    transition: opacity .2s ease, transform .2s ease;
}

.compliance-interno-toast::before {
    content: "✓";
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.35rem;
    height: 1.35rem;
    flex: 0 0 1.35rem;
    border-radius: 999px;
    background: rgba(37, 99, 235, .16);
    color: #1d4ed8;
    font-size: .78rem;
    font-weight: 950;
}

.compliance-interno-toast[data-tone="success"] {
    border-color: rgba(34, 197, 94, .24);
    background: rgba(240, 253, 244, .96);
    color: #14532d;
}

.compliance-interno-toast[data-tone="success"]::before {
    background: rgba(34, 197, 94, .16);
    color: #15803d;
}

.compliance-interno-toast.is-visible {
    opacity: 1;
    transform: translateY(0);
}

.dark .compliance-interno-toast {
    border-color: rgba(96, 165, 250, .24);
    background: rgba(15, 23, 42, .94);
    color: #bfdbfe;
    box-shadow: 0 18px 38px rgba(0, 0, 0, .25);
}

.dark .compliance-interno-toast::before {
    background: rgba(96, 165, 250, .18);
    color: #bfdbfe;
}

.dark .compliance-interno-toast[data-tone="success"] {
    border-color: rgba(74, 222, 128, .26);
    background: rgba(20, 83, 45, .36);
    color: #bbf7d0;
}

.compliance-page-interno .compliance-row-readable {
    transition: transform .16s ease, border-color .16s ease, box-shadow .16s ease, opacity .16s ease, background .16s ease;
}

.compliance-page-interno .compliance-row-readable:hover,
.compliance-page-interno .compliance-row-readable:focus-within {
    transform: translateY(-1px);
    border-color: rgba(37, 99, 235, .28);
    box-shadow: 0 14px 30px rgba(15, 23, 42, .075);
}

.dark .compliance-page-interno .compliance-row-readable:hover,
.dark .compliance-page-interno .compliance-row-readable:focus-within {
    border-color: rgba(96, 165, 250, .24);
    box-shadow: 0 14px 30px rgba(0, 0, 0, .2);
}

.compliance-page-interno .compliance-action-button,
.compliance-page-interno .compliance-detail-trigger,
.compliance-interno-filament-modal .compliance-action-button {
    position: relative;
    overflow: hidden;
    transition: transform .15s ease, box-shadow .15s ease, opacity .15s ease, background .15s ease, border-color .15s ease;
}

.compliance-page-interno .compliance-action-button:hover,
.compliance-page-interno .compliance-detail-trigger:hover,
.compliance-interno-filament-modal .compliance-action-button:hover,
.compliance-page-interno .compliance-action-button:focus-visible,
.compliance-page-interno .compliance-detail-trigger:focus-visible,
.compliance-interno-filament-modal .compliance-action-button:focus-visible {
    transform: translateY(-1px);
    box-shadow: 0 10px 22px rgba(15, 23, 42, .12);
    outline: none;
}

.compliance-page-interno .compliance-action-button.is-loading,
.compliance-page-interno .compliance-detail-trigger.is-loading,
.compliance-interno-filament-modal .compliance-action-button.is-loading {
    pointer-events: none;
    opacity: .78;
}

.compliance-page-interno .compliance-action-button.is-loading::after,
.compliance-page-interno .compliance-detail-trigger.is-loading::after,
.compliance-interno-filament-modal .compliance-action-button.is-loading::after {
    content: "";
    position: absolute;
    inset: auto .55rem auto auto;
    width: .8rem;
    height: .8rem;
    border-radius: 999px;
    border: 2px solid currentColor;
    border-right-color: transparent;
    animation: complianceInternoSpin .7s linear infinite;
}

.compliance-page-interno.has-interno-action-feedback .compliance-row-readable:focus-within {
    background: linear-gradient(135deg, rgba(239, 246, 255, .98), rgba(255, 255, 255, .96));
}

.dark .compliance-page-interno.has-interno-action-feedback .compliance-row-readable:focus-within {
    background: linear-gradient(135deg, rgba(30, 64, 175, .22), rgba(15, 23, 42, .78));
}

@keyframes complianceInternoSpin {
    to {
        transform: rotate(360deg);
    }
}

@media (prefers-reduced-motion: reduce) {
    .compliance-interno-toast,
    .compliance-page-interno .compliance-row-readable,
    .compliance-page-interno .compliance-action-button,
    .compliance-page-interno .compliance-detail-trigger,
    .compliance-interno-filament-modal .compliance-action-button {
        transition: none;
    }

    .compliance-page-interno .compliance-action-button:hover,
    .compliance-page-interno .compliance-detail-trigger:hover,
    .compliance-interno-filament-modal .compliance-action-button:hover,
    .compliance-page-interno .compliance-row-readable:hover,
    .compliance-page-interno .compliance-row-readable:focus-within {
        transform: none;
    }
}

/* Lote 1 - Pendências: leitura operacional, hierarquia visual e foco do dia. */
.pendencias-lote1-page {
    gap: 1.15rem;
}

.pendencias-lote1-hero {
    position: relative;
    overflow: hidden;
}

.pendencias-lote1-hero::after {
    content: "";
    position: absolute;
    inset: auto -6rem -7rem auto;
    width: 18rem;
    height: 18rem;
    border-radius: 999px;
    background: rgba(255, 255, 255, .12);
    pointer-events: none;
}

.pendencias-lote1-hero > * {
    position: relative;
    z-index: 1;
}

.pendencias-lote1-hero-actions {
    min-width: 220px;
}

.pendencias-lote1-toolbar {
    margin-bottom: 0;
}

.pendencias-lote1-command {
    display: grid;
    grid-template-columns: minmax(260px, .7fr) minmax(0, 1.3fr);
    gap: 1rem;
    align-items: stretch;
    border: 1px solid rgba(148, 163, 184, .22);
    border-radius: 1.35rem;
    background: linear-gradient(135deg, rgba(255, 255, 255, .96), rgba(248, 250, 252, .92));
    box-shadow: 0 16px 35px rgba(15, 23, 42, .07);
    padding: 1rem;
}

.dark .pendencias-lote1-command {
    background: linear-gradient(135deg, rgba(15, 23, 42, .78), rgba(30, 41, 59, .64));
    border-color: rgba(148, 163, 184, .16);
}

.pendencias-lote1-command-copy {
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: .35rem;
}

.pendencias-lote1-command-copy h2 {
    margin: .25rem 0 0;
    color: #0f172a;
    font-size: 1.25rem;
    font-weight: 950;
}

.dark .pendencias-lote1-command-copy h2 {
    color: #f8fafc;
}

.pendencias-lote1-command-copy p {
    margin: 0;
