.pendencias-lote4-filter-chip.warning.active { background: rgba(254, 243, 199, .78); border-color: rgba(245, 158, 11, .34); }
.pendencias-lote4-filter-chip.info.active { background: rgba(219, 234, 254, .78); border-color: rgba(59, 130, 246, .34); }
