.dark .pendencias-lote4-filter-chip.warning.active { background: rgba(120, 53, 15, .30); }
.dark .pendencias-lote4-filter-chip.info.active { background: rgba(30, 64, 175, .26); }
.dark .pendencias-lote4-filter-chip.ok.active { background: rgba(20, 83, 45, .28); }

.pendencias-lote4-search-row {
    display: flex;
