}

.pendencias-lote5-advanced-card span {
    display: block;
    color: #64748b;
    font-size: .72rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: .06em;
    margin-bottom: .25rem;
}

.pendencias-lote5-advanced-card strong {
    display: block;
    color: inherit;
    font-size: .98rem;
    line-height: 1.25;
}

.pendencias-lote5-advanced-card small {
    display: block;
