/* Lote 6 - consolidação, polimento e feedback operacional */
.pendencias-lote6-livewire-loading {
    position: sticky;
    top: .75rem;
    z-index: 35;
    display: none;
    align-items: center;
    justify-content: center;
    gap: .55rem;
    width: fit-content;
    max-width: 100%;
    margin: 0 auto -.25rem;
    padding: .6rem .9rem;
    border: 1px solid rgba(59, 130, 246, .22);
    border-radius: 999px;
    background: rgba(239, 246, 255, .96);
    color: #1d4ed8;
    font-size: .82rem;
    font-weight: 800;
    box-shadow: 0 16px 35px rgba(15, 23, 42, .12);
    backdrop-filter: blur(12px);
}

.pendencias-lote6-consolidation {
    display: grid;
    grid-template-columns: minmax(0, 1.05fr) minmax(280px, 1.45fr);
    gap: 1.1rem;
    align-items: stretch;
    border: 1px solid rgba(30, 64, 175, .11);
