.pendencias-lote6-health-card span,
.pendencias-lote6-route-guide span {
    display: block;
    color: #64748b;
    font-size: .75rem;
    font-weight: 800;
    letter-spacing: .02em;
}

.pendencias-lote6-health-card strong {
    display: block;
    margin: .25rem 0;
    font-size: 1.85rem;
    line-height: 1;
    color: #0f172a;
