.pendencias-lote6-health-card.warning { border-color: rgba(245, 158, 11, .22); background: linear-gradient(180deg, rgba(255,251,235,.92), #fff); }
.pendencias-lote6-health-card.info { border-color: rgba(59, 130, 246, .2); background: linear-gradient(180deg, rgba(239,246,255,.92), #fff); }
.pendencias-lote6-health-card.ok { border-color: rgba(34, 197, 94, .2); background: linear-gradient(180deg, rgba(240,253,244,.92), #fff); }

