/* Popup global de resolução — padrão inspirado na Central de Aprovações.
   Mantém o modal fora dos cards/tabelas para evitar conflito de overflow, z-index e Alpine/Livewire. */
.documentos-modal-backdrop {
    position: fixed;
    inset: 0;
    z-index: 9999;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px;
    background: rgba(15, 23, 42, 0.68);
    backdrop-filter: blur(8px);
}

.documentos-modal-card {
    width: min(960px, 100%);
    max-height: min(88vh, 920px);
    overflow: auto;
    border-radius: 28px;
    border: 1px solid rgba(226, 232, 240, 0.92);
    background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
    box-shadow: 0 30px 80px rgba(15, 23, 42, 0.34);
}

.documentos-modal-card--wide {
    width: min(1040px, 100%);
}

.documentos-modal-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 20px;
    padding: 26px 28px 0;
}

.documentos-modal-header h2 {
    margin: 4px 0 6px;
    color: #0f172a;
    font-size: clamp(1.35rem, 2.4vw, 2rem);
    font-weight: 850;
    letter-spacing: -0.04em;
}

.documentos-modal-header p {
    margin: 0;
    max-width: 760px;
    color: #64748b;
    font-size: 0.95rem;
    line-height: 1.55;
}

.documentos-modal-close {
    display: inline-flex;
    width: 42px;
    height: 42px;
    align-items: center;
    justify-content: center;
    flex: 0 0 auto;
    border: 1px solid rgba(203, 213, 225, 0.9);
    border-radius: 999px;
    background: #ffffff;
    color: #334155;
    font-size: 1.55rem;
    line-height: 1;
    cursor: pointer;
    box-shadow: 0 12px 28px rgba(15, 23, 42, 0.08);
    transition: transform 0.16s ease, box-shadow 0.16s ease, border-color 0.16s ease;
}

.documentos-modal-close:hover,
.documentos-modal-close:focus-visible {
    transform: translateY(-1px);
    border-color: rgba(59, 130, 246, 0.55);
    box-shadow: 0 16px 36px rgba(15, 23, 42, 0.14);
    outline: none;
}

.documentos-resolver-form--dialog {
    gap: 18px;
    padding: 0 28px 28px;
}

.documentos-resolver-footer--dialog {
    position: sticky;
    bottom: 0;
    z-index: 2;
    margin: 4px -28px -28px;
    padding: 18px 28px;
    border-top: 1px solid rgba(226, 232, 240, 0.95);
    border-radius: 0 0 28px 28px;
    background: rgba(248, 250, 252, 0.96);
    backdrop-filter: blur(12px);
}

.documentos-modal-actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: 10px;
}

.dark .documentos-modal-card {
    border-color: rgba(51, 65, 85, 0.92);
    background: linear-gradient(180deg, #0f172a 0%, #111827 100%);
}

.dark .documentos-modal-header h2 {
    color: #f8fafc;
}

.dark .documentos-modal-header p {
    color: #94a3b8;
}

.dark .documentos-modal-close {
    border-color: rgba(71, 85, 105, 0.9);
    background: #111827;
    color: #e2e8f0;
}

.dark .documentos-resolver-footer--dialog {
    border-top-color: rgba(51, 65, 85, 0.95);
    background: rgba(15, 23, 42, 0.96);
}

@media (max-width: 760px) {
    .documentos-modal-backdrop {
        align-items: flex-end;
        padding: 12px;
    }

    .documentos-modal-card,
    .documentos-modal-card--wide {
        width: 100%;
        max-height: 92vh;
        border-radius: 22px;
    }

    .documentos-modal-header {
        padding: 22px 20px 0;
    }

    .documentos-resolver-form--dialog {
        padding: 0 20px 20px;
    }

    .documentos-resolver-footer--dialog {
        margin: 4px -20px -20px;
        padding: 16px 20px;
    }
}


.documentos-prioridade-inteligente {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(280px, 360px);
    gap: 1rem;
    align-items: stretch;
    margin: 1rem 0;
    padding: 1.25rem;
    border-radius: 1.25rem;
    border: 1px solid rgba(148, 163, 184, .24);
    background: linear-gradient(135deg, rgba(255,255,255,.96), rgba(248,250,252,.92));
    box-shadow: 0 18px 45px rgba(15, 23, 42, .08);
}

.documentos-prioridade-inteligente.danger {
    border-color: rgba(239, 68, 68, .32);
    background: linear-gradient(135deg, rgba(254, 242, 242, .98), rgba(255, 255, 255, .94));
}

.documentos-prioridade-inteligente.warning {
    border-color: rgba(245, 158, 11, .34);
    background: linear-gradient(135deg, rgba(255, 251, 235, .98), rgba(255, 255, 255, .94));
}

.documentos-prioridade-inteligente.primary {
    border-color: rgba(59, 130, 246, .28);
    background: linear-gradient(135deg, rgba(239, 246, 255, .98), rgba(255, 255, 255, .94));
}

.documentos-prioridade-inteligente.success {
    border-color: rgba(34, 197, 94, .24);
    background: linear-gradient(135deg, rgba(240, 253, 244, .96), rgba(255, 255, 255, .94));
}

.documentos-prioridade-inteligente__content h2 {
    margin: .25rem 0 .35rem;
    font-size: clamp(1.25rem, 2vw, 1.65rem);
    line-height: 1.12;
    font-weight: 800;
    color: #0f172a;
}

.documentos-prioridade-inteligente__content p {
    max-width: 760px;
    margin: 0;
    color: #475569;
    line-height: 1.6;
}

.documentos-prioridade-inteligente__meta {
    display: flex;
    flex-wrap: wrap;
    gap: .5rem;
    margin-top: .9rem;
}

.documentos-prioridade-inteligente__meta span {
    display: inline-flex;
    align-items: center;
    gap: .35rem;
    padding: .42rem .7rem;
    border-radius: 999px;
    background: rgba(255,255,255,.78);
    border: 1px solid rgba(148, 163, 184, .22);
    color: #475569;
    font-size: .82rem;
    font-weight: 700;
}

.documentos-prioridade-inteligente__meta strong {
    color: #0f172a;
}

.documentos-prioridade-inteligente__action {
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: .55rem;
    padding: 1rem;
    border-radius: 1rem;
    background: rgba(15, 23, 42, .92);
    color: #fff;
    box-shadow: inset 0 1px 0 rgba(255,255,255,.08);
}

.documentos-prioridade-inteligente__action strong {
    font-size: 1rem;
    line-height: 1.3;
}

.documentos-prioridade-inteligente__action small {
    color: rgba(255,255,255,.74);
