}

.documentos-prioridade-inteligente__action a {
    color: #bfdbfe;
    font-weight: 800;
    text-decoration: none;
}

.documentos-prioridade-inteligente__action a:hover {
    color: #ffffff;
    text-decoration: underline;
}

@media (max-width: 900px) {
    .documentos-prioridade-inteligente {
        grid-template-columns: 1fr;
        padding: 1rem;
    }
}

/* Lote Extra 2 — Fluxo contínuo de resolução */
.documentos-fluxo-continuo {
    display: grid;
    grid-template-columns: minmax(0, 1.45fr) minmax(280px, .55fr);
    gap: 1rem;
    align-items: stretch;
    padding: 1rem;
    margin: 1rem 0;
    border: 1px solid rgba(148, 163, 184, .24);
    border-radius: 1.25rem;
    background: linear-gradient(135deg, rgba(255,255,255,.96), rgba(248,250,252,.92));
    box-shadow: 0 18px 48px rgba(15, 23, 42, .08);
}

.documentos-fluxo-continuo.ativo {
    border-color: rgba(245, 158, 11, .38);
    background: linear-gradient(135deg, rgba(255,251,235,.94), rgba(255,255,255,.98));
}

.documentos-fluxo-continuo.concluido {
    border-color: rgba(34, 197, 94, .35);
    background: linear-gradient(135deg, rgba(240,253,244,.94), rgba(255,255,255,.98));
}

.documentos-fluxo-continuo__content h2 {
    margin: .15rem 0 .35rem;
    font-size: 1.15rem;
    font-weight: 800;
