}

.documentos-fluxo-continuo__feedback {
    display: grid;
    gap: .2rem;
    margin-top: .85rem;
    padding: .75rem .85rem;
    border-radius: 1rem;
    border: 1px solid rgba(34, 197, 94, .25);
