}

.documentos-fluxo-continuo__feedback strong {
    font-size: .9rem;
    font-weight: 800;
}

.documentos-fluxo-continuo__feedback span {
    font-size: .82rem;
}

.documentos-fluxo-continuo__panel {
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: .5rem;
    padding: .95rem;
    border-radius: 1rem;
    background: rgba(255,255,255,.84);
    border: 1px solid rgba(148, 163, 184, .22);
}

.documentos-fluxo-continuo__panel > span {
    width: max-content;
    max-width: 100%;
    padding: .25rem .55rem;
    border-radius: 999px;
    font-size: .72rem;
    font-weight: 800;
    color: rgb(146, 64, 14);
    background: rgba(254, 243, 199, .92);
}

.documentos-fluxo-continuo__panel strong {
    color: rgb(15, 23, 42);
    font-size: .98rem;
    line-height: 1.25;
}

.documentos-fluxo-continuo__panel small {
    color: rgb(71, 85, 105);
    line-height: 1.45;
}

.documentos-fluxo-continuo__panel a {
    display: inline-flex;
    justify-content: center;
    align-items: center;
    min-height: 2.35rem;
    padding: .55rem .85rem;
    border-radius: .8rem;
    font-weight: 800;
    text-decoration: none;
    color: rgb(21, 128, 61);
    background: rgba(220, 252, 231, .85);
    border: 1px solid rgba(34, 197, 94, .25);
}

@media (max-width: 900px) {
    .documentos-fluxo-continuo {
        grid-template-columns: 1fr;
    }
}
