/* === LOTE 8 | gestao-documental-enterprise.css === */
.gd-page {
    display: flex;
    flex-direction: column;
    gap: 22px;
}

.gd-hero,
.gd-card,
.gd-score-card,
.gd-today-card,
.gd-doc,
.gd-kpi {
    background: #ffffff;
    border: 1px solid #e5e7eb;
    box-shadow: 0 14px 36px rgba(15, 23, 42, 0.06);
}

.gd-hero {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 22px;
    padding: 28px;
    border-radius: 28px;
    overflow: hidden;
    position: relative;
}

.gd-hero::after {
    content: '';
    position: absolute;
    right: -90px;
    top: -120px;
    width: 260px;
    height: 260px;
    border-radius: 999px;
    background: rgba(37, 99, 235, 0.10);
}

.gd-hero-content,
.gd-hero-actions {
    position: relative;
    z-index: 1;
}

.gd-eyebrow {
    color: #2563eb;
    font-size: 12px;
    font-weight: 900;
    letter-spacing: .08em;
    text-transform: uppercase;
}

.gd-title {
    margin: 6px 0 0;
    color: #0f172a;
    font-size: 30px;
    line-height: 1.15;
    font-weight: 950;
}

.gd-subtitle {
    margin: 10px 0 0;
    max-width: 860px;
    color: #64748b;
    font-size: 14px;
    line-height: 1.65;
}

.gd-hero-actions,
.gd-filter-actions,
.gd-doc-side,
.gd-empty-actions {
    display: flex;
    gap: 10px;
}

.gd-hero-actions {
    flex-wrap: wrap;
    justify-content: flex-end;
}

.gd-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 40px;
    padding: 9px 15px;
    border-radius: 14px;
    border: 1px solid #d1d5db;
    background: #ffffff;
    color: #334155;
    font-size: 13px;
    font-weight: 850;
    text-decoration: none;
    cursor: pointer;
    transition: transform .18s ease, box-shadow .18s ease, border-color .18s ease, background .18s ease;
}

.gd-btn:hover {
    transform: translateY(-1px);
    border-color: #94a3b8;
    box-shadow: 0 8px 18px rgba(15, 23, 42, 0.08);
}

.gd-btn-primary {
    border-color: #2563eb;
    background: #2563eb;
    color: #ffffff;
}

.gd-command-center {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 260px;
    gap: 16px;
}

.gd-score-card {
