    gap: 24px;
    align-items: center;
    border-radius: 24px;
    padding: 22px;
}

.gd-score-label,
.gd-today-card span {
    color: #64748b;
    font-size: 13px;
    font-weight: 850;
}

.gd-score-value,
.gd-today-card strong {
