    font-weight: 900;
}

.gd-doc-side {
    flex-direction: column;
}

.gd-mini-score {
    padding: 14px;
    border-radius: 18px;
    background: #f8fafc;
    text-align: center;
}

.gd-mini-score strong {
    font-size: 22px;
}

.gd-company {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 13px;
    border-radius: 16px;
    background: #f8fafc;
