    margin-top: 4px;
    color: #64748b;
    font-size: 12px;
}

.gd-company b {
    color: #0f172a;
    font-size: 16px;
    font-weight: 950;
}

.gd-critical-list a {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 12px;
    padding: 13px;
    border-radius: 16px;
    background: #f8fafc;
    color: #334155;
    text-decoration: none;
    font-size: 13px;
    font-weight: 900;
