.gd-critical-list strong {
    display: inline-flex;
    min-width: 34px;
    height: 28px;
    align-items: center;
    justify-content: center;
    border-radius: 999px;
    background: #ffffff;
    color: #0f172a;
    border: 1px solid #e5e7eb;
