    border-color: #1f2937;
    box-shadow: none;
}

.dark .gd-title,
.dark .gd-score-value,
.dark .gd-today-card strong,
.dark .gd-kpi strong,
.dark .gd-section-title,
.dark .gd-doc-title,
.dark .gd-meta strong,
.dark .gd-mini-score strong,
