.dark .gd-today-card small,
.dark .gd-kpi small,
.dark .gd-section-subtitle,
.dark .gd-doc-desc,
.dark .gd-company span,
.dark .gd-muted-box,
.dark .gd-timeline-item,
.dark .gd-priority-head span,
.dark .gd-priority-item small,
.dark .gd-action-card small {
