}

.dark .gd-field input,
.dark .gd-field select,
.dark .gd-btn,
.dark .gd-action-card,
.dark .gd-priority-lane,
.dark .gd-priority-item,
.dark .gd-priority-stats span,
.dark .gd-meta div,
.dark .gd-mini-score,
.dark .gd-company,
.dark .gd-critical-list a,
.dark .gd-muted-box,
.dark .gd-empty {
    background: #0f172a;
    border-color: #334155;
    color: #e5e7eb;
}

.dark .gd-score-bar {
    background: #334155;
}

@media (max-width: 1400px) {
    .gd-filters {
        grid-template-columns: repeat(4, minmax(0, 1fr));
    }

    .gd-field-search {
        grid-column: span 4;
    }
}

@media (max-width: 1280px) {
    .gd-action-grid,
    .gd-priority-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .gd-grid-main {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 960px) {
    .gd-hero,
    .gd-score-card,
    .gd-doc-main,
    .gd-command-center {
        grid-template-columns: 1fr;
    }

    .gd-hero {
        display: block;
    }

    .gd-hero-actions {
        justify-content: flex-start;
        margin-top: 18px;
    }

    .gd-kpis {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .gd-score-card,
    .gd-doc-main {
        display: grid;
    }

    .gd-meta {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .gd-doc-side {
        flex-direction: row;
        flex-wrap: wrap;
    }

    .gd-filters {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .gd-field-search {
        grid-column: span 2;
    }
}

@media (max-width: 680px) {
    .gd-hero,
    .gd-card,
    .gd-score-card,
    .gd-today-card,
    .gd-doc,
    .gd-kpi {
        border-radius: 18px;
        padding: 16px;
    }

    .gd-title {
        font-size: 24px;
    }

    .gd-kpis,
    .gd-filters,
    .gd-action-grid,
    .gd-priority-grid,
    .gd-meta {
        grid-template-columns: 1fr;
    }

    .gd-field-search {
        grid-column: auto;
    }

    .gd-btn,
    .gd-filter-actions,
    .gd-hero-actions,
    .gd-doc-side {
        width: 100%;
    }

    .gd-filter-actions,
    .gd-hero-actions,
    .gd-doc-side {
        flex-direction: column;
    }

    .gd-timeline-item {
        flex-direction: column;
        gap: 2px;
    }
}
