    inset: 0;
    z-index: 60;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 22px;
    background: rgba(15, 23, 42, .55);
    backdrop-filter: blur(5px);
}

.tp-modal {
    width: min(1180px, 100%);
    max-height: calc(100vh - 44px);
    overflow: auto;
    border-radius: 26px;
    background: #fff;
    box-shadow: 0 30px 80px rgba(15, 23, 42, .34);
}

.tp-modal-head,
.tp-modal-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 16px;
    padding: 22px;
    border-bottom: 1px solid #e5e7eb;
}

.tp-modal-head h3,
.tp-modal-header h3 {
    margin: 4px 0 4px;
    font-size: 22px;
    color: #111827;
}

.tp-modal-head p,
.tp-modal-header p {
    margin: 0;
    color: #6b7280;
}

.tp-eyebrow-dark {
    font-size: 11px;
    font-weight: 900;
    letter-spacing: .15em;
    color: #2563eb;
}

.tp-modal-close {
    width: 38px;
    height: 38px;
    border-radius: 14px;
    border: 1px solid #e5e7eb;
    background: #f9fafb;
    color: #111827;
    font-size: 24px;
    line-height: 1;
    cursor: pointer;
}

.tp-modal-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 310px;
    gap: 18px;
    padding: 22px;
}

.tp-modal-main,
.tp-modal-side,
.tp-action-stack,
.tp-checklist-box,
.tp-comments-box {
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.tp-detail-card,
.tp-info-card,
.tp-modal-section {
    padding: 18px;
    border-radius: 20px;
    background: #fff;
    border: 1px solid #e5e7eb;
    box-shadow: 0 10px 24px rgba(15, 23, 42, .05);
}

.tp-detail-title {
