}

.tp-inline-form {
    grid-template-columns: minmax(0, 1fr) auto;
}

.tp-inline-form button,
.tp-comment-form button,
.tp-action-stack button,
.tp-open-record {
    border: none;
    border-radius: 14px;
    background: #2563eb;
    color: #fff;
    font-weight: 900;
    padding: 11px 14px;
