}

.tp-comment small {
    color: #6b7280;
}

.tp-info-list p {
    display: flex;
    justify-content: space-between;
    gap: 12px;
    margin: 12px 0 0;
    padding-top: 12px;
    border-top: 1px solid #e5e7eb;
}

.tp-info-list span {
    color: #6b7280;
}

.tp-info-list b {
    color: #111827;
    text-align: right;
}

.tp-grid-calendar-pro {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 340px;
    gap: 18px;
    align-items: start;
}

.tp-calendar-actions {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    justify-content: flex-end;
    align-items: center;
}

.tp-month {
