}

.tp-calendar-day.is-muted {
    background: #f9fafb;
    opacity: .72;
}

.tp-calendar-day.is-today {
    border-color: #2563eb;
    box-shadow: 0 0 0 3px rgba(37, 99, 235, .12);
}

.tp-calendar-day.has-late {
    border-color: #fecaca;
    background: #fff7f7;
}

.tp-calendar-day-head {
    display: flex;
    justify-content: space-between;
