    margin-bottom: 8px;
}

.tp-calendar-day-head strong {
    color: #111827;
}

.tp-calendar-day-head span {
    color: #6b7280;
    font-size: 12px;
    font-weight: 800;
}

.tp-calendar-day-items {
    display: flex;
    flex-direction: column;
    gap: 7px;
}

.tp-calendar-card,
.tp-calendar-mini-card {
