}

.tp-calendar-card span,
.tp-calendar-card small,
.tp-calendar-mini-card strong,
.tp-calendar-mini-card span {
    display: block;
}

.tp-calendar-card span,
.tp-calendar-mini-card strong {
    color: #111827;
    font-weight: 800;
    font-size: 12px;
}

.tp-calendar-card small,
.tp-calendar-mini-card span {
    margin-top: 3px;
    color: #6b7280;
    font-size: 11px;
}

.tp-calendar-card.is-late,
.tp-calendar-mini-card.is-late {
    border-color: #fecaca;
    background: #fee2e2;
}

.tp-calendar-more-wrap {
    position: relative;
}

.tp-more-items {
    list-style: none;
    cursor: pointer;
    color: #2563eb;
    font-size: 12px;
    font-weight: 900;
}

.tp-more-items::-webkit-details-marker {
    display: none;
}

.tp-calendar-more-popover {
    position: absolute;
    top: 26px;
    left: 0;
    z-index: 20;
    width: 260px;
    padding: 12px;
    border-radius: 16px;
    border: 1px solid #e5e7eb;
    background: #fff;
    box-shadow: 0 20px 50px rgba(15, 23, 42, .18);
}

.tp-calendar-more-head {
    display: flex;
    justify-content: space-between;
    gap: 10px;
    margin-bottom: 10px;
}

.tp-calendar-more-head strong {
    color: #111827;
}

.tp-calendar-more-head span {
    color: #6b7280;
    font-size: 12px;
}

.tp-calendar-more-list,
.tp-calendar-side,
.tp-list,
.tp-list-compact,
.tp-check-mini-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.tp-list-row,
.tp-list-button,
.tp-list-link {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto;
    gap: 12px;
    align-items: center;
    padding: 12px;
    border-radius: 16px;
    border: 1px solid #e5e7eb;
    background: #fff;
    text-align: left;
    text-decoration: none;
    color: inherit;
}

.tp-list-button {
    width: 100%;
    cursor: pointer;
}

.tp-list-row:hover,
.tp-list-button:hover,
.tp-list-link:hover {
    border-color: #bfdbfe;
    background: #f8fafc;
}

.tp-list-main strong,
.tp-list-main span {
    display: block;
}

.tp-list-main strong {
    color: #111827;
}

.tp-list-main span {
    margin-top: 3px;
    color: #6b7280;
    font-size: 12px;
}

.tp-list-row b {
    color: #111827;
    font-size: 12px;
}

.tp-check,
.tp-check-mini {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    border-radius: 12px;
    background: #fee2e2;
    color: #b91c1c;
    font-weight: 900;
}

.tp-check.is-done,
.tp-check-mini.is-done {
    background: #dcfce7;
    color: #15803d;
}

.tp-check-mini {
    width: 24px;
    height: 24px;
    border-radius: 999px;
    font-size: 12px;
}

.tp-calendar-empty-day {
    color: #9ca3af;
    font-size: 12px;
    padding: 8px 0;
}

.tp-action-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 10px;
}

.tp-action-grid button {
    border: none;
    border-radius: 14px;
    padding: 11px;
    background: #111827;
    color: #fff;
    font-weight: 900;
    cursor: pointer;
}

.tp-modal-body,
.tp-modal-footer {
    padding: 18px 22px;
}

.tp-modal-footer {
    border-top: 1px solid #e5e7eb;
    display: flex;
    justify-content: flex-end;
}

.tp-table-wrap {
    overflow-x: auto;
}

.tp-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0 10px;
}

.tp-table th {
    text-align: left;
    color: #6b7280;
    font-size: 12px;
    text-transform: uppercase;
    letter-spacing: .05em;
    padding: 0 12px;
}

.tp-table td {
    background: #fff;
    border-top: 1px solid #e5e7eb;
    border-bottom: 1px solid #e5e7eb;
    padding: 14px 12px;
