}

.tp-table td:first-child {
    border-left: 1px solid #e5e7eb;
    border-radius: 14px 0 0 14px;
}

.tp-table td:last-child {
    border-right: 1px solid #e5e7eb;
    border-radius: 0 14px 14px 0;
}

.tp-table a {
    color: #1d4ed8;
    font-weight: 900;
