}

@media (max-width: 1200px) {
    .tp-metrics-4,
    .tp-metrics-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .tp-grid-calendar-pro,
    .tp-modal-grid {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 780px) {
    .tp-hero,
    .tp-kanban-toolbar {
        flex-direction: column;
        align-items: stretch;
    }

    .tp-calendar-grid,
    .tp-calendar-grid-pro {
        grid-template-columns: 1fr;
    }

    .tp-metrics-4,
    .tp-metrics-grid {
        grid-template-columns: 1fr;
    }

    .tp-inline-form,
    .tp-list-row,
    .tp-list-button,
    .tp-list-link {
        grid-template-columns: 1fr;
    }

    .tp-modal-backdrop {
        padding: 10px;
        align-items: stretch;
    }

    .tp-modal {
        max-height: calc(100vh - 20px);
    }
}

/* Ajustes finais do Calendário: visual restaurado, 4 colunas e conteúdo sem estourar */
.tp-calendar-metrics {
    grid-template-columns: repeat(4, minmax(0, 1fr));
}

.tp-grid-calendar-pro {
    grid-template-columns: minmax(0, 1fr) 360px;
    gap: 22px;
}

.tp-calendar-grid,
.tp-calendar-grid-pro {
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 16px;
}

.tp-calendar-day {
    min-height: 220px;
    padding: 15px;
    border-radius: 20px;
    background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
    border: 1px solid #e5e7eb;
    box-shadow: 0 10px 24px rgba(15, 23, 42, .05);
    overflow: hidden;
    display: flex;
    flex-direction: column;
}

.tp-calendar-day.is-muted {
    background: #f9fafb;
    opacity: .68;
}

.tp-calendar-day.is-today {
    border-color: #2563eb;
    box-shadow: 0 0 0 3px rgba(37, 99, 235, .12), 0 12px 28px rgba(37, 99, 235, .10);
}

.tp-calendar-day.has-late {
    border-color: #fecaca;
    background: linear-gradient(180deg, #fff7f7 0%, #ffffff 100%);
}

.tp-calendar-day-head {
    align-items: flex-start;
    padding-bottom: 10px;
    border-bottom: 1px solid #eef2f7;
}

.tp-calendar-day-head strong {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 34px;
    height: 34px;
    border-radius: 12px;
    background: #eef2ff;
    color: #1d4ed8;
    font-size: 16px;
}

.tp-calendar-day.has-late .tp-calendar-day-head strong {
    background: #fee2e2;
    color: #dc2626;
}

.tp-calendar-day.is-today .tp-calendar-day-head strong {
    background: #2563eb;
    color: #fff;
}

.tp-calendar-day-head span {
    padding-top: 7px;
    color: #64748b;
    font-size: 11px;
    letter-spacing: .06em;
    text-transform: uppercase;
}

.tp-calendar-day-items {
    flex: 1;
    min-width: 0;
    padding-top: 2px;
}

.tp-calendar-card,
.tp-calendar-mini-card {
    position: relative;
    width: 100%;
    min-width: 0;
    padding: 11px 12px 11px 14px;
    border-radius: 14px;
    border: 1px solid #bfdbfe;
    background: #eff6ff;
    box-shadow: 0 8px 18px rgba(37, 99, 235, .06);
    transition: .18s ease;
    overflow: hidden;
}

.tp-calendar-card::before,
.tp-calendar-mini-card::before {
    content: '';
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 4px;
    background: #2563eb;
}

.tp-calendar-card:hover,
.tp-calendar-mini-card:hover {
    transform: translateY(-1px);
    border-color: #60a5fa;
    box-shadow: 0 12px 24px rgba(37, 99, 235, .11);
}

.tp-calendar-card.is-late,
.tp-calendar-mini-card.is-late {
    border-color: #fecaca;
    background: #fef2f2;
}

.tp-calendar-card.is-late::before,
.tp-calendar-mini-card.is-late::before {
    background: #dc2626;
}

.tp-calendar-card span,
.tp-calendar-card small,
.tp-calendar-mini-card strong,
.tp-calendar-mini-card span,
.tp-list-main strong,
.tp-list-main span,
.tp-calendar-modal h3,
.tp-calendar-modal p,
.tp-calendar-modal strong,
.tp-calendar-modal small {
    min-width: 0;
    overflow-wrap: anywhere;
    word-break: normal;
}

.tp-calendar-card span,
.tp-calendar-mini-card strong {
    font-size: 13px;
    line-height: 1.25;
}

.tp-calendar-card small,
.tp-calendar-mini-card span {
    line-height: 1.25;
}

.tp-calendar-empty-day {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 54px;
    border-radius: 14px;
    background: #f8fafc;
    border: 1px dashed #d1d5db;
    color: #94a3b8;
    font-weight: 700;
}

.tp-more-items {
    display: inline-flex;
    width: 100%;
    align-items: center;
    justify-content: center;
    padding: 8px 10px;
    border-radius: 12px;
    background: #eef2ff;
    color: #1d4ed8;
}

.tp-calendar-more-popover {
    width: min(320px, 82vw);
    max-height: 360px;
    overflow: auto;
}

.tp-calendar-side .tp-list-row,
.tp-calendar-side .tp-list-button {
