/* Ajuste 20260504: Calendário popover sobre os cards, Kanban mais sensível e modal SLA */
.tp-calendar-grid,
.tp-calendar-grid-pro,
.tp-calendar-day,
.tp-calendar-day-items {
    overflow: visible;
}

.tp-calendar-day {
    position: relative;
}

.tp-calendar-more-wrap {
    position: relative;
    z-index: 5;
}

.tp-calendar-more-wrap[open] {
    z-index: 80;
}

.tp-calendar-more-wrap[open] .tp-more-items {
    background: #dbeafe;
    box-shadow: 0 8px 18px rgba(37, 99, 235, .14);
}

.tp-calendar-more-popover {
    z-index: 100;
    top: calc(100% + 8px);
    left: 0;
    width: min(340px, 86vw);
    max-height: 390px;
    overflow: auto;
    border: 1px solid #dbeafe;
    box-shadow: 0 24px 70px rgba(15, 23, 42, .22);
}

.tp-calendar-more-popover::before {
    content: '';
    position: absolute;
    top: -7px;
    left: 22px;
    width: 14px;
    height: 14px;
    transform: rotate(45deg);
    background: #fff;
    border-left: 1px solid #dbeafe;
    border-top: 1px solid #dbeafe;
}

.tp-kanban-cards {
    min-height: 180px;
    padding-bottom: 28px;
    border-radius: 18px;
    transition: background .15s ease, box-shadow .15s ease;
}

.tp-kanban-is-dragging .tp-kanban-cards {
    outline: 2px dashed rgba(37, 99, 235, .16);
    outline-offset: 5px;
    background: rgba(239, 246, 255, .68);
}

.tp-kanban-is-dragging .tp-kanban-column:hover .tp-kanban-cards {
    background: #eff6ff;
