}

.tp-table-clickable:hover td {
    background: #f8fafc;
    border-color: #bfdbfe;
}

.tp-table-clickable:hover {
    transform: translateY(-1px);
}

.tp-table-link-button {
    border: none;
    padding: 0;
    background: transparent;
    color: #1d4ed8;
    font-weight: 900;
    text-align: left;
    cursor: pointer;
    overflow-wrap: anywhere;
}

.tp-sla-modal {
    width: min(980px, calc(100vw - 28px));
    max-height: calc(100vh - 42px);
    overflow: auto;
}

.tp-sla-modal h3,
.tp-sla-modal p,
.tp-sla-modal strong,
.tp-sla-modal small,
.tp-sla-modal b,
.tp-sla-modal span {
    overflow-wrap: anywhere;
}

.tp-sla-modal .tp-modal-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
}

.tp-sla-modal-columns {
    display: grid;
    grid-template-columns: minmax(0, .9fr) minmax(0, 1.1fr);
    gap: 14px;
    margin-top: 14px;
}

.tp-text-block p {
    margin: 0 0 10px;
    color: #374151;
    line-height: 1.55;
}

.tp-text-block p:last-child {
    margin-bottom: 0;
}

.tp-sla-table td:first-child {
    min-width: 260px;
}

