        left: 50%;
        transform: translateX(-50%) rotate(45deg);
    }
}

/* Lote 4 - Feedback visual das ações operacionais */
.tp-action-loading {
    position: fixed;
    right: 22px;
    bottom: 22px;
    z-index: 70;
    display: none;
    align-items: center;
    gap: 10px;
    padding: 12px 16px;
    border-radius: 999px;
    border: 1px solid rgba(59, 130, 246, .22);
    background: rgba(255, 255, 255, .94);
    color: #0f172a;
    box-shadow: 0 18px 45px rgba(15, 23, 42, .18);
    font-size: 13px;
    font-weight: 900;
    backdrop-filter: blur(12px);
}

.dark .tp-action-loading {
    border-color: rgba(96, 165, 250, .28);
    background: rgba(15, 23, 42, .94);
    color: #e5e7eb;
}

.tp-spinner {
    width: 16px;
    height: 16px;
    border-radius: 999px;
    border: 2px solid rgba(59, 130, 246, .22);
    border-top-color: #2563eb;
    animation: tp-spin .75s linear infinite;
    flex: none;
}

.tp-inline-loading {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    margin-left: 8px;
    font-size: 12px;
    font-weight: 900;
    color: #2563eb;
}

.tp-saving-note {
    display: none;
    align-items: center;
    gap: 8px;
    margin-top: 10px;
    padding: 10px 12px;
    border-radius: 14px;
    border: 1px solid rgba(59, 130, 246, .18);
    background: rgba(239, 246, 255, .9);
    color: #1d4ed8;
    font-size: 13px;
    font-weight: 800;
}

.dark .tp-saving-note {
    border-color: rgba(96, 165, 250, .22);
    background: rgba(30, 58, 138, .18);
    color: #bfdbfe;
