}

.tp-calendar-card[disabled],
.tp-list-button[disabled],
.tp-kanban-card[disabled],
.tp-checkline[disabled] {
    transform: none !important;
}

@keyframes tp-spin {
    to { transform: rotate(360deg); }
}

@media (max-width: 640px) {
    .tp-action-loading {
        right: 14px;
        bottom: 14px;
        left: 14px;
        justify-content: center;
        border-radius: 18px;
    }
}

