    --qa-primary-dark: #1d4ed8;
    --qa-success: #16a34a;
    --qa-warning: #d97706;
    --qa-danger: #dc2626;
    --qa-info-soft: #e0f2fe;
    --qa-success-soft: #dcfce7;
    --qa-warning-soft: #fef3c7;
    --qa-danger-soft: #fee2e2;
    --qa-radius-xl: 24px;
