/* ==========================================================================
   Lote 10 - Planos público legado
   Origem: public/css/style-planos.css
   Consolidado no CSS global para remover carregamentos isolados.
   ========================================================================== */
:root {
    --planos-bg: #f8fafc;
    --planos-card: #ffffff;
    --planos-text: #0f172a;
    --planos-muted: #64748b;
    --planos-border: #e2e8f0;
    --planos-primary: #06376d;
    --planos-primary-soft: #eff6ff;
    --planos-success: #16a34a;
    --planos-warning: #f59e0b;
    --planos-shadow: 0 24px 70px rgba(15, 23, 42, .10);
}

* {
    box-sizing: border-box;
}

body.planos-page {
    margin: 0;
    min-height: 100vh;
    font-family: Arial, Helvetica, sans-serif;
    color: var(--planos-text);
    background:
        radial-gradient(circle at top left, rgba(6, 55, 109, .14), transparent 34%),
        radial-gradient(circle at top right, rgba(22, 163, 74, .10), transparent 28%),
        var(--planos-bg);
}

.planos-wrapper {
    width: min(1220px, calc(100% - 32px));
    margin: 0 auto;
    padding: 44px 0;
}

.planos-hero {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 320px;
    gap: 24px;
    align-items: stretch;
    margin-bottom: 28px;
}

.planos-eyebrow {
    display: inline-flex;
    align-items: center;
    margin-bottom: 12px;
    padding: 7px 12px;
    border-radius: 999px;
    background: var(--planos-primary-soft);
    color: var(--planos-primary);
    font-size: 12px;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: .08em;
}

.planos-hero h1 {
    margin: 0;
    max-width: 760px;
    font-size: clamp(32px, 4vw, 52px);
    line-height: 1.05;
    font-weight: 900;
    letter-spacing: -.04em;
}

.planos-hero p {
    margin: 14px 0 0;
    max-width: 850px;
    color: var(--planos-muted);
    font-size: 17px;
    line-height: 1.7;
}

.planos-hero-card {
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 8px;
    padding: 22px;
    border: 1px solid var(--planos-border);
    border-radius: 24px;
    background: rgba(255, 255, 255, .82);
    box-shadow: 0 14px 35px rgba(15, 23, 42, .07);
}

.planos-hero-card strong {
    font-size: 18px;
}

.planos-hero-card span {
    color: var(--planos-muted);
    line-height: 1.6;
}

.planos-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 20px;
    align-items: stretch;
}

.plano-card {
    position: relative;
    display: flex;
    flex-direction: column;
    min-height: 100%;
    padding: 26px;
    background: var(--planos-card);
    border: 1px solid var(--planos-border);
    border-radius: 24px;
    box-shadow: 0 14px 40px rgba(15, 23, 42, .06);
    transition: transform .18s ease, box-shadow .18s ease, border-color .18s ease;
}

.plano-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--planos-shadow);
    border-color: rgba(6, 55, 109, .28);
}

.plano-card-destaque {
    border: 2px solid var(--planos-primary);
    box-shadow: 0 22px 65px rgba(6, 55, 109, .16);
}

.plano-tag {
    position: absolute;
    top: -13px;
    left: 24px;
    display: inline-flex;
    align-items: center;
    padding: 6px 12px;
    border-radius: 999px;
    background: var(--planos-primary);
    color: #ffffff;
    font-size: 12px;
    font-weight: 900;
}

.plano-card-topo h2 {
    margin: 0;
    font-size: 22px;
    font-weight: 900;
    letter-spacing: -.02em;
}

.plano-card-topo p {
    margin: 10px 0 0;
    min-height: 72px;
    color: var(--planos-muted);
    font-size: 14px;
    line-height: 1.6;
}

.plano-price {
    margin: 20px 0 16px;
    font-size: 32px;
    font-weight: 950;
    letter-spacing: -.04em;
}

.plano-limites {
    display: grid;
    gap: 8px;
    margin-bottom: 18px;
}

.plano-limites span {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 34px;
    padding: 7px 10px;
    border-radius: 12px;
    background: #f8fafc;
    border: 1px solid var(--planos-border);
    color: #334155;
    font-size: 13px;
    font-weight: 800;
}

.plano-lista {
    display: grid;
    gap: 10px;
    margin: 0;
    padding: 0;
    list-style: none;
}

.plano-lista li {
    position: relative;
    padding-left: 24px;
    color: #334155;
    font-size: 14px;
    line-height: 1.5;
}

.plano-lista li::before {
    content: '✓';
    position: absolute;
    left: 0;
    top: 0;
    color: var(--planos-success);
    font-weight: 900;
}

.plano-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    min-height: 46px;
    margin-top: auto;
    padding: 12px 18px;
    border-radius: 14px;
    color: #ffffff;
    font-size: 14px;
    font-weight: 900;
    text-decoration: none;
    transition: transform .18s ease, opacity .18s ease;
}

.plano-btn:hover {
    transform: translateY(-1px);
    opacity: .94;
}

.plano-btn-blue {
    background: var(--planos-primary);
}

.plano-btn-green {
    background: var(--planos-success);
}

.planos-observacao {
    margin-top: 24px;
    padding: 18px 20px;
    background: rgba(255, 255, 255, .82);
    border: 1px solid var(--planos-border);
    border-radius: 18px;
    color: #334155;
    font-size: 14px;
    line-height: 1.6;
}

@media (max-width: 1100px) {
    .planos-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 820px) {
    .planos-wrapper {
        width: min(100% - 24px, 1220px);
        padding: 28px 0;
    }

    .planos-hero {
        grid-template-columns: 1fr;
    }

    .planos-grid {
        grid-template-columns: 1fr;
    }

    .plano-card-topo p {
        min-height: auto;
    }
}


