    padding: .8rem;
    text-transform: uppercase;
    letter-spacing: .05em;
}
.rel-table td { border-top: 1px solid #e2e8f0; padding: .85rem .8rem; vertical-align: top; color: #334155; }
.rel-table td strong { color: #0f172a; }
.rel-table small { display: block; color: #64748b; margin-top: .18rem; }
.rel-badge, .rel-priority {
    display: inline-flex;
    border-radius: 999px;
    padding: .32rem .58rem;
    font-size: .74rem;
    font-weight: 900;
    background: #eef2ff;
    color: #3730a3;
}
.rel-priority--alta, .rel-priority--critica, .rel-priority--urgente { background: #fef2f2; color: #b91c1c; }
.rel-priority--media { background: #fffbeb; color: #b45309; }
.rel-priority--baixa { background: #ecfdf5; color: #047857; }

.rel-list, .rel-checklist { display: flex; flex-direction: column; gap: .7rem; }
.rel-list-row, .rel-check, .rel-validation {
    border: 1px solid #e2e8f0;
    border-radius: 16px;
    background: #f8fafc;
    padding: .85rem;
}
.rel-list-row { display: flex; justify-content: space-between; gap: .8rem; }
.rel-list-row strong, .rel-list-row span { display: block; }
.rel-list-row span, .rel-check p, .rel-check small, .rel-validation p { color: #64748b; font-size: .84rem; margin: .2rem 0 0; }
.rel-list-row em { font-style: normal; font-weight: 900; color: #1d4ed8; }
.rel-check { display: grid; grid-template-columns: 28px 1fr; gap: .7rem; }
.rel-check > span { width: 28px; height: 28px; border-radius: 999px; display: grid; place-items: center; font-weight: 900; }
.rel-check.ok > span { background: #dcfce7; color: #15803d; }
.rel-check.warn > span { background: #fef3c7; color: #b45309; }
.rel-check strong, .rel-validation strong { color: #0f172a; }

.rel-validation-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: .85rem; }
.rel-validation.ok { border-color: rgba(34,197,94,.22); background: #f0fdf4; }
.rel-validation.warn { border-color: rgba(245,158,11,.28); background: #fffbeb; }
.rel-empty { text-align: center; padding: 1.3rem; color: #64748b; }
.rel-empty strong { display: block; color: #0f172a; font-size: 1rem; }
.rel-empty.small { text-align: left; padding: .9rem; }

@media (max-width: 1100px) {
    .rel-summary-grid, .rel-summary-grid.compact { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .rel-grid.two { grid-template-columns: 1fr; }
}
@media (max-width: 720px) {
    .rel-hero { align-items: stretch; flex-direction: column; border-radius: 18px; }
    .rel-actions { justify-content: stretch; }
    .rel-actions button { flex: 1 1 90px; }
    .rel-summary-grid, .rel-summary-grid.compact, .rel-validation-grid { grid-template-columns: 1fr; }
    .rel-card-header { flex-direction: column; }
}

/* Lote 5 — reforço de UX: relatórios são leitura, análise e exportação. */
.rel-kicker i,
.rel-actions button i { margin-right: .35rem; }
.rel-purpose-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: .85rem;
}
.rel-purpose-card {
    display: grid;
    grid-template-columns: 42px 1fr;
    gap: .8rem;
    align-items: start;
    border: 1px solid rgba(148, 163, 184, .24);
    background: rgba(255,255,255,.96);
    border-radius: 20px;
    padding: 1rem;
    box-shadow: 0 12px 28px rgba(15, 23, 42, .05);
}
.rel-purpose-card i {
    width: 42px;
    height: 42px;
    display: grid;
    place-items: center;
    border-radius: 14px;
    background: #eff6ff;
    color: #1d4ed8;
    font-size: 1.1rem;
}
.rel-purpose-card strong { display:block; color:#0f172a; font-weight: 950; }
.rel-purpose-card span { display:block; color:#64748b; font-size:.88rem; margin-top:.18rem; }
@media (max-width: 860px) { .rel-purpose-grid { grid-template-columns: 1fr; } }
.dark .rel-purpose-card,
.dark .rel-hero,
.dark .rel-card,
.dark .rel-stat,
.dark .rel-tabs { background: rgba(15, 23, 42, .92); border-color: rgba(148, 163, 184, .22); }
.dark .rel-purpose-card strong,
.dark .rel-card-header h2,
.dark .rel-stat strong,
.dark .rel-table td strong,
.dark .rel-empty strong { color: #f8fafc; }
.dark .rel-purpose-card span,
.dark .rel-card-header p,
.dark .rel-table td,
.dark .rel-table small,
.dark .rel-list-row span,
.dark .rel-check p,
.dark .rel-check small,
.dark .rel-validation p { color: #cbd5e1; }
.dark .rel-tabs button,
.dark .rel-table th,
.dark .rel-list-row,
.dark .rel-check,
.dark .rel-validation,
.dark .rel-table-wrap { background: rgba(30, 41, 59, .82); border-color: rgba(148, 163, 184, .2); }

/* LOTE 11 - Auditoria detalhada - auditoria-detalhada.css */
:root {
    --prazzu-primary: #FD8605;
    --prazzu-primary-dark: #d96f00;
    --prazzu-primary-soft: #fff4e8;
    --prazzu-primary-border: #ffd7ad;
    --prazzu-secondary: #06376d;
    --prazzu-secondary-soft: #eaf2fb;
    --prazzu-text: #111827;
    --prazzu-muted: #6b7280;
    --prazzu-border: #e5e7eb;
    --prazzu-surface: #ffffff;
    --prazzu-surface-soft: #f8fafc;
}

.ad-page {
    display: flex;
    flex-direction: column;
    gap: 1.2rem;
}

.ad-hero {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 1rem;
    border: 1px solid rgba(148, 163, 184, 0.26);
    border-radius: 1rem;
    padding: 1.35rem;
    background: linear-gradient(135deg, rgba(6, 55, 109, 0.10), rgba(253, 134, 5, 0.09));
}

.ad-eyebrow {
    font-size: 0.72rem;
    font-weight: 850;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--prazzu-secondary);
}

.ad-title {
    margin: 0.25rem 0 0;
    font-size: 1.45rem;
    line-height: 1.2;
    font-weight: 950;
    color: var(--prazzu-text);
}

.ad-subtitle {
    margin: 0.5rem 0 0;
    max-width: 930px;
    font-size: 0.92rem;
    line-height: 1.55;
    color: var(--prazzu-muted);
}

.ad-hero-actions,
.ad-filter-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.55rem;
    flex-shrink: 0;
}

.ad-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 2.35rem;
    border-radius: 0.75rem;
    padding: 0.55rem 0.9rem;
    font-size: 0.82rem;
    font-weight: 850;
    text-decoration: none;
    border: 1px solid transparent;
    cursor: pointer;
    transition: transform 0.16s ease, box-shadow 0.16s ease, background 0.16s ease;
}

.ad-button:hover {
    transform: translateY(-1px);
}

.ad-button--primary {
    color: #ffffff;
    background: linear-gradient(135deg, var(--prazzu-secondary), var(--prazzu-primary));
    box-shadow: 0 10px 22px rgba(6, 55, 109, 0.16);
}

.ad-button--ghost {
    color: var(--prazzu-secondary);
    border-color: var(--prazzu-primary-border);
    background: #ffffff;
}

.ad-filters {
    display: grid;
    grid-template-columns: repeat(6, minmax(0, 1fr));
    gap: 0.8rem;
    align-items: end;
    border: 1px solid rgba(148, 163, 184, 0.26);
    border-radius: 1rem;
    padding: 1rem;
    background: #ffffff;
    box-shadow: 0 8px 24px rgba(15, 23, 42, 0.04);
}

.ad-filter-field {
    min-width: 0;
}

.ad-filter-field label,
.ad-check-filter span {
    display: block;
    margin-bottom: 0.35rem;
    font-size: 0.73rem;
    font-weight: 850;
    color: #475569;
}

.ad-filter-field select {
    width: 100%;
    min-height: 2.45rem;
    border: 1px solid #dbe3ef;
    border-radius: 0.75rem;
    padding: 0.45rem 0.65rem;
    font-size: 0.84rem;
    color: #111827;
    background: #ffffff;
}

.ad-check-filter {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    min-height: 2.45rem;
    border: 1px solid #dbe3ef;
    border-radius: 0.75rem;
    padding: 0.45rem 0.65rem;
    background: #f8fafc;
}

.ad-check-filter input {
    width: 1rem;
    height: 1rem;
}

.ad-check-filter span {
    margin: 0;
}

.ad-metrics {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 1rem;
}

.ad-metrics--five {
    grid-template-columns: repeat(5, minmax(0, 1fr));
}

.ad-metric-card,
.ad-panel {
    border: 1px solid rgba(148, 163, 184, 0.25);
    border-radius: 1rem;
    background: #ffffff;
    box-shadow: 0 8px 24px rgba(15, 23, 42, 0.04);
}

.ad-metric-card {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
    min-height: 118px;
    padding: 1rem;
}

.ad-metric-card span {
    font-size: 0.76rem;
    font-weight: 850;
    color: var(--prazzu-muted);
}

.ad-metric-card strong {
    font-size: 1.85rem;
    line-height: 1;
    font-weight: 950;
    letter-spacing: -0.04em;
    color: var(--prazzu-text);
}

.ad-metric-card small {
    margin-top: auto;
    font-size: 0.74rem;
    color: var(--prazzu-muted);
}

.ad-metric-card--info {
    border-color: #b8d2ee;
    background: #eaf2fb;
}

.ad-metric-card--warning {
    border-color: #fde68a;
    background: #fffbeb;
}

.ad-metric-card--danger,
.ad-metric-card--critical {
    border-color: #fecaca;
    background: #fef2f2;
}

.ad-layout {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(280px, 0.65fr);
    gap: 1rem;
    align-items: start;
}

.ad-layout--balanced {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}

.ad-panel {
    min-width: 0;
    padding: 1.05rem;
}

.ad-panel-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 1rem;
    margin-bottom: 1rem;
}

.ad-panel-header h3 {
    margin: 0;
    font-size: 1.02rem;
    font-weight: 900;
    color: var(--prazzu-text);
}

.ad-panel-header p {
    margin: 0.25rem 0 0;
    font-size: 0.82rem;
    color: var(--prazzu-muted);
}

.ad-panel-counter {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    border-radius: 999px;
    padding: 0.35rem 0.75rem;
    font-size: 0.74rem;
    font-weight: 850;
    color: var(--prazzu-secondary);
    background: var(--prazzu-primary-soft);
    border: 1px solid var(--prazzu-primary-border);
}

.ad-empty {
    border-radius: 0.85rem;
    padding: 1rem;
    font-size: 0.9rem;
    color: #64748b;
    background: #f8fafc;
    border: 1px dashed #cbd5e1;
}

.ad-chart {
    display: flex;
    flex-direction: column;
    gap: 0.85rem;
}

.ad-chart-row {
    display: grid;
    grid-template-columns: 9rem minmax(0, 1fr) 5rem;
    gap: 0.8rem;
    align-items: center;
}

.ad-chart-track {
    height: 0.75rem;
    overflow: hidden;
    border-radius: 999px;
    background: #e5e7eb;
}

.ad-chart-bar {
    height: 100%;
    border-radius: inherit;
    background: linear-gradient(90deg, var(--prazzu-secondary), var(--prazzu-primary));
}

.ad-chart-row strong {
    text-align: right;
    font-size: 0.88rem;
    color: var(--prazzu-text);
}

.ad-badge {
    display: inline-flex;
    align-items: center;
    max-width: 100%;
    border-radius: 999px;
    padding: 0.25rem 0.65rem;
    font-size: 0.72rem;
    line-height: 1;
    font-weight: 850;
    white-space: nowrap;
}

.ad-badge--success {
    color: #166534;
    background: #dcfce7;
}

.ad-badge--warning {
    color: #92400e;
    background: #fef3c7;
}

.ad-badge--danger {
    color: #991b1b;
    background: #fee2e2;
}

.ad-badge--gray {
    color: #334155;
    background: #f1f5f9;
}

.ad-ranking {
    display: flex;
    flex-direction: column;
    gap: 0.65rem;
}

.ad-ranking-row {
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 0.25rem 1rem;
    align-items: center;
    border-radius: 0.75rem;
    padding: 0.75rem;
    background: #f8fafc;
}

.ad-ranking-row--stacked {
    grid-template-columns: minmax(0, 1fr) auto;
}

.ad-ranking-row span {
    min-width: 0;
    overflow: hidden;
    font-size: 0.86rem;
    font-weight: 800;
    color: #334155;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.ad-ranking-row small {
    grid-column: 1;
    font-size: 0.72rem;
    color: #64748b;
}

.ad-ranking-row strong {
    grid-row: span 2;
    flex-shrink: 0;
    font-size: 0.9rem;
    color: var(--prazzu-text);
}

.ad-sensitive-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0.85rem;
}

.ad-sensitive-card {
    min-width: 0;
    border: 1px solid #fecaca;
    border-radius: 0.9rem;
    padding: 0.85rem;
    background: #fff7f7;
}

.ad-sensitive-top {
    display: flex;
    justify-content: space-between;
    gap: 0.5rem;
    align-items: center;
}

.ad-sensitive-top time,
.ad-timeline-top time {
    flex-shrink: 0;
    font-size: 0.74rem;
    color: #64748b;
}

.ad-sensitive-card h4 {
    margin: 0.75rem 0 0;
    font-size: 0.94rem;
    font-weight: 900;
    color: #111827;
}

.ad-sensitive-card p {
    margin: 0.35rem 0 0;
    font-size: 0.8rem;
    line-height: 1.45;
    color: #64748b;
}

.ad-timeline {
    display: flex;
    flex-direction: column;
    gap: 0.9rem;
}

.ad-timeline-item {
    display: grid;
    grid-template-columns: 1.4rem minmax(0, 1fr);
    gap: 0.75rem;
    position: relative;
}

.ad-timeline-item:not(:last-child)::after {
    content: '';
    position: absolute;
    left: 0.65rem;
    top: 1.6rem;
    width: 2px;
    height: calc(100% - 0.6rem);
    background: rgba(6, 55, 109, 0.15);
}

.ad-timeline-marker {
    width: 1.3rem;
    height: 1.3rem;
    border: 4px solid #eaf2fb;
    border-radius: 999px;
    background: var(--prazzu-secondary);
    z-index: 1;
}

.ad-timeline-content {
    min-width: 0;
    border-radius: 0.95rem;
    padding: 0.95rem;
    border: 1px solid rgba(148, 163, 184, 0.22);
    background: rgba(248, 250, 252, 0.78);
}

.ad-timeline-top {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 0.65rem;
}

.ad-timeline-badges {
    display: flex;
    flex-wrap: wrap;
    gap: 0.45rem;
    min-width: 0;
}

.ad-timeline-content h4 {
    margin: 0.7rem 0 0;
    font-size: 0.98rem;
    font-weight: 900;
    color: var(--prazzu-text);
}

.ad-timeline-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 0.45rem;
    margin-top: 0.65rem;
}

.ad-timeline-meta span {
    max-width: 100%;
    overflow: hidden;
    border-radius: 999px;
    padding: 0.25rem 0.55rem;
    font-size: 0.72rem;
    font-weight: 750;
    color: #475569;
    background: #ffffff;
    border: 1px solid #e2e8f0;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.ad-diff {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.65rem;
    margin-top: 0.75rem;
}

.ad-diff div {
    min-width: 0;
    border-radius: 0.75rem;
    padding: 0.65rem;
    background: #ffffff;
    border: 1px solid #e5e7eb;
}

.ad-diff span {
    display: block;
    margin-bottom: 0.25rem;
    font-size: 0.68rem;
    font-weight: 850;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: #64748b;
}

.ad-diff strong {
    display: block;
    overflow-wrap: anywhere;
    font-size: 0.82rem;
    line-height: 1.4;
    font-weight: 750;
    color: var(--prazzu-text);
}

.ad-panel--large .ad-timeline {
    max-height: 38rem;
    overflow-y: auto;
    overflow-x: hidden;
    padding-right: 0.35rem;
    scrollbar-width: thin;
    scrollbar-color: var(--prazzu-primary) #eaf2fb;
}

.ad-panel--large .ad-timeline::-webkit-scrollbar {
    width: 0.45rem;
}

.ad-panel--large .ad-timeline::-webkit-scrollbar-track {
    border-radius: 999px;
    background: #eaf2fb;
}

.ad-panel--large .ad-timeline::-webkit-scrollbar-thumb {
    border-radius: 999px;
    background: var(--prazzu-primary);
}

@media (max-width: 1280px) {
    .ad-metrics--five,
    .ad-sensitive-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .ad-filters {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}

@media (max-width: 1024px) {
    .ad-hero,
    .ad-panel-header {
        flex-direction: column;
    }

    .ad-layout,
    .ad-layout--balanced,
    .ad-metrics,
    .ad-metrics--five {
        grid-template-columns: 1fr;
    }

    .ad-chart-row {
        grid-template-columns: 1fr;
    }

    .ad-chart-row strong {
        text-align: left;
    }
}

@media (max-width: 720px) {
    .ad-filters,
    .ad-sensitive-grid {
        grid-template-columns: 1fr;
    }

    .ad-hero,
    .ad-panel,
    .ad-metric-card,
    .ad-filters {
        border-radius: 0.85rem;
        padding: 0.9rem;
    }

    .ad-diff {
        grid-template-columns: 1fr;
    }
}

/* UX polish - auditoria completa */
.ad-hero--clean {
    background: linear-gradient(135deg, rgba(6, 55, 109, 0.08), rgba(253, 134, 5, 0.07));
}

.ad-help-grid {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
    margin-top: 0.85rem;
}

.ad-help-grid span {
    display: inline-flex;
    align-items: center;
    gap: 0.38rem;
    border: 1px solid rgba(6, 55, 109, 0.13);
    border-radius: 999px;
    padding: 0.35rem 0.65rem;
    font-size: 0.76rem;
    font-weight: 800;
    color: #334155;
    background: rgba(255, 255, 255, 0.74);
}

.ad-help-grid strong {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.15rem;
    height: 1.15rem;
    border-radius: 999px;
    font-size: 0.68rem;
    color: #ffffff;
    background: var(--prazzu-secondary);
}

.ad-filters--ux {
    grid-template-columns: repeat(6, minmax(0, 1fr));
}

.ad-filter-field--wide {
    grid-column: span 2;
}

.ad-filter-field input[type="search"],
.ad-filter-field input[type="text"] {
    width: 100%;
    min-height: 2.45rem;
    border: 1px solid #dbe3ef;
    border-radius: 0.75rem;
    padding: 0.45rem 0.75rem;
    font-size: 0.84rem;
    color: #111827;
    background: #ffffff;
}

.ad-filter-field input:focus,
.ad-filter-field select:focus {
    outline: none;
    border-color: var(--prazzu-primary);
    box-shadow: 0 0 0 3px rgba(253, 134, 5, 0.14);
}

.ad-active-filters {
    grid-column: 1 / -1;
    display: flex;
    flex-wrap: wrap;
    gap: 0.45rem;
    align-items: center;
    border-top: 1px solid #eef2f7;
    padding-top: 0.8rem;
    font-size: 0.78rem;
    color: #64748b;
}

.ad-active-filters strong {
    color: #334155;
}

.ad-active-filters span {
    border-radius: 999px;
    padding: 0.28rem 0.6rem;
    font-weight: 800;
    color: var(--prazzu-secondary);
    background: var(--prazzu-secondary-soft);
}

.ad-focus-panel {
    border-color: rgba(253, 134, 5, 0.28);
}

.ad-timeline-item--ux {
    grid-template-columns: 2.4rem minmax(0, 1fr);
}

.ad-timeline-item--ux:not(:last-child)::after {
    left: 1.17rem;
}

.ad-avatar {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2.35rem;
    height: 2.35rem;
    border-radius: 999px;
    border: 3px solid #eaf2fb;
    font-size: 0.78rem;
    font-weight: 950;
    color: #ffffff;
    background: linear-gradient(135deg, var(--prazzu-secondary), var(--prazzu-primary));
    z-index: 1;
}

.ad-diff--ux div:first-child {
    border-color: #dbe3ef;
    background: #f8fafc;
}

.ad-diff--ux div:last-child {
    border-color: var(--prazzu-primary-border);
    background: var(--prazzu-primary-soft);
}

@media (max-width: 1280px) {
    .ad-filters--ux {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .ad-filter-field--wide {
        grid-column: 1 / -1;
    }
}

@media (max-width: 720px) {
    .ad-help-grid,
    .ad-active-filters {
        align-items: stretch;
        flex-direction: column;
    }

    .ad-timeline-item--ux {
        grid-template-columns: 1fr;
    }

    .ad-timeline-item--ux::after {
        display: none;
    }
}

/* LOTE 11 - Relatórios personalizados - relatorios-personalizados.css */
:root {
    --prazzu-primary: #FD8605;
    --prazzu-primary-dark: #d96f00;
    --prazzu-primary-soft: #fff4e8;
    --prazzu-primary-border: #ffd7ad;
    --prazzu-secondary: #06376d;
    --prazzu-secondary-dark: #042a52;
    --prazzu-secondary-soft: #eaf2fb;
    --prazzu-secondary-border: #b8d2ee;
    --prazzu-text: #111827;
    --prazzu-muted: #6b7280;
    --prazzu-border: #e5e7eb;
    --prazzu-surface: #ffffff;
    --prazzu-surface-soft: #f8fafc;
}

.rp-page {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.rp-hero {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    border: 1px solid rgba(148, 163, 184, 0.25);
    border-radius: 1rem;
    padding: 1.5rem;
    background: linear-gradient(135deg, rgba(37, 99, 235, 0.14), rgba(16, 185, 129, 0.08));
}

.rp-eyebrow {
    font-size: 0.75rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #06376d;
}

.rp-title {
    margin: 0.25rem 0 0;
    font-size: 1.45rem;
    font-weight: 850;
    line-height: 1.2;
    color: #111827;
}

.rp-subtitle {
    margin: 0.45rem 0 0;
    max-width: 780px;
    font-size: 0.92rem;
    color: #6b7280;
}

.rp-groups {
    display: flex;
    flex-direction: column;
    gap: 1.75rem;
}

.rp-group {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.rp-group-header h3 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 800;
    color: #111827;
}

.rp-group-header p {
    margin: 0.2rem 0 0;
    font-size: 0.85rem;
    color: #6b7280;
}

.rp-grid {
    display: grid;
    grid-template-columns: repeat(12, minmax(0, 1fr));
    gap: 1rem;
}

.rp-report {
    grid-column: span 12 / span 12;
    display: flex;
    min-height: 360px;
    flex-direction: column;
    gap: 1rem;
    border-radius: 1rem;
    padding: 1.15rem;
    border: 1px solid rgba(148, 163, 184, 0.25);
    background: #ffffff;
    box-shadow: 0 8px 24px rgba(15, 23, 42, 0.04);
    overflow: hidden;
}

.rp-report--default {
    background: #ffffff;
    border-color: rgba(148, 163, 184, 0.25);
}

.rp-report--warning {
    background: #fffbeb;
    border-color: #fde68a;
}

.rp-report--danger {
    background: #fef2f2;
    border-color: #fecaca;
}

.rp-report-top {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 1rem;
}

.rp-report-source {
    display: block;
    font-size: 0.78rem;
    font-weight: 750;
    color: #6b7280;
}

.rp-report h4 {
    margin: 0.3rem 0 0;
    font-size: 1.08rem;
    font-weight: 850;
    color: #111827;
}

.rp-report p {
    margin: 0.35rem 0 0;
    font-size: 0.84rem;
    color: #6b7280;
}

.rp-report-type {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    white-space: nowrap;
    border-radius: 999px;
    padding: 0.28rem 0.7rem;
    font-size: 0.72rem;
    font-weight: 800;
    color: #374151;
    background: rgba(255, 255, 255, 0.82);
    border: 1px solid rgba(148, 163, 184, 0.3);
}

.rp-metrics {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0.75rem;
}

.rp-metric {
    border-radius: 0.9rem;
    padding: 0.85rem;
    background: rgba(255, 255, 255, 0.76);
    border: 1px solid rgba(148, 163, 184, 0.22);
}

.rp-metric span {
    display: block;
    font-size: 0.72rem;
    font-weight: 800;
    color: #6b7280;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.rp-metric strong {
    display: block;
    margin-top: 0.25rem;
    font-size: 1.45rem;
    line-height: 1;
    font-weight: 900;
    color: #111827;
}

.rp-content-grid {
    display: grid;
    grid-template-columns: minmax(220px, 0.75fr) minmax(0, 1.25fr);
    gap: 1rem;
}

.rp-panel {
    min-width: 0;
    border-radius: 0.95rem;
    padding: 0.9rem;
    background: rgba(255, 255, 255, 0.66);
    border: 1px solid rgba(148, 163, 184, 0.22);
}

.rp-panel-title {
    margin-bottom: 0.75rem;
    font-size: 0.78rem;
    font-weight: 850;
    color: #374151;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.rp-chart {
    display: flex;
    flex-direction: column;
    gap: 0.72rem;
    width: 100%;
}

.rp-chart-row {
    display: grid;
    grid-template-columns: minmax(86px, 0.9fr) minmax(100px, 2fr) auto;
    align-items: center;
    gap: 0.65rem;
}

.rp-chart-label {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-size: 0.78rem;
    font-weight: 750;
    color: #374151;
}

.rp-chart-track {
    height: 0.72rem;
    overflow: hidden;
    border-radius: 999px;
    background: rgba(148, 163, 184, 0.22);
}

.rp-chart-bar {
    height: 100%;
    border-radius: inherit;
    background: linear-gradient(90deg, #06376d, #FD8605);
}

.rp-chart-value {
    min-width: 2rem;
    text-align: right;
    font-size: 0.78rem;
    font-weight: 850;
    color: #111827;
}

.rp-table-wrap {
    width: 100%;
    overflow-x: auto;
    border-radius: 0.85rem;
    border: 1px solid rgba(148, 163, 184, 0.25);
    background: rgba(255, 255, 255, 0.72);
}

.rp-table {
    width: 100%;
    min-width: 680px;
    border-collapse: collapse;
    font-size: 0.82rem;
}

.rp-table th,
.rp-table td {
    padding: 0.72rem 0.85rem;
    text-align: left;
    border-bottom: 1px solid rgba(148, 163, 184, 0.22);
    color: #374151;
}

.rp-table th {
    font-size: 0.72rem;
    font-weight: 850;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #6b7280;
    background: rgba(248, 250, 252, 0.86);
}

.rp-table tr:last-child td {
    border-bottom: 0;
}

.rp-table td {
    max-width: 240px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.rp-table td:first-child {
    font-weight: 750;
    color: #111827;
}

.rp-empty-content {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 120px;
    border-radius: 0.85rem;
    border: 1px dashed rgba(148, 163, 184, 0.45);
    color: #6b7280;
    font-size: 0.85rem;
    font-weight: 700;
    text-align: center;
}

.rp-report-footer {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    flex-wrap: wrap;
    gap: 0.75rem;
    padding-top: 0.65rem;
    border-top: 1px solid rgba(148, 163, 184, 0.25);
    font-size: 0.75rem;
    color: #6b7280;
}

.rp-report-footer span {
    display: inline-flex;
    align-items: center;
    border-radius: 999px;
    padding: 0.18rem 0.55rem;
    background: rgba(255, 255, 255, 0.68);
    border: 1px solid rgba(148, 163, 184, 0.24);
}

.rp-empty-card {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 0.65rem;
    min-height: 260px;
    border: 1px dashed #cbd5e1;
    border-radius: 1rem;
    padding: 2rem;
    text-align: center;
    background: #ffffff;
}

.rp-empty-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 3rem;
    height: 3rem;
    border-radius: 999px;
    background: #eaf2fb;
    color: #06376d;
    font-size: 1.5rem;
    font-weight: 900;
}

.rp-empty-card h3 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 850;
    color: #111827;
}

.rp-empty-card p {
    margin: 0;
    color: #6b7280;
}

.rp-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    margin-top: 0.5rem;
    border-radius: 0.75rem;
    padding: 0.65rem 1rem;
    background: #06376d;
    color: #ffffff !important;
    font-size: 0.85rem;
    font-weight: 800;
    text-decoration: none;
    box-shadow: 0 8px 20px rgba(37, 99, 235, 0.22);
}

.rp-button:hover {
    background: #06376d;
}

@media (max-width: 1100px) {
    .rp-content-grid {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 760px) {
    .rp-metrics {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .rp-chart-row {
        grid-template-columns: 1fr;
        gap: 0.35rem;
    }

    .rp-chart-value {
        text-align: left;
    }
}

@media (max-width: 520px) {
    .rp-metrics {
        grid-template-columns: 1fr;
    }
}

@media (prefers-color-scheme: dark) {
    .rp-hero,
    .rp-report,
    .rp-empty-card {
        background-color: #111827;
    }

    .rp-title,
    .rp-group-header h3,
    .rp-report h4,
    .rp-metric strong,
    .rp-chart-value,
    .rp-table td:first-child,
    .rp-empty-card h3 {
        color: #f9fafb;
    }

    .rp-subtitle,
    .rp-group-header p,
    .rp-report-source,
    .rp-report p,
    .rp-metric span,
    .rp-report-footer,
    .rp-chart-label,
    .rp-table td,
    .rp-empty-card p,
    .rp-empty-content {
        color: #9ca3af;
    }

    .rp-report--default {
        background: #111827;
        border-color: #374151;
    }

    .rp-report--warning {
        background: rgba(120, 53, 15, 0.28);
        border-color: rgba(251, 191, 36, 0.35);
    }

    .rp-report--danger {
        background: rgba(127, 29, 29, 0.28);
        border-color: rgba(248, 113, 113, 0.35);
    }

    .rp-report-type,
    .rp-metric,
    .rp-panel,
    .rp-report-footer span {
        color: #e5e7eb;
        background: rgba(17, 24, 39, 0.72);
        border-color: rgba(75, 85, 99, 0.7);
    }

    .rp-panel-title {
        color: #d1d5db;
    }

    .rp-chart-track {
        background: rgba(75, 85, 99, 0.7);
    }

    .rp-table-wrap {
        background: rgba(17, 24, 39, 0.62);
        border-color: rgba(75, 85, 99, 0.7);
    }

    .rp-table th {
        color: #d1d5db;
        background: rgba(31, 41, 55, 0.78);
    }

    .rp-table th,
    .rp-table td {
        border-bottom-color: rgba(75, 85, 99, 0.7);
    }
}

