.crm-title-block p{font-size:13px;margin-top:8px;}
.crm-search-box{height:45px;border-radius:12px;background:#fff;box-shadow:0 8px 24px rgba(15,23,42,.06);}
.crm-search-box kbd{height:25px;min-width:38px;border-radius:7px;font-size:11px;}
.crm-top-actions{gap:10px;}
.crm-btn{text-decoration:none!important;height:44px;border-radius:10px;padding:0 15px;font-size:13px;}
