.crm-attention-strip{border-radius:18px;padding:16px 18px 18px;background:#fff;margin-bottom:20px;}
.crm-attention-strip header{margin-bottom:14px;}
.crm-attention-strip header>div{gap:9px;}
.crm-attention-strip strong{font-size:12px;}
.crm-attention-list{gap:10px;}
.crm-attention-card{min-height:72px;border-radius:14px;padding:13px 14px;grid-template-columns:36px 1fr;background:#fff;}
.crm-attention-card.tone-danger{border-color:rgba(239,68,68,.45);background:linear-gradient(90deg,rgba(239,68,68,.07),rgba(255,255,255,.92));}
.crm-attention-card.tone-warning{background:linear-gradient(90deg,rgba(245,158,11,.08),rgba(255,255,255,.92));}
