.crm-tabs button.active{background:#f3e8ff;color:#6d28d9;box-shadow:inset 0 -2px 0 #8b5cf6,0 8px 18px rgba(124,58,237,.10);}
.crm-tabs b{height:23px;min-width:24px;background:#e9d5ff;color:#6d28d9;}
.crm-toolbar-actions{gap:10px;}
.crm-view-toggle{width:38px;height:38px;border:1px solid var(--crm-line);border-radius:11px;background:#fff;color:#334155;display:grid;place-items:center;box-shadow:0 8px 18px rgba(15,23,42,.05);}
