.status-pill{min-height:24px;padding:4px 10px;border-radius:8px;font-size:11px;}
.status-pill.tone-danger{background:#fee2e2;color:#b91c1c;}.status-pill.tone-warning{background:#fef3c7;color:#b45309;}.status-pill.tone-success{background:#dcfce7;color:#15803d;}
.mini-bar{height:5px;max-width:86px;}
.crm-pagination{height:64px;border-radius:0 0 18px 18px;background:#fff;}
.crm-right-panel{gap:12px;top:14px;}
.side-card{padding:15px;border-radius:15px;}
.profile-head{grid-template-columns:52px minmax(0,1fr) 30px;gap:12px;position:relative;}
.profile-head>span{width:52px;height:52px;font-size:18px;}
