.health-content p{font-size:12px;margin:7px 0 10px;}
.health-content button{height:36px;border-radius:9px;}
.step-item{grid-template-columns:28px minmax(0,1fr) auto;padding:8px 6px;border:0;border-bottom:1px solid var(--crm-line-soft);border-radius:0;background:transparent;}
