.step-item strong{font-size:12px;}
.step-item small{display:none;}
.step-item em{font-size:11px;}
.add-next-step{height:36px;border:1px solid var(--crm-line);border-radius:10px;background:#fbfdff;color:#7c3aed;font-size:12px;font-weight:850;display:flex;align-items:center;justify-content:center;gap:7px;margin-top:4px;}
.pendency-line{grid-template-columns:26px minmax(0,1fr) auto;padding:8px;border-radius:10px;background:#fbfdff;}
.pendency-line strong{font-size:12px;}
.pendency-line em{font-size:11px;color:#f59e0b;}
.big-progress{height:8px;margin-top:2px;}
.onboarding-steps{gap:8px;margin-top:12px;}
.onboarding-steps div{font-size:12px;}
.quick-grid{grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;}
