@media (max-width:1420px){.quick-grid{grid-template-columns:repeat(2,minmax(0,1fr));}.crm-tabs{gap:8px;}}
@media (max-width:1180px){.crm-workspace{grid-template-columns:1fr;}.quick-grid{grid-template-columns:repeat(4,minmax(0,1fr));}}
