    align-items: center;
    white-space: nowrap;
    border-radius: 999px;
    padding: 0.2rem 0.55rem;
    font-size: 0.68rem;
    font-weight: 850;
    color: #065f46;
    background: #fff4e8;
}

.fo-step-body p {
    margin: 0.45rem 0 0;
    font-size: 0.84rem;
    line-height: 1.5;
    color: #6b7280;
}

.fo-step-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 0.45rem;
    margin-top: 0.75rem;
}

.fo-step-meta span {
    display: inline-flex;
    align-items: center;
    border-radius: 0.65rem;
    padding: 0.3rem 0.55rem;
    font-size: 0.72rem;
    font-weight: 800;
    color: #374151;
    background: #ffffff;
    border: 1px solid rgba(148, 163, 184, 0.28);
}

