    display: flex;
    flex-direction: column;
    gap: 0.18rem;
    border-radius: 0.85rem;
    padding: 0.75rem;
    background: rgba(248, 250, 252, 0.78);
    border: 1px solid rgba(148, 163, 184, 0.2);
}

.fo-summary-list span {
    font-size: 0.72rem;
    font-weight: 850;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: #6b7280;
}

