    width: max-content;
    max-width: 100%;
    padding: 5px 9px;
    border-radius: 999px;
    background: rgba(100, 116, 139, .1);
    color: #475569;
    font-size: 12px;
    font-weight: 850;
    white-space: nowrap;
}

.prazzu-pill.ok {
    background: rgba(34, 197, 94, .12);
    color: #15803d;
}

.prazzu-pill.muted {
    background: rgba(148, 163, 184, .14);
    color: #64748b;
}

.prazzu-badge.success {
    background: rgba(34, 197, 94, .12);
    color: #15803d;
}

.prazzu-badge.warning {
    background: rgba(245, 158, 11, .14);
    color: #b45309;
}

.prazzu-modal-cell {
