        .pc-file-row span { display:block; margin-top:.1rem; color:var(--pc-muted); font-size:.67rem; font-weight:800; }
        .pc-progress { height:.65rem; border-radius:999px; background:#e2e8f0; overflow:hidden; margin-top:.65rem; }
